window.__ENFELV__ = {"count": 213, "records": [{"year": 1970, "pmid": "18605433", "author": "Chapman AL", "n_authors": 3, "title": "Infection and transformation of dog cells with a modified sarcoma virus.", "abstract": "Dog-embryo cell cultures were infected with a mixture of feline leukemia virus (FelLV) and a modified murine (Moloney) sarcoma virus MSV(FelLV). Morphological alteration of the cells was observed 3 days post infection. Virus progeny from the infected cultures increased 50- to 100-fold in foci of cellular alteration on dog cell cultures pretreated with diethylaminoethyl-dextran, but only twofold on cat embryo cultures similarly treated. The numbers of foci produced corresponded to a dual infection with the MSV(FelLV) and endogenous FelLV and could be increased by simultaneous infection with exogenous FelLV. After five serial passages in dog cell cultures, the virus mixture still had a superior focus-inducing capacity on cat cells as compared with dog cells. Electron microscopic examination of infected dog cultures showed typical C-type virions. FelLV alone propagated in dog cell cultures without inducing morphological alteration, and progeny virus, capable of promoting focus formation by MSV(FelLV), could be detected 48 hours post infection.", "journal": "Journal of the National Cancer Institute", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1973, "pmid": "4357865", "author": "Benveniste RE", "n_authors": 2, "title": "Homology between type-C viruses of various species as determined by molecular hybridization.", "abstract": "Two strains of feline leukemia virus, two endogenous feline type-C viruses (RD/CCC group), several endogenous and laboratory strains of murine \"leukemia\" virus, two rat viruses, two primate viruses (woolly monkey and gibbon ape), as well as hamster, pig, and avian type-C viruses were examined for their relatedness to one another by molecular hybridization. The extent of nucleic-acid homology was determined by hybridization of the various viral RNAs to a [(3)H]DNA product synthesized from each virus. Among the murine type-C viruses (Rauscher, Kirsten, AT-124, and endogenous BALB/c virus) a high degree of homology is observed, although the viruses are not identical. The two primate viruses are also closely related to one another. The feline, rat, hamster, and pig endogenous viruses can be readily distinguished from one another and from the murine and primate viruses since their DNA products share very little or no nucleic-acid homology. However, the murine and primate type-C virus groups possess a surprising degree of relatedness. Feline type-C viruses fall into two distinct groups, the feline leukemia virus group and the RD-114/CCC group, with little detectable nucleic-acid homology between them. Infection of feline or rat cells with type-C virus results in production of the endogenous type-C virus of the species along with the infecting virus.", "journal": "Proceedings of the National Academy of Sciences of the United States of America", "doi": "10.1073/pnas.70.12.3316", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1973, "pmid": "4129928", "author": "Okabe H", "n_authors": 3, "title": "Specificity of the DNA product of RNA-dependent DNA polymerase in type C viruses. II. Quantitative analysis.", "abstract": "A number of mammalian Type C viruses were analyzed for relatedness by the technique of DNA.RNA hybridization. Viral DNAs were prepared in single-stranded form from complexes with 70S viral RNA formed during endogenous polymerase reactions. Extent of hybridization was assayed with the single-strand nuclease (S-1) from Aspergillus oryzae. Results obtained indicated a high degree of viral specificity, with significant cross-reactions being observed only with viruses obtained from within a species, as in the case of mouse and cat viruses, or in the special case of woolly monkey-gibbon comparisons. Comparisons of RD-114 virus, recently determined to be of feline origin, and conventional feline Type C viruses (FeLV), revealed minimal relatedness, especially when feline virus was grown on human cells, thus indicating the possibility of coexistence of greatly disparate Type C viruses within one species. A rat-specific virus, recovered from tumors induced by murine sarcoma virus, was found to contain genetic material common to both the original mouse virus and viruses indigenous to the rat, even though only rat-specific proteins have been detected during infection by this virus.", "journal": "Proceedings of the National Academy of Sciences of the United States of America", "doi": "10.1073/pnas.70.12.3923", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1973, "pmid": "4358162", "author": "East JL", "n_authors": 4, "title": "Structural characteristics and nucleotide sequence analysis of genomic RNA from RD-114 virus and feline RNA tumor viruses.", "abstract": "The results of molecular hybridization experiments have demonstrated that the RNA genome of RD-114 virus has extensive nucleotide sequence homology with the RNA genome of Crandell virus, an endogenous type C virus of cats, but only limited homology with the RNA genomes of feline sarcoma virus and feline leukemia virus. The genomic RNAs of RD-114 virus and Crandell virus also had identical sedimentation coefficients of 50S. A structural rearrangement of genomic RNA did not exist within released RD-114 virions, whereas a structural rearrangement of genomic RNA did occur within feline sarcoma virions and feline leukemia virions after release from virus-producing cells.", "journal": "Journal of virology", "doi": "10.1128/JVI.12.5.1085-1091.1973", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1974, "pmid": "4134740", "author": "Hellman A", "n_authors": 7, "title": "Baboon virus isolate M-7 with properties similar to feline virus RD-114.", "abstract": "A virus (M-7) isolated from baboon placental tissue demonstrates many similarities to endogenous feline virus RD-114. Immunodiffusion analysis shows a group-specific antigen (gs-1) line of identity between M-7 and RD-114. Anti-RD-114 DNA polymerase IgG inhibits M-7 polymerase by 57% compared to 97% for RD-114. M-7 virus has helper activity as demonstrated by rescue of murine sarcoma virus (MSV) from sarcoma-positive leukemia-negative human amnion cells. The host range of the rescued M-7 pseudotype of MSV, MSV (M-7), is similar to that of RD-114 virus. MSV (M-7) is also able to transform baboon cells and causes no detectable transformation of feline cells without addition of helper feline leukemia virus. Interference properties of M-7 and RD-114 virus are identical. Virus-specific neutralizing antisera, although partially cross-reacting, can distinguish MSV (M-7) from MSV (RD-114). These similarities and differences between RD-114 and M-7 viruses are best explained as type-specific differences between two viruses within the same strain.", "journal": "Journal of virology", "doi": "10.1128/JVI.14.1.133-138.1974", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1975, "pmid": "52892", "author": "Benveniste RE", "n_authors": 3, "title": "Evolution of type C viral genes: origin of feline leukemia virus.", "abstract": "Reiterated gene sequences related to the RNA of feline leukemia virus (FeLV) are detected in all tissues of domestic cats and their close Felis relatives but not in more distantly related Felis species. Partially homologous viral gene sequences are found in rodent, and particularly rat, DNA. Together with the immunologic relationships observed between FeLV and endogenous rodent type C viruses, the results lead to the conclusion that FeLV-related genes were transmitted from a rodent to cat ancestor and have been perpetuated in the germ line of cats.", "journal": "Science (New York, N.Y.)", "doi": "10.1126/science.52892", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1975, "pmid": "171336", "author": "Fischinger PJ", "n_authors": 4, "title": "Two levels of restriction by mouse or cat cells of murine sarcoma virus coated by endogenous xenotropic oncornavirus.", "abstract": "Mouse and cat cells were each examined for the mode of restriction of endogenous xenotropic oncornavirus. Murine xenotropic helper virus (MuX) and its pseudo-type of Moloney murine sarcoma virus (MSV(MuX)) were grown in cat cells to high titre. MuX alone did not replicate in any mouse cell tested including normal or transformed outbred Swis 3T3 cells or SC-I cells, but did grow in a variety of other mammalian cells. MSV(MuX) was not able to achieve that intracellular state from which it could be rescued by mouse leukaemia virus (MuLV) in any mouse cell tested with the exception of SC-I cells. Detection of MSV(MuX) foci with appropriate helper virus was as sensitive in SC-I cells as in the cells of several other species. Sequential passage of MSV(MuX) virus complex in SC=I cells resulted in a loss of infectious sarcoma and helper viruses, but transformed, MSV rescuable cells were retained. If cat embryo cells were infected with either the feline endogenous xenotropic virus (FeX) or its MSV pseudotype (MSV(FeX), two analogous states of restriction were observed. FeX alone did not replicate in cat cells as measured by release of progeny virus or by FeX group-specific antigen induction. Cat cells could be susceptible or insusceptible to the entry of MSV(FeX) as measured by MSV rescue with appropriate ecotropic feline leukaemia virus. The sensitivity of detection of MSV(FeX) foci in some cat cells in the presence of feline ecotropic virus was comparable to that exhibited by cells of other mammalian species. A single strain of cat cells underwent a change in its restrictive capacity for MSV(FeX) on prolonged passage. Late passage cat cells became very insusceptible to MSV(FeX) but not to other pseudotypes of MSV. Infectious FeX or its group-specific antigens were not detected in the insusceptible cells. The major glycoprotein of FeX did appear as a surface antigen of the insusceptibel cells. It is apparent that two levels of cellular restriction can be distinguished in each of two mammalian cell systems by the susceptibility to penetration of MSV coated with endogenous xenotropic oncornavirus.", "journal": "The Journal of general virology", "doi": "10.1099/0022-1317-29-1-51", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1975, "pmid": "51882", "author": "Hino S", "n_authors": 3, "title": "Antigenic determinants of the 70,000 molecular weight glycoprotein of woolly monkey type C RNA virus.", "abstract": "The 70,000 molecular weight glycoprotein (gp70) of a type-C RNA virus originally isolated from a woolly monkey has been partially purified and immunologically characterized. Evidence that this viral protein is viral coded was derived from studies showing its antigenic properties to be unaltered by virus passage in cells of different species. A broadly reactive competition immunoassay was developed utilizing antiserum prepared against feline leukemia virus to precipitate 125I-labeled woolly monkey virus gp70. Gibbon and woolly viruses, as well as feline and several mouse type-C viruses, all reacted with equal efficiency in this assay. In contrast, an endogenous virus of the baboon failed to cross-react, suggesting that viruses of this latter group are less immunologically related to the others. In a homologous competition immunoassay for the woolly viral glycoprotein, the woolly virus was readily distingusihed from otherwise colsely related viruses of gibbon apes. These findings demonstrate the pronounced type-specific antigenic dterminants possessed by this viral protein. The antigenic determinants of gp70 responsible for neutralization have also been investigated.", "journal": "Journal of immunology (Baltimore, Md. : 1950)", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1975, "pmid": "50133", "author": "Olsen RG", "n_authors": 3, "title": "Antibody in cats to mammalian RNA tumor virus interspecies antigens.", "abstract": "The studies were undertaken to determine whether the cat, a mammalian species that carries xenotropic endogenous C-type virus(es) and in addition undergoes horizontally transmitted oncogenic C-type RNA tumor virus infections, responds immunologically to the mammalian C-type virus interspecies antigens. Sera from normal cats and from cats with spontaneous or virus-induced neoplasms were examined for antibodies to interspecies antigen antigen by complement-fixation inhibition, by inhibition of the paired radioiodine-labeled antibody technique (PRILAT inhibition), and by two-step radioimmunoelectrophoresis. Using three separate complement-fixation inhibition systems designed to detect antibodies to interspecies antigen(s), 23 of 23 sera from tumor-bearing cats and 24 of 31 sera from normal cats were positive in both systems. The negative sera were from germ-free cats. Among the 49 positive sera, 47 yielded titers of 1:16 or greater by one or more complement-fixation inhibition tests. Of these 47 sera, 42 were positive by the paired radioiodine-labeled antibody technique inhibition test; the 5 paired radioiodine-labeled antibody technique-negative sera were from normal specific-pathogen-free cats. Direct reaction with the interspecies determinant on the p30 protein from Rauscher murine leukemia virus by immunoglobulin from cats immunized with feline leukemia virus was shown by two-step radioimmunoelectrophoresis. The feline antibody was also identified as an immunoglobulin by column chromatography and two-step radioimmunoelectrophoresis. These antibodies did not fix guinea pig complement during reaction with the interspecies antigen. That other mammals may produce similar noncomplement-fixing (guinea pig) antibodies to RNA tumor virus antigens is likely.", "journal": "Cancer research", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1975, "pmid": "49443", "author": "Sherr CJ", "n_authors": 4, "title": "Interspecies antigenic determinants of the reverse transcriptases and p30 proteins of mammalian type C viruses.", "abstract": "The major internal structural proteins (p30) of type C viruses isolated from several mammalian species were studied by radioimmunoprecipitation and competitive radioimmunoassays. Three antigenically distinguishable sets of interspecies determinants could be demonstrated by both methods. One set of determinants shared by viruses of rodent origin (mouse and rat) can be detected readily in feline leukemia viruses but not in other type C viral groups. The p30 proteins of murine viruses also contain a second discrete set of antigenic determinants related to those in infectious primate viruses and endogenous porcine viruses, but not detected in the feline leukemia virus group. The p30 proteins of endogenous viruses of baboons and domestic cats share yet a third set of cross-reactive determinants not detected in type C viruses isolated from other species of animals. Enzyme inhibition studies performed with antisera raised toward the reverse transcriptases of these same groups of type C viruses showed the same patterns of immunological cross-reactions as observed with p30 proteins. The antigenic cross-reactions between the homologous proteins of type C virus isolated from genetically distant animals may reflect transmission of type C viruses across species barriers.", "journal": "Journal of virology", "doi": "10.1128/JVI.15.6.1440-1448.1975", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1976, "pmid": "60495", "author": "Sherr CJ", "n_authors": 4, "title": "Type C viruses from Kirsten sarcoma-transformed mink cells co-cultivated with primate cells and expressing p30 antigens related to feline leukemia virus.", "abstract": "Two type C viruses with new antigenic and biological properties were isolated by co-cultivating secondary cell strains established from the kidneys of a baboon (Papio papio) and a patas monkey (Erythrocebus patas) with mink cells non-productively transformed by Kirsten sarcoma virus. Both new isolates (designated PP-1R and EP-1R) contain major structural proteins (p30) that are immunologically most closely related to the p30 proteins of feline leukemia viruses. The reverse transcriptases of both viruses, although antigenically related to polymerases of murine and rat type C viruses, are distinct from those of previously described type C viral groups. Both PP-1R and EP-1R can be transmitted to canine and feline cells and to sarcoma virus-transformed, but not normal, mink cells. Both viruses contain RNA genomes partially homologous to those of endogenous mouse and rat type C viruses and the Kirsten sarcoma virus. In addition, the RNA of PP-1R contains a portion of the nucleic acid sequences found in a type C virus isolated from the baboon species P. papio. We propose that both new isolates are genetic recombinants formed between endogenous primate type C viral genomes and sequences found in Kirsten sarcoma-transformed mink cells.", "journal": "Journal of virology", "doi": "10.1128/JVI.19.2.346-358.1976", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1976, "pmid": "181753", "author": "Aoki T", "n_authors": 5, "title": "Natural antibodies in sera from healthy humans to antigens on surfaces of type C RNA viruses and cells from primates.", "abstract": "Sera from healthy humans contained naturally occurring antibody against group- or subgroup-specific antigen on the envelope of the following type C viruses isolated from primates: gibbon ape leukemia virus, simian (woolly monkey) sarcoma virus, baboon endogenous type C virus, and putative human type C viruses [HL23V isolated from blood cells of a patient with acute myelogenous leukemia (HL23) and HEL-12V from human embryonic diploid cells (CIH-32)]. Two sera also reacted with C57BL/6 mouse leukemia induced by Friend virus. These results were obtained by indirect immunoelectron microscopy with various virus-producing cells and by absorption tests using as targets gibbon lymphosarcoma cells that release gibbon ape leukemia virus. In a previous report, the presence of natural antibody in sera from healthy gibbon apes was demonstrated. When the specificities of the human and gibbon natural antibodies were compared, the human natural antibody reacted with two nonproducing culture cell lines of human lymphocytic leukemia (CEM-A and MOLT) and with human embryonic diploid (CIH-1(V-) cells [which became type C virus-producing CIH-32(V+) cells after many passages], but did not react with normal gibbon spleen monolayer cells. In contrast, gibbon natural antibody showed no reaction with CEM-A, MOLT, and CIH-1(V-) cells but reacted with gibbon spleen monolayer cells. Neither human nor gibbon natural antibody that was reactive with gibbon ape leukemia virus crossreacted with feline leukemia virus and mouse wild-type AKR leukemia virus. The gibbon lymphosarcoma cells releasing gibbon ape leukemia virus were used in a screening study of sera from healthy humans. Out of 72 sera screened by indirect immunoelectron microscopy using this system, 55 were positive (76%), i.e., 26 out of 35 males (74%) and 29 out of 37 females (78%). The highest incidence of antibody production was in 1- to 10-year-olds and 31- to 40-year-olds, with the adults exhibiting higher levels. Differences in incidence of natural antibody were not found to be sex-linked. These findings suggest that type C RNA viruses related to the gibbon ape leukemia virus and simian (woolly monkey) sarcoma virus family as well as the baboon endogenous type C virus family may be widespread in humans.", "journal": "Proceedings of the National Academy of Sciences of the United States of America", "doi": "10.1073/pnas.73.7.2491", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1976, "pmid": "178890", "author": "Frankel AE", "n_authors": 3, "title": "Fractionation of DNA nucleotide transcripts from Moloney sarcoma virus and isolation of sarcoma virus-specific complementary DNA.", "abstract": "Radioactive DNA complementary to nucleotide sequences in Moloney murine sarcoma virus (MSV) and Moloney leukemia virus (M-MuLV) complex was made by the endogenous reverse transcriptase reaction. These virus stocks contained a threefold excess of MSV over M-MuLV as measured by biological assay. The complementary DNA was an accurate copy of the viral RNA in that 86% of 35S viral RNA hybridized with complementary (cDNA) DNA at a 1.5 to 1 cDNA-RNA molar ratio. The complementary DNA, of a 4-6S size, was fractionated by sequential absorptions with MulV and the feline leukemia virus pseudotype of MSV, [MSV(FeLV)] RNA. In this manner three sets of nucleotide sequences whichrepresent different portions of the MSV viral complex were obtained: a sarcoma virus-specific fraction (cDNAsarc) with sequences that had no homology to M-MuLV RNA but which hybridized to MSV (FeLV) RNA, a sarcoma-leukemia fraction (cDNA common) with sequences common to MSV as well as M-MuLV viral RNA, and a cDNAleuk representing those nucleotide sequences found only in M-MuLV. Hybridization of MSV-MuLV viral 35S RNA with a threefold molar excess of cDNA's revealed that approximately 20% was hybridized with cDNAsarc, whereas approximately 75% was hybridized with cDNAcommon. M-MuLV 35S RNA alone did not hybridize with cDNAsarc but did hybridize 40 and 50% with cDNAleuk and cDNAcommon, respectively. The cDNAsarc represents about 25% of the total MSV sequences, whereas the cDNAcommon represents the remainder of the MSV virus genome. Some cDNAcommon sequences were shared by two other sarcoma viruses and several distinctly different isolates of MulV. In contrast, the MSV \"sarc\" sequences had little or no homology with two other murine sarcoma virus isolates.", "journal": "Journal of virology", "doi": "10.1128/JVI.18.2.481-490.1976", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1976, "pmid": "176414", "author": "Charman HP", "n_authors": 5, "title": "Humoral immune responses of cats to feline leukemia virus: comparison of responses to the major structural protein p30 and to a virus-specific cell membrane antigen (FOCMA).", "abstract": "Radioimmunoprecipitation was used to test cat sera for ability to bind to the purified major internal protein p30 of feline leukemia viurs (FeLV), to the endogenous cat virus (RD-114), and to murine leukemia virus (MuLV). The data were compared with results of tests for antibody to the feline oncornavirus-associated cell membrane antigen FOCMA and for the presence of viremia. In contrast to the general lack of free antibody to FeLV p30 in a random sample of healthy cats, high levels of antibody to FeLV p30 and FOCMA were found in normal animals from high-leukemia-cluster households. Titers of greater than or equal to 200 for p30 and greater than or equal to 32 for FOCMA were found in nonviremic animals; a percentage of animals with high FOCMA titers and lower or no p30 binding activity were viremic. Animals with neoplasms were low or negative for FOCMA antibody and did not have high titers of free p30 antibody. The p30 binding activity could be divided into three main categories: high binding with FeLV p30 and much lower activity with RD-114 and MuLV p30's, as seen with hyperimmune sera; high binding with FeLV and RD-114 p30's and low activity with MuLV p30, possibly indicative of specific antibody to both of the aforementioned proteins; and low level binding to all three p30's.", "journal": "Journal of the National Cancer Institute", "doi": "10.1093/jnci/56.4.859", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1977, "pmid": "72739", "author": "Calafat J", "n_authors": 3, "title": "Feline malignant mammary tumors. III. Presence of C-particles and intracisternal A-particles and their relationship with feline leukemia virus antigens and RD-114 virus antigens.", "abstract": "Thirty-six feline mammary tumors were examined by the electron microscope, and by the indirect immunofluorescence (IFA) test with anti-FeLV and anti-RD-114 serum. In 11 (30.6%) tumors intracisternal A-particles (IAP) were found. One of these tumors contained a few particles with an electron-dense nucleoid in the cisternae of the endoplasmic reticulum. In 7 (19.4%) other tumors C-particles were found and in the remaining 18 (50.0%) no particles at all could be detected. In 11 (30.6%) tumors FeLV antigens and in 20 (55.5%) tumors RD-114 virus antigens were present. In 9 (25%) tumors we found a high (greater than 1/64) and in 11 (30.6%) tumors a low (greater than 1/16 less than or equal to 1/64) titer. There was a good correlation between the presence of C-particles and the demonstration of FeLV-antigen but none between IAP and FeLV antigens. No correlation was found between RD-114 virus antigens and any type of particle. Morphologically, the IAP found in feline mammary tumors were indistinguishable from the IAP present in mammary tumors of some inbred mice strains. The IAP in feline mammary tumors possibly represent an endogenous virus, different from RD-114 virus. The role of these viruses in the etiology of feline mammary tumors is discussed.", "journal": "International journal of cancer", "doi": "10.1002/ijc.2910200516", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1977, "pmid": "198602", "author": "Schäfer W", "n_authors": 1, "title": "[Model studies on virus-induced tumors and their immunological treatment (author's transl)].", "abstract": "After a review of the general biological properties of C-type oncorna viruses, results are presented on the structure of an exogenous murine leukemia virus (FLV) and on the serobiological properties of its structural proteins. Our findings suggested a major role of the viral surface glycoprotein gp71 in immunological defense mechanisms. This was confirmed by vaccination experiments with isolated gp71 in mice. The induced immunity was highly specific and not operative against endogenous murine C-viruses belonging to other serotypes. Surprisingly the latter were found to be activated by the vaccination with gp71 of FLV. In heterologous animal species isolated FLV-gp71 induced the formation of broadly reacting antibodies. They were found to be effective in the therapy of infections with FLV in mice as well as with feline leukaemia virus in cats. Most impressive results were obtained with an antiserum prepared against feline leukaemia virus in a goat. This serum completely suppressed sarcomas induced by infection with feline sarcoma virus.", "journal": "Klinische Wochenschrift", "doi": "10.1007/BF01491299", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1977, "pmid": "197261", "author": "Niman HL", "n_authors": 4, "title": "Endogenous RD-114 virus genome expression in malignant tissues of domestic cats.", "abstract": "Endogenous xenotropic cat type C virus (RD-114)- and infectious feline leukemia virus (FeLV)-specific gene expressions were measured in spontaneous sarcomas carcinomas, and nonmalignant cat tissues by molecular hybridization for virus-specific RNA and competition radio-immunoassays for the major internal protein (p30) of these two viruses. The results indicate that RD-114 gene expression in sarcomas and carcinomas at both RNA and p30 levels is significantly higher than histologically normal tissues from cats free of cancer. In contrast, the levels of FeLV viral RNA and p30 are fount to be low or undetectable in the majority of these tumored and normal tissues examined. Whereas variability in the amounts of RD-114 OR FeLV RNA and p30 expressed is found in tissues from different cats, their expression is fairly uniform in multiple malignant tissues of the same cat. The finding of widespread occurrence of elevated RD-114 gene expression in sarcomas and carcinomas is consistent with our similar observation with natural lymphomas of domestic cats and suggests that expression of certain functions of this endogenous virus may be etiologically involved in the development of many different spontaneous neoplasms of cats.", "journal": "Journal of virology", "doi": "10.1128/JVI.23.3.578-586.1977", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1977, "pmid": "191415", "author": "Gardner MB", "n_authors": 11, "title": "FeLV epidemiology in Los Angeles cats: Appraisal of detection methods.", "abstract": "We investigated the reliability of the fixed cell indirect fluorescent antibody (IFA) peripheral blood smear test as an index of systemic infection with FeLV. Positive results with this test were found to correlate well with detectable FeLV p30 antigen in bone-marrow smears by IFA, in serum and tissue by competition immunoassays, and with type-C particles in bone marrow or spleen by electron microscopy. Most cats with lymphoma, anemia or infectious peritonitis were positive for FeLV and showed a poor or absent antibody response to FeLV p30, gp70, and FOCMA antigens. Most older cats with lymphoma, carcinoma, or sarcoma were negative for FeLV expression and also lacked these FeLV-related antibodies. Detectable immunologic response to FeLV p30 and gp70 proteins and a high-titered FOCMA antibody response were generally restricted to certain healthy cats exposed to FeLV. Antibody to endogenous RD-114 viral p30 and gp70 was not detected in any of a large number of feline sera tested. The prevalence of FeLV-related diseases and immunologic responses to FeLV in healthy cats was directly correlated with the degree of FeLV exposure. By using the IFA blood smear and FOCMA antibody tests one can monitor the horizontal spread of FeLV in multi-cat household and accurately predict the FeLV disease susceptibilty or resistance of individual cats in each environments.", "journal": "International journal of cancer", "doi": "10.1002/ijc.2910190420", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1977, "pmid": "66679", "author": "Smith HS", "n_authors": 3, "title": "Expression of antigenic crossreactivity to RD114 p 30 protein in a human fibrosarcoma cell line.", "abstract": "An antigen crossreacting with the 30,000-molecular-weight protein (p30) of the feline endogenous oncornavirus (RD114) was detected in a well-characterized human fibrosarcoma cell line, HT1080, by indirect immunofluorescence. Three antisera against RD114 p30 gave similar positive results, while two antisera prepared against simian sarcoma virus p30, one antiserum prepared against murine leukemia virus p30, and one antiserum prepared against feline leukemia virus p30 gave no immunofluorescence. The reactivity observed with the antiserum against RD114 p30 was detected in 10-40% of the cells at early passages and was no longer expressed by the forty-first subculture. The reactivity could be removed by adsorption of the antiserum with RD114-infected dog or human cells, but not by uninfected cells or by cells infected with an antigenically unrelated oncornavirus, feline leukemia virus. Neither complete virus particles nor reverse transcriptase (RNA-dependent DNA nucleotidyltransferase) activity was detected in the culture. These experiments suggest that the fibrosarcoma cell line is expressing an antigen related to the p30 protein of RD114 baboon endogenous virus group of oncornaviruses without producing complete virions.", "journal": "Proceedings of the National Academy of Sciences of the United States of America", "doi": "10.1073/pnas.74.2.744", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1978, "pmid": "210130", "author": "Okabe H", "n_authors": 4, "title": "A portion of the feline leukaemia virus genome is not endogenous in cat cells.", "abstract": "Although viral sequences closely related to feline leukaemia virus are represented in multiple copies in cellular DNA of all domestic cats, a specific fraction was present only in the virus-infected cells. This fraction was detected by viral cDNA enriched by a prior absorption of a total complementary DNA (cDNA) transcript with normal cat liver DNA. The recycled cDNA hybridized well with the cellular DNA of virus-infected cells, but to a lesser extent with DNA from uninfected cat cells. The probe was used to differentiate virus-positive from virus-negative tumour tissues of cats. The same approach with cDNA of another endogenous feline virus, RD114, failed to show any difference between a virus-infected cell line and normal cells, including both virus-inducible and non-inducible lines.", "journal": "International journal of cancer", "doi": "10.1002/ijc.2910220114", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1978, "pmid": "76684", "author": "Sherr CJ", "n_authors": 3, "title": "Endogenous mink (Mustela vison) type C virus isolated from sarcoma virus-transformed mink cells.", "abstract": "A previously described type virus stock (designated PP-1R), isolated by cocultivating baboon cells with mink cells transformed by Kirsten sarcoma virus (64J1), has been further cloned and characterized. End point-diluted stocks of PP-1R have been obtained that are free of focus-forming activity and lack both Kirsten sarcoma and primate type C viral sequences. Nucleic acid hybridization experiments show that the cloned virus (MiLV) is an endogenous, genetically transmitted virus of the mink (Mustela vison). MiLV replicates in canine, feline, and 64J1 mink cells but not in an untransformed mink cell line. Multiple viral gene copies can be detected in the DNA of normal mink cells in culture and in normal mink tissues; related endogenous viral genes are also detected in several related Mustela species. The virus codes for a p30 protein very closely related antigenically to that of feline leukemia virus but contains p15 and p12 proteins that are antigenically distinct. The mink cell line, Mv1Lu, and its Kirsten sarcoma-transformed derivatives, 64J1, express relatively low levels of type C viral RNA related to MiLV and normally do not produce detectable levels of MiLV p30 protein or complete, infectious viral particles. Infection of sarcoma virus-transformed mink cells with baboon type C virus, however, can augment the level of expression of endogenous mink viral RNA and can result in the synthesis and packaging of mink viral RNA and p30 antigen in extracellular virions. Since the Mv1Lu cell line and its tranformed derivatives have become widely used in studies of retroviruses, the possibility of activating endogenous mink viral genes should be considered by investigators working with these cells.", "journal": "Journal of virology", "doi": "10.1128/JVI.25.3.738-749.1978", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1978, "pmid": "201591", "author": "Okabe H", "n_authors": 4, "title": "Reiteration frequency of feline type C viral genomes in homologous and heterologous host cell DNA.", "abstract": "Differences in the multiplicity of proviral sequences of two feline endogenous viruses, RD-114 and FeLV, in homologous and heterologous host DNA were examined by viral cDNA hybridization using cellular DNA fractionated with respect to reiteration frequency. The endogenous proviral DNAs in cat cells were fractionated predominantly with intermediate-repeated sequences, while RD-114 proviral DNA in virus-infected human cells was fractionated together with unique-sequence DNA. These differences were consistent with the results of kinetic analysis using unfractionated DNA.", "journal": "Intervirology", "doi": "10.1159/000148943", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1979, "pmid": "92319", "author": "Jurjus A", "n_authors": 4, "title": "Placenta-bound immunoglobulins.", "abstract": "Low pH eluates were prepared from trophoblasts derived from 8 term human placentas. A qualitative analysis for immunoglobulins revealed the presence of IgG, IgA, and IgM in these eluates. IgC-rich fractions were obtained by DEAE-cellulose chromatography of ammonium sulfate-concentrated eluates. These fractions were able to neutralize, in vitro, the catalytic activity of reverse transcriptases (RT) from several retroviruses. RT from baboon endogenous virus (BEV) seemed to be more susceptible to the neutralizing activity of some eluates. This was in contrast to RT from feline leukemia virus (FeLV) which were neutralized by eluates of leukocytes from chronic myelogenous leukemia. In contrast to previous and present results with purified IgG from leukemic leukocytes, the purified IgG from placenta eluates was incapable of RT neutralization. However, such purified IgG fractions inhibited mixed lymphocyte reactions.", "journal": "Arthritis and rheumatism", "doi": "10.1002/art.1780221120", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1979, "pmid": "291976", "author": "Bernstein A", "n_authors": 4, "title": "Presence and expression of Friend erythroleukemia virus-related sequences in normal and leukemic mouse tissues.", "abstract": "The nature and distribution of sequences related to the murine erythroleukemia virus, Friend spleen focus-forming virus (SFFV), have been analyzed by using a radioactive cDNA probe specific for the SFFV genome (cDNA(sff)). From the proportion of high molecular weight viral [(32)P]RNA which hybridized to cDNA(sff), it was estimated that these sequences represent about 50% of the SFFV genome, indicating a genetic complexity of about 3300 nucleotides. cDNA(sff) hybridized extensively (80-95%) to SFFV virion RNA and to cellular RNA from murine and rat cells productively or nonproductively infected with SFFV. Only background homology was detected between cDNA(sff) and viral RNA from a number of murine [Friend murine leukemia virus (MuLV), Moloney-MuLV, and Kirsten sarcoma virus] and nonmurine (Rous sarcoma virus, feline leukemia virus, baboon endogenous virus, and Mason-Pfizer mammary tumor virus) retroviruses. Limited homology was also detected to a number of murine xenotropic and mink cell focus-inducing viruses (20-35%) as well as Rauscher leukemia virus (50%). Nucleotide sequences homologous to cDNA(sff) were also detected in the DNA of normal cells of several mouse strains as single or a few copies per cell. Thermal denaturation analysis indicated that duplexes formed between cDNA(sff) and normal DBA/2J cellular DNA have a reduction in melting temperature of 2 degrees C when compared with the dissociation of hybrids between cDNA(sff) and homologous sequences in SFFV-infected mouse spleen cell DNA. Examination of cellular RNA from uninfected mouse cells indicated that SFFV-related RNA sequences were also expressed in varying degrees in different tissues of adult DBA/2J mice. The highest amounts were observed in cells from bone marrow and spleen, whereas considerably lower amounts were found in cells from the thymus and kidney. No SFFV-related sequences could be detected in RNA extracted from liver, muscle, or fibroblasts. The presence of these SFFV-related sequences in normal, uninfected mouse cell DNA and their differential expression in hematopoietic tissues suggest that these sequences may be an integral part of the program of both normal and leukemic hematopoietic cell differentiation.", "journal": "Proceedings of the National Academy of Sciences of the United States of America", "doi": "10.1073/pnas.76.9.4455", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1979, "pmid": "222681", "author": "Mandel MP", "n_authors": 4, "title": "Endogenous RD-114 virus of cats: absence of antibodies to RD-114 envelope antigens in cats naturally exposed to feline leukemia virus.", "abstract": "Healthy cats, including those exposed to feline leukemia virus in leukemia cluster households, lack evidence of humoral immunity to virion surface antigens of the endogenous RD-114 virus.", "journal": "Infection and immunity", "doi": "10.1128/iai.24.1.282-285.1979", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1979, "pmid": "83351", "author": "Ahmed M", "n_authors": 7, "title": "Characterization of a retrovirus isolated from normal mink cells co-cultivated with a dog mammary tumour.", "abstract": "A retrovirus antigenically distinct from known type C, B and D viruses was isolated from normal mink (Mustela vison) lung cells that had been co-cultivated with 5-iododeoxyuridine- and dexamethasone-treated dog mammary tumour cells. Cytogenetic studies of the virus-releasing co-culture showed mitotic figures identical to the normal mink cell line (MvlLu) with the exception of a low frequency of cells with extensive chromosomal breakage and uncoiling. The new virus bands at a buoyant density of 1.16 g/ml, contains 60S RNA and a reverse transcriptase which prefers Mn2+ over Mg2+ for the synthesis of DNA. This enzyme utilizes poly(rA).oligo(dT) more efficiently than poly(dA).oligo(dT) and is also able to synthesize DNA copies from the endogenous RNA. Morphologically, it is a typical type C virus. Filtered virus readily infects mink, dog and other mammalian cells indicating the amphotropic nature of its cell growth requirement. Hybridization studies showed that normal mink DNA contains multiple copies of proviral sequences of this newly isolated virus. Serological analyses indicate that the mink endogenous virus contains in its core protein, in addition to the interspecies type-C determinant, an antigenic component related to one of the determinants found in the feline leukaemia virus p30 protein. This determinant is not present in the Rauscher leukaemia virus, RD114 virus or simian sarcoma virus.", "journal": "The Journal of general virology", "doi": "10.1099/0022-1317-42-1-179", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1980, "pmid": "6262439", "author": "Kimball PC", "n_authors": 2, "title": "Three sizes of subunits in RNAs from feline sarcoma-leukaemia virus mixtures.", "abstract": "RNA from the Snyder-Theilen feline sarcoma-leukaemia virus complex (ST-FeSV-FeLV) sedimented in a double-peaked band between 50 and 70S, but Gardner-Arnstein (GA) FeSV-FeLV RNA sedimented in a single 70S peak. FeLV isolated from the ST virus mixture contained RNA which sedimented in a 70S band like GA-FeSV-FeLV RNA, but F422 FeLV RNA sedimented more slowly, at 50 to 60S. After thermal denaturation, resedimentation revealed three classes of RNA subunits in ST-FeSV-FeLV RNA: the first class, 35 to 37S, was also found in ST-FeLV and other FeLVs (except F422 FeLV), in the endogenous feline virus, RD114 and in GA-FeSV-FeLV; the second class, 32 to 34S, was similar to subunits in F422 FeLV and minor components of GA-FeSV-FeLV and ST-FeLV; the third class, 25S, was detected only in ST-FeSV-FeLV RNA. Electrophoresis of RNA species in buffered formamide provided evidence that the three classes of RNA subunits distinguishable on the basis of sedimentation rates actually represent three size classes of subunits. The ST virus mixture was shown to contain about equal titres of infectious FeLV and transforming FeSV whereas GA-FeSV-FeLV had at least a 10-fold excess fo FeLV over FeSV. These observations are discussed in terms of possible origins of the three sizes of FeSV-FeLV RNA subunits and their relationships to three species of FeSV-FeLV proviral DNA described recently (Sherr et al. 1979).", "journal": "The Journal of general virology", "doi": "10.1099/0022-1317-51-2-295", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1980, "pmid": "6248115", "author": "Waters LC", "n_authors": 4, "title": "Differential association of transfer RNAs with the genomes of murine, feline and primate retroviruses.", "abstract": "The tRNAs that are bound to the genomic RNAs of several murine, feline, and primate retroviruses have been identified. Transfer RNAs were divided into those loosely bound and those tightly bound by stepwise thermal dissociation of the 70 S RNA. They were then identified and semiquantitated by aminoacylation. Proline tRNA is the most tenaciously bound tRNA in several strains of murine leukemia virus, two strains of feline leukemia virus, and the primate viruses simian sarcoma, baboon endogenous, and gibbon ape lymphoma. In the feline xenotropic virus, RD-114, tRNAGly is enriched in the most tightly bound fraction. In Mason-Pfizer monkey virus, as in the murine mammary tumor virus, tRNALys is the tRNA most tenaciously bound to its genomic RNA. Besides the most tightly associated tRNA, one or more different tRNAs are found in relatively large amounts in association with the 70 S RNA. (For convenience, we refer to the largest RNA ccomplex (50-70 S) isolated from any of the retroviruses studies as '70 S' RNA.) These tRNAs can be distinguished from the most tightly bound tRNA by the fact that they can be dissociated at lower temperatures. However, they occur in the same relative abundance as the tightly bound tRNA.", "journal": "Biochimica et biophysica acta", "doi": "10.1016/0005-2787(80)90139-2", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1980, "pmid": "6247824", "author": "Koshy R", "n_authors": 3, "title": "Characterization of the endogenous feline leukemia virus-related DNA sequences in cats and attempts to identify exogenous viral sequences in tissues of virus-negative leukemic animals.", "abstract": null, "journal": "Virology", "doi": "10.1016/0042-6822(80)90202-0", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1980, "pmid": "6244200", "author": "Schneider J", "n_authors": 3, "title": "Search for mammalian type-C retrovirus polypeptides on infected animal cells and human tumor cell lines using interspecies-reacting antibodies.", "abstract": "Cells producing endogenous and exogenous type-C retroviruses of murine, feline and primate origin were evaluated for expression of those virus-specific cell-surface antigens which cross-react with antibodies to interspecies determinants of mammalian type-C viral polypeptides. Surface polypeptides of cells replicating endogenous and exogenous type-C retroviruses were iodinated by the lactoperoxidase method. Labelled antigens were immunoprecipitated and analyzed in polyacrylamide gel electrophoresis in the presence of sodium dodecyl sulfate. This method detected gp71 and less frequently p15E/p12E on the surface of virus-producing cells; in addition, p27 was found on F422 cells replicating feline leukemia virus. Antibodies to the membrane protein p15E displayed the broadest cross-reactivity but only antibodies to gp71 mediated complement-dependent interspecies cell lysis. The pattern of cross-reactivity reflected known genetic relationships among these mammalian viruses. Although antiserum to the simian sarcoma virus complex (SSV) was strongly cytotoxic to some human tumor cell lines, this reactivity could not be attributed to antibodies cross-reacting with SSV gp71.", "journal": "Experimental cell biology", "doi": "10.1159/000162979", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1981, "pmid": "6278488", "author": "Casey JW", "n_authors": 7, "title": "The U3 portion of feline leukemia virus DNA identifies horizontally acquired proviruses in leukemic cats.", "abstract": "The presence and location of DNA sequences related to the U3 and U5 portions of the infectious exogenous feline leukemia virus (FeLV) long terminal repeat (LTR) in various cat DNAs have been determined by hybridization experiments. In uninfected cat DNAs, the U5 LTR segment from the Gardner-Arnstein strain B virus is present at approximately 150 copies per cell. This level is approximately 10-fold greater than that of endogenous internal FeLV sequences. The U5 sequences differ in copy number and, to some extent, in location from one animal to another. For any one animal, the sequence organization of the U5 segments is the same among different tissues, showing that the pattern is inherited through the germ line. Most importantly, the viral U3 LTR probe hybridizes only very weakly with uninfected cat DNAs. Both the U3 and the U5 regions of the LTR from the Gardner-Arnstein strain of virus cross-hybridize with DNA derived from four other infectious FeLVs representing A, B, and C subtypes. Thus, the C3 region may be used as a probe for studying the number and location of exogenously acquired FeLV proviruses in infected cat tissues. In some cases exogenously acquired proviruses are present in unique sites in the genome of virus-positive cat lymphosarcomas, indicating a monoclonal origin for the tumor. In other tumors, the proviral sequences are randomly distributed over many sites. Lymphosarcomas of virus-negative cats have no exogenous U3 sequences despite epidemiological evidence of an association of virus-negative leukemia with exposure to FeLV.", "journal": "Proceedings of the National Academy of Sciences of the United States of America", "doi": "10.1073/pnas.78.12.7778", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1981, "pmid": "6270364", "author": "Fischinger PJ", "n_authors": 4, "title": "Selective host range restriction of goat cells for recombinant murine leukemia virus and feline leukemia virus type A.", "abstract": "We isolated a strain of normal goat fibroblasts which was uniquely selective in that it allowed the replication of xenotropic murine leukemia virus but not polytropic recombinant murine leukemia virus. In addition, feline leukemia virus type A replication was severely diminished in these goat cells, whereas feline leukemia virus type B and feline endogenous RD114-CCC viruses replicated efficiently. No other known cells exhibit this pattern of virus growth restriction. These goat cells allow the study of xenotropic murine leukemia virus in mixtures which also contain recombinant murine leukemia virus and may be helpful in eliminating feline leukemia virus type which often coexists in feline sarcoma or leukemia virus mixtures with other feline leukemia virus types.", "journal": "Journal of virology", "doi": "10.1128/JVI.39.3.981-985.1981", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1982, "pmid": "7129681", "author": "Rhim JS", "n_authors": 3, "title": "Neoplastic transformation of rabbit cells by murine sarcoma viruses.", "abstract": "Neoplastic transformation of rabbit cells by Kirsten murine sarcoma virus (Ki-MSV), the Ki-MSV pseudotype of baboon endogenous virus (Ki-MSV[BaEV]) and the Moloney-MSV pseudotype of feline leukemia virus (M-MSV[FeLV]) is reported. Rabbit cells can be readily transformed by Ki-MSV, Ki-MSV(BaEV) and M-MSV(FeLV). Rabbit cells transformed by Ki-MSV and M-MSV(FeLV) were found to be virus producers, whereas those transformed by Ki-MSV(BaEV) were nonproducers (NP). The NP cells were obtained by simply infection rabbit cells with Ki-MSV(BaEV) and subculturing the infected cells. Although the morphologically altered NP cells did not produce infectious virus or murine leukemia virus antigen, they did contain a rescuable MSV genome. All of the transformed cells formed colonies in soft agar, grew to high saturation densities and produced tumors when transplanted into nude mice. The Ki-MSV and M-MSV(FeLV)-transformed cells produced tumors in newborn WH/J rabbits, thus providing an important tool for studying tumor immunity in the rabbit.", "journal": "International journal of cancer", "doi": "10.1002/ijc.2910300318", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1982, "pmid": "6284972", "author": "Cohen M", "n_authors": 4, "title": "DNA sequence relationship of the baboon endogenous virus genome to the genomes of other type C and type D retroviruses.", "abstract": "Baboon endogenous virus (BaEV) is a type C retrovirus present in multiple proviral copies in the DNA of baboons. Although interspecies antigenic determinants present on reverse transcriptase and gag proteins are shared among all mammalian type C viruses, no nucleic acid homology between BaEV and other type C viruses (except RD-114) has been found in conventional liquid hybridization experiments. In this study, we used restriction fragments of cloned BaEV DNA immobilized on nitrocellulose to test for relatedness with [(32)P]cDNA's of various type C and type D viruses. We detected the following distant relationships previously found only through immunological and protein sequencing techniques: (i) eight type C viral cDNA's (the endogenous virus of rhesus monkeys, feline leukemia virus, simian sarcoma virus, gibbon ape leukemia virus, Rauscher murine leukemia virus, BALB-2, NZB, and RD-114) and two type D viral cDNA's (Mason-Pfizer monkey virus and squirrel monkey retrovirus) were able to hybridize with cloned BaEV DNA; (ii) the eight type C probes hybridized to restriction fragments spanning most of the BaEV genome, but only RD-114 hybridized to fragments within the 1.9 kilobases at the 3' end of the genome; (iii) the two type D probes hybridized primarily to fragments within the 1.9 kilobases at the 3' terminus and weakly or not at all elsewhere; and (iv) [(32)P]cDNA's of several other oncornaviruses (mouse mammary tumor virus, equine infectious anemia virus, bovine leukemia virus, and reticuloendotheliosis virus) exhibited no homology with BaEV DNA. DNA sequence analysis has allowed us to orient the BaEV restriction map with the genetic map at both ends of the genome. Homologies between retroviral cDNA's and BaEV clone restriction fragments could thus be related to specific BaEV genes. Whereas type C cDNA's hybridized to fragments from gag, pol, and the pol-env junction, squirrel monkey retrovirus cDNA hybridized only to a fragment coding for the p15E portion of env. Mason-Pfizer monkey virus cDNA also hybridized within the p15E region, but exhibited homology to the 3' half of gp70 as well. These results are discussed relative to previously reported antigenic relatedness of retroviral proteins. The data suggest that BaEV represents an important link in oncornavirus evolution.", "journal": "Journal of virology", "doi": "10.1128/JVI.41.3.801-812.1982", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1983, "pmid": "6850643", "author": "Rasheed S", "n_authors": 1, "title": "Characterization of a differentiated cat melanoma cell line.", "abstract": "We have established several long-term cultures of a naturally occurring metastatic melanoma of a domestic cat. The cells are fully differentiated as indicated by the Fontana-Masson staining of the melanin in the perinuclear region and by electron microscopy of the cytoplasmic melanosomes in various stages of development. The melanoma cells do not produce virus particles or the major core proteins (i.e., protein with a molecular weight of 30,000) of the feline leukemia virus or the endogenous cat virus RD-114. Retrovirus is also not induced when melanoma cultures are treated with 5-iodo-2'-deoxyuridine or bromodeoxyuridine and cocultivated with susceptible cells. Treatment of cells with N6,O2'-dibutyryl cyclic adenosine 3' :5'-monophosphate or theophyllin, however, accentuates melanin production and increases the number of pigmented cells. The cultured cells develop melanotic tumors in s.c. inoculated newborn cats and athymic nude mice. As far as we can ascertain, this is the first report of a spontaneous malignant melanoma of a cat which provides an important resource for studying cell differentiation in vitro.", "journal": "Cancer research", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1983, "pmid": "6304345", "author": "Soe LH", "n_authors": 4, "title": "Molecular cloning and characterization of endogenous feline leukemia virus sequences from a cat genomic library.", "abstract": "Recombinant bacteriophage lambda clones from a cat genomic library derived from placental DNA of a specific pathogen-free cat were screened to identify endogenous feline leukemia virus (FeLV) sequences. Restriction endonuclease mapping of four different clones indicates that there are a number of similarities among them, notably the presence of a 6.0- to 6.4-kilobase pair (kbp) EcoRI hybridizing fragment containing portions of sequences homologous to the gag, pol, env, and long terminal repeat-like elements of the infectious FeLV. The endogenous FeLV sequences isolated are approximately 4 kbp in length and are significantly shorter than the cloned infectious FeLV isolates, which are 8.5 to 8.7 kbp in length. The endogenous elements have 3.3- to 3.6-kbp deletions in the gag-pol region and approximately 0.7- to 1.0-kbp deletions in the env region. These deletions would render them incapable of encoding an infectious virus and may therefore be related to the non-inducibility of FeLV from uninfected cat cells and the subgenomic expression of these endogenous sequences in placental tissue. It appears that there is conservation in the ordering of restriction sites previously reported in the proviruses of the infectious FeLVs in sequences corresponding to the pol and env boundary as well as the region spanning the env gene of the endogenous clones, whereas a greater divergence occurs among restriction sites mapped to the gag and part of the pol regions of the infectious FeLV. Such deleted, FeLV-related subsets of DNA sequences could have originated either by germ-line integration of a complete ecotropic virus followed by deletion, or by integration of a preexisting, defective, deleted variant of the infectious virus.", "journal": "Journal of virology", "doi": "10.1128/JVI.46.3.829-840.1983", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1983, "pmid": "6300313", "author": "Stiff MI", "n_authors": 2, "title": "Effects of retrovirus protein on the feline one-way mixed leukocyte reaction.", "abstract": "The objective of this study was to evaluate the effects of feline retrovirus protein on cat lymphocyte recognition of allogeneic cells in the mixed leukocyte reaction (MLR), using u.v.-inactivated feline leukaemia virus (FeLV) and a non-disease-producing endogenous cat virus (RD-114). Twenty micrograms of u.v.-inactivated virus protein from each virus were added to mixed leukocyte cultures. FeLV induced significant suppression of the MLR (P less than 0.005) whereas no significant suppression was found using RD-114. Since feline leukaemia infection is associated with immunosuppression, the retrovirus proteins may be interfering with the response of immunocompetent cells when they are confronted with an altered host cell.", "journal": "The Journal of general virology", "doi": "10.1099/0022-1317-64-4-957", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1983, "pmid": "6329934", "author": "Busch MP", "n_authors": 6, "title": "Characterization of the expression of cellular retrovirus genes and oncogenes in feline cells.", "abstract": "Expression of endogenous retrovirus genes and two different cellular oncogenes (c-onc genes) was examined at the transcriptional level in a variety of normal and lymphoma/leukemia tissues of the domestic cat. The two oncogenes, c-myb(related to avian myeloblastosis virus) and c-myc(related to avian myelocytomatosis virus) were selected for their association with the induction of hematopoietic malignancies, when present in the transforming retroviruses. Tissue-specific expression of endogenous feline leukemia virus (FeLV)-related genes was detected in cellular subpopulations of the cat placenta by in situ method of hybridization. Gel blotting analysis of placental poly(A)-selected RNA revealed that the FeLV-related RNA species were primarily subgenomic, representing the env gene region of the endogenous provirus elements. Like the endogenous retrovirus genes, c-myb and c-myc loci of the cat genomic DNA were also transcribed at differential levels in normal tissues of the cat. Dot-blot hybridization analysis showed that the expression of these two oncogenes was linked to growth and development as it varied with the gestational age of the fetus and from fetal to adult tissues. Among the major hematopoietic organs, spleen and bone marrow contained both c-myb and c-myc transcripts, while thymus preferentially expressed the c-myb gene. In contrast to the low level of c-myc expression in fetal thymus tissues, enhanced c-myc expression was detected in all five thymomas tested and also in several other neoplasms including two granulocytic leukemias. The feline c-myb gene was not very active in granulocytic leukemias or in three of the five thymomas. RNA gel blotting analysis of poly(A)-selected RNA of a thymoma and its lymph node metastasis showed identical pattern of c-myc transcripts.", "journal": "Hematological oncology", "doi": "10.1002/hon.2900010108", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1983, "pmid": "6299244", "author": "Pal BK", "n_authors": 2, "title": "Mink type C virus: biochemical characterization of the structural polypeptides.", "abstract": "Mink type C virions contained six major protein species of approximate M.W. of 90,000, 70,000, 30,000, 15,000, 12,000 and 10,000. The two largest polypeptides were glycosylated and the 12,000 M.W. polypeptide was the major phosphoprotein of the virion. Two-dimensional tryptic peptide map of the 30,000 M.W. major structural protein of MiLV showed a pattern distinct from those of analogous proteins from mouse and endogenous cat type C viruses. Significant peptide homology of this protein was, however, found with the corresponding protein of infectious feline type C virus (FeLV).", "journal": "Archives of virology", "doi": "10.1007/BF01314138", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1983, "pmid": "6197953", "author": "Goldschmied-Reouven A", "n_authors": 3, "title": "Hamster endogenous retrovirus (HaER)--distinct properties of structural proteins and DNA polymerase.", "abstract": "The structural proteins as well as some features of the RNA-dependent DNA polymerase of the hamster endogenous retrovirus (HaER) were examined. The polypeptide pattern of this virus is substantially different from that of other known retroviruses in containing major polypeptides with molecular weights of 68,000, 59,000, 27,000 and 24,000 daltons. Double antibody competitive radioimmunoassays showed that the HaER particles do not share any detectable antigenic relatedness with the murine viruses' p30, but manifest a considerable relatedness with the feline leukemia virus p27 and a slight cross-reactivity with the rat virus major protein. The RNA-dependent DNA polymerase of HaER virus has a molecular size of approximately 73,000 daltons and in contrast to other mammalian retroviruses shows no significant preference for Mn2+ over Mg2+. Apart from the lack of antigenic relatedness between the HaER virus proteins and the p30 protein of murine viruses, there is also no antigenic relatedness between HaER and murine viruses insofar as their DNA polymerase is concerned.", "journal": "Archives of virology", "doi": "10.1007/BF01311319", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1984, "pmid": "6090693", "author": "Reeves RH", "n_authors": 2, "title": "Molecular genetic characterization of the RD-114 gene family of endogenous feline retroviral sequences.", "abstract": "RD-114 is a replication-competent, xenotropic retrovirus which is homologous to a family of moderately repetitive DNA sequences present at ca. 20 copies in the normal cellular genome of domestic cats. To examine the extent and character of genomic divergence of the RD-114 gene family as well as to assess their positional association within the cat genome, we have prepared a series of molecular clones of endogenous RD-114 DNA segments from a genomic library of cat cellular DNA. Their restriction endonuclease maps were compared with each other as well as to that of the prototype-inducible RD-114 which was molecularly cloned from a chronically infected human cell line. The endogenous sequences analyzed were similar to each other in that they were colinear with RD-114 proviral DNA, were bounded by long terminal redundancies, and conserved many restriction sites in the gag and pol regions. However, the env regions of many of the sequences examined were substantially deleted. Several of the endogenous RD-114 genomes contained a novel envelope sequence which was unrelated to the env gene of the prototype RD-114 env gene but which, like RD-114 and endogenous feline leukemia virus provirus, was found only in species of the genus Felis, and not in other closely related Felidae genera. The endogenous RD-114 sequences each had a distinct cellular flank which indicates that these sequences are not tandem but dispersed nonspecifically throughout the genome. Southern analysis of cat cellular DNA confirmed the conclusions about conserved restriction sites in endogenous sequences and indicated that a single locus may be responsible for the production of the major inducible form of RD-114.", "journal": "Journal of virology", "doi": "10.1128/JVI.52.1.164-171.1984", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1984, "pmid": "6197475", "author": "Markenson JA", "n_authors": 2, "title": "Reactivity of antisera to endogenous primate retrovirus with a human T cell membrane protein: recognition of a nonviral glycoprotein by antibodies directed only against carbohydrate components.", "abstract": "A glycosylated protein of approximately 70,000 daltons (gp70) from the surface of human peripheral blood T cells was immunoprecipitated by antisera to the baboon endogenous retrovirus (BEV-M7) and the serologically related feline endogenous retrovirus (RD114) but not by antisera to other retroviruses. Whereas preliminary absorption experiments were consistent with a possible viral specificity for this reaction, detailed biochemical and serologic characterization of the purified cellular protein suggested that it was not related to the gp70 of either M7 or RD114 viruses. The specificity of the reaction was further analyzed by assays of cellular gp70 antigenicity after exposure to exo- and endoglycosidases or trypsin and carbohydrate hapten inhibition studies. The results of these experiments were consistent with the interpretation that the glycoprotein was being recognized by antibody binding to the carbohydrate moiety of the molecule. These results provide an example of an antibody activity that could lead to inappropriate conclusions when sensitive radioimmunoprecipitation techniques are used for the biochemical analysis of antigenic systems. They emphasize the necessity of purifying cellular antigens as a prerequisite to determining the exact basis for a serologic reaction.", "journal": "Journal of immunology (Baltimore, Md. : 1950)", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1984, "pmid": "6097827", "author": "Hlubinová K", "n_authors": 5, "title": "Purification and protein composition of endogenous rat viruses.", "abstract": "Endogenous retroviruses are not in the majority of cases the cause of any neoplasia, except for the laboratory conditions. As far as they might serve for the evolution of pathogenic retroviruses more attention should have been paid to them. In this paper we introduce some approaches to the purification of rat endogenous retroviruses to such a degree of purity that enabled satisfactory SDS-PAGE analysis of its structural proteins. Purities of samples obtained by usual purification methods, long-term isopycnic centrifugation at a high gravity force and velocity centrifugation are compared. Protein profile of rat endogenous virus in SDS-PAGE is compared with the ones of other retroviruses. For the first time the evidence was obtained for the striking similarity between electrophoretic protein profile of rat endogenous virus WERC and feline leukemia virus. The major structural proteins of rat endogenous retrovirus and feline leukemia virus cannot be distinguished even when resolution long gradient PAGE had been employed. The accordance of electrophoretic mobilities of major structural proteins in SDS-PAGE can indicate the relatedness of retroviruses.", "journal": "Neoplasma", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1985, "pmid": "2415715", "author": "Soe LH", "n_authors": 4, "title": "Molecular analysis of several classes of endogenous feline leukemia virus elements.", "abstract": "Five recombinant DNA clones of endogenous feline leukemia virus-related DNA sequences were isolated by screening a lambda phage genomic library of cat placental DNA with a probe specific to the gag-pol region of infectious feline leukemia virus. The clones containing retroviral long terminal repeat-like sequences demonstrated the existence of different size classes of endogenous elements in the cat genome, including those of nearly full length in which the gag region is heterogeneous but all of pol and most of env are highly conserved. Other size classes included elements with major deletions in gag or pol. A genomic DNA analysis suggested that the majority of endogenous elements were close to full length in size and that the highly truncated sequences which we described previously (Soe et al., J. Virol. 46:829-840, 1983) represented only a subset of the elements present. A restriction analysis of genomic DNA suggested a high degree of conservation in pol and the 5' portion of env among the various endogenous sequences present in the cat genome. We also found by using DNA transfection that while all of the endogenous clones were noninfectious, there was differential expression of the elements which we examined. These findings correlate with the subgenomic expression of endogenous feline leukemia virus sequences in cat placental tissue.", "journal": "Journal of virology", "doi": "10.1128/JVI.56.3.701-710.1985", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1985, "pmid": "2988377", "author": "Lewis MG", "n_authors": 7, "title": "Retroviral-associated eosinophilic leukemia in the cat.", "abstract": "Fourteen specific-pathogen-free cats were inoculated with a putative env gene recombinant feline retrovirus, PR8. An isolate of the Rickard strain of feline leukemia virus (FeLV-R), PR8, has the properties of both an exogenous (FeLV-R) and an endogenous (xenotropic) feline retrovirus (RD-114). Twelve of the PR8-inoculated cats developed viremia; 2 of the 12 cats developed eosinophilia, with 1 being diagnosed with eosinophilic leukemia and the other with extreme eosinophilic hyperplasia. Eosinophilic leukemia is rare in cats and has not previously been associated with retroviral infection. Changes in the viral envelope properties may have altered the pathogenicity of the exogenous virus to cause this rare form of leukemia.", "journal": "American journal of veterinary research", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1985, "pmid": "2983093", "author": "Haapala DK", "n_authors": 4, "title": "Isolation from cats of an endogenous type C virus with a novel envelope glycoprotein.", "abstract": "A search for variant endogenous cat viruses led to a novel isolate. Although the major envelope glycoprotein of this virus was similar in size to that of an RD-114-like virus that was coisolated, it was unrelated to RD-114 or feline leukemia virus by immunological and biological criteria. This degree of dissimilarity suggests a different evolutionary progenitor from that for the RD-114 and feline leukemia virus viral envelopes. The novel virus did, however, code for gag gene polypeptides which are closely related to RD-114 virus. Neither the novel isolate nor the RD-114-like coisolate induced foci in S+L- cat cells which restrict focus induction by RD-114 virus. This suggests that the two viruses share a common genomic target of restriction which resides outside of the env region.", "journal": "Journal of virology", "doi": "10.1128/JVI.53.3.827-833.1985", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1985, "pmid": "2989102", "author": "Wong TC", "n_authors": 4, "title": "The promoter of the long terminal repeat of feline leukemia virus is effective for expression of a mouse H-2 histocompatibility gene in mouse and human cells.", "abstract": "DNA-mediated gene transfer techniques have been used to study the effectiveness of a novel construction involving the feline leukemia virus long terminal repeat (FeLV LTR) for expressing the mouse H-2 Ld gene in mouse and human cells. In this construction, the transcription initiation (promoter) and termination (polyadenylation) functions of the FeLV LTR have been split by insertion of a promoterless H-2 gene between them. An S1 nuclease assay has been developed that makes it possible to measure accumulated LdRNA against a background of endogenous major histocompatibility antigen RNAs in mouse and human cells. In mouse cells, the H-2 Ld gene was expressed at approximately equal levels (measured as accumulated RNA) when driven either by its own promoter or by the FeLV LTR construction. In human cells, expression at the RNA level was highest when driven by the FeLV LTR. We conclude that the FeLV LTR construction is useful for expressing foreign genes in human cells.", "journal": "Gene", "doi": "10.1016/0378-1119(85)90291-4", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1986, "pmid": "3009890", "author": "Stewart MA", "n_authors": 7, "title": "Nucleotide sequences of a feline leukemia virus subgroup A envelope gene and long terminal repeat and evidence for the recombinational origin of subgroup B viruses.", "abstract": "Molecular clones of the subgroup A feline leukemia virus FeLV-A/Glasgow-1 have been obtained. Nucleotide sequence analysis of the 3' end of the proviral genome and comparison with the published sequence of FeLV-B/Gardner-Arnstein showed that the most extensive differences are located within the 5' domain of the env gene. Within this domain, several divergent regions of env are separated by more conserved segments. The 3' end of env is highly conserved, with only a single amino acid coding difference in p15env. The proviral long terminal repeats are also highly conserved, differing by only eight base substitutions and one base insertion. Specific probes constructed from the FeLV-A or FeLV-B env genes were used to compare the env genes of various exogenous FeLV isolates and the endogenous FeLV-related proviruses of normal cat DNA. An FeLV-A-derived env probe showed no hybridization to normal cat DNA but detected all FeLV-A and FeLV-C isolates tested. In contrast, an FeLV-B env probe detected independent FeLV-B isolates and a family of endogenous FeLV-related proviruses. Our observations provide strong evidence to support the hypothesis that FeLV-B viruses have arisen by recombination between FeLV-A and endogenous proviral elements in cat DNA.", "journal": "Journal of virology", "doi": "10.1128/JVI.58.3.825-834.1986", "deposited_data": "Sim", "nuccore_ids": "323912", "bioproject_ids": null, "sra_ids": null}, {"year": 1987, "pmid": "2821968", "author": "Beyer W", "n_authors": 5, "title": "Molecular cloning of an endogenous cat retroviral element (ECE 1)--a recombinant between RD-114 and FeLV-related sequences. Brief report.", "abstract": "A lambda L 47.1 clone library was constructed from BamHI digests of cellular cat DNA and was screened with cDNA probes specific for the 3'-terminus of the replication competent RD-114 virus. The first analysis of one clone (lambda-ECE 1) shows that it consists at least of a 3'-LTR and a 5' adjacent env gene. The LTR nucleotide sequences of the RD-114 cDNA clones and ECE 1 are identical within the R region and unrelated to FeLV. Otherwise, the region upstream from the 3'-LTR of ECE 1 shows homology to the transmembrane protein encoding gene of FeLV, but not to RD-114. These results imply that ECE 1 is a recombinant between an RD-114-like 3'-LTR and a FeLV-related env portion.", "journal": "Archives of virology", "doi": "10.1007/BF01320971", "deposited_data": "Sim", "nuccore_ids": "163878", "bioproject_ids": null, "sra_ids": null}, {"year": 1988, "pmid": "2843665", "author": "Berry BT", "n_authors": 5, "title": "Structure and function of endogenous feline leukemia virus long terminal repeats and adjoining regions.", "abstract": "The nucleotide sequence of the 5' long terminal repeat (LTR) of three independent loci (CFE-6, CFE-16, and CF-14) of endogenous feline leukemia virus (FeLV) DNAs of the domestic cat genome was determined. The 3' LTR of the CFE-6 clone was also sequenced. The endogenous FeLV LTRs, which were very similar to each other in sequence and in organization of the functional domains, differed considerably from the exogenous FeLV LTR in the U3 region. The major differences in U3 included variations in sets of small (14 to 19 base pair) direct repeats, altered location of the simian virus 40 core enhancer-like sequence, and occurrence of three segments of largely nonhomologous sequences. There was extensive homology between endogenous and exogenous FeLV LTRs in sequences beginning from the TATA box through the R region down to the 3' end of the U5 region. The DNA sequence downstream of the 5' LTR encompassing the primer-binding site, leader, and almost to the end of the p15gag coding region, a point up to which the sequencing was carried out, also revealed a high degree of conservation. However, the detection of frameshift and nonsense mutations in this region of a nearly full-length endogenous provirus sequence (CFE-6) predicted its defectiveness and correlated with the lack of infectivity of this DNA. The functional studies of the endogenous LTRs, based on linkage to the bacterial cat gene and transient expression in feline cell lines, indicated that although the basic characteristics for promotion and enhancement of transcription were retained in each LTR, there was a significant variation in the activity of the cat constructs. Reconstruction and deletion analyses with the CFE-6 5' LTR revealed the presence of strong transcription regulatory sequences in the 702-base-pair region immediately upstream of the 5' boundary of the endogenous LTR. These and related data suggest that in addition to the transcription-modulating elements occurring within the LTR, the cis-acting nucleotide sequences in the upstream cellular DNA may determine the overall efficiency of transcription of the defective endogenous FeLV provirus loci of the felid genome.", "journal": "Journal of virology", "doi": "10.1128/JVI.62.10.3631-3641.1988", "deposited_data": "Sim", "nuccore_ids": "163819, 163818, 163817", "bioproject_ids": null, "sra_ids": null}, {"year": 1988, "pmid": "2895894", "author": "Overbaugh J", "n_authors": 4, "title": "Transduction of endogenous envelope genes by feline leukaemia virus in vitro.", "abstract": "Feline leukaemia viruses (FeLV) are exogenous retroviruses that can be detected in most cats with leukaemia, aplastic anaemia, myeloproliferative diseases and fatal immunosuppression. FeLV isolates have been divided into three subgroups, based on the viral envelope-determined properties of interference and host range in vitro. FeLV-A is present in all natural isolates and is generally minimally pathogenic. FeLV-B is found with FeLV-A in isolates from approximately 40% of natural infections and in a higher percentage of cats with lymphoma. Following the fundamental observations of genetic reassortment of avian retroviruses with endogenous viral genes and the origination of lymphomagenic viruses during the ontogeny of AKR mice, we show here that transfection of feline cells with FeLV-A DNA results in its recombination with endogenous FeLV-related sequences to produce viruses with the structural and host range properties of FeLV-B. Thus in vitro propagation of a retrovirus may result in the generation of variants with very different properties.", "journal": "Nature", "doi": "10.1038/332731a0", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1989, "pmid": "2539525", "author": "Kumar DV", "n_authors": 3, "title": "Nucleotide sequence and distinctive characteristics of the env gene of endogenous feline leukemia provirus.", "abstract": "Nucleotide sequence analysis of the env gene of two different endogenous feline leukemia virus (FeLV) loci, CFE-6 and CFE-16, of domestic cats revealed the following characteristics. (i) Both proviruses contain an open reading frame in the env region; (ii) whereas the full complement of the exogenous FeLV env is generally present in CFE-6 DNA, it is truncated in CFE-16 DNA such that the 5' half of the gp70 domain and the untranslated region 3' to the p15E domain have been fused by an internal deletion, resulting in loss of the C-terminal half of the gp70- and all of the p15E-coding sequences; (iii) endogenous env is highly homologous to large sequence domains conserved in all three exogenous FeLV subgroups (A, B, and C) but is similar to FeLV-B sequence domains in the variable regions detected in these viruses; and (iv) there are four other sequence domains, one residing at the C terminus of gp70 and three scattered in p15E, which are unique for the endogenous env, thereby distinguishing it from the FeLV-B gene.", "journal": "Journal of virology", "doi": "10.1128/JVI.63.5.2379-2384.1989", "deposited_data": "Sim", "nuccore_ids": "163851, 163849", "bioproject_ids": null, "sra_ids": null}, {"year": 1990, "pmid": "2165140", "author": "Levy LS", "n_authors": 5, "title": "An unusual retrovirus-like sequence identified in human DNA.", "abstract": "The human genome contains many different types of endogenous proviruses and retrovirus-like elements. An unusual element of this kind has been isolated from human DNA on the basis of its relatedness to the integrase-coding domain of the pol gene of feline leukaemia virus (FeLV). The element, termed Hs5, is related to FeLV only over a short region of 81 nucleotides predicted to encode the carboxyl terminus of the FeLV integrase protein, p46pol. The region of relatedness between Hs5 and FeLV identifies a short conserved amino acid stretch which is shared among distantly related retroviruses. The conservation of this sequence, its position, and predicted secondary structure suggest that it may represent a conserved substrate binding site or active site of the integrase enzyme. Nucleotide sequence analysis of Hs5 reveals that it is not an intact retrovirus, but contains only the 3' terminus of pol and a defective env gene without apparent long terminal repeat; Hs5 is unusual among human endogenous retrovirus-like elements in this respect.", "journal": "The Journal of general virology", "doi": "10.1099/0022-1317-71-7-1613", "deposited_data": "Sim", "nuccore_ids": "220062", "bioproject_ids": null, "sra_ids": null}, {"year": 1990, "pmid": "2161827", "author": "Cheney CM", "n_authors": 8, "title": "A feline large granular lymphoma and its derived cell line.", "abstract": "A lymphoma cell line (MCC) was derived from an abdominal mass from a 13-yr-old castrated male cat. The cells resemble natural killer precursor cells, have membrane-bound granules, and are positive for chloroacetate esterase, alpha-naphthyl butyrate esterase, and tartrate-resistant acid phosphatase activities. The MCC cells are negative for rearranged feline T-cell receptor genes, negative for feline T-cytotoxic antigen, Ia, and surface mu, tau, and lambda chains and do not form E-rosettes. The MCC cell line is negative for the feline leukemia virus (FeLV); e.g., negative for exogenous FeLV (exU3) sequences, negative for cytoplasmic and surface FeLV major core protein of 27,000 daltons (p27) by indirect immunofluorescence assay, negative for helper FeLV by clone 81 assay, and negative for release of soluble FeLV p27 by enzyme-linked immunosorbent assay. Electron microscopy reveals budding type C retrovirus particles and MCC cells react with anti-RD-114 (anti-endogenous feline retrovirus) reference serum. After in vitro infection, MCC replicate FeLV readily, but replication is noncytopathic.", "journal": "In vitro cellular & developmental biology : journal of the Tissue Culture Association", "doi": "10.1007/BF02624087", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1990, "pmid": "1691887", "author": "Sommerfelt MA", "n_authors": 2, "title": "Receptor interference groups of 20 retroviruses plating on human cells.", "abstract": "The types of receptors on the surfaces of human and other mammalian cells for 13 C-type and 7 D-type retrovirus strains were determined by interference to the formation of syncytia and the plating of viral pseudotypes. All the D-type simian retroviruses (SRV-1-5, SMRV, PO-1-Lu) share a common receptor which is also utilized by the baboon and cat endogenous C-type viruses (BaEV, RD114). Syncytial cross-interference was also observed in human cells between the gibbon ape leukemia/simian sarcoma associated viruses (GALV/SSAV) and feline leukemia virus subgroup B (FeLV-B). Amphotropic and xenotropic murine leukemia viruses (MLV-A, MLV-X), bovine leukemia virus (BLV), and FeLV-C infect human cells via unique cell surface receptors. Human T-cell leukemia viruses types 1 and 2 (HTLV-1, HTLV-2) share a common receptor with related chimpanzee and simian viruses (STLV). Thus seven distinct receptor groups were delineated on human cells for C-type and D-type retroviruses.", "journal": "Virology", "doi": "10.1016/0042-6822(90)90230-o", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1990, "pmid": "2155287", "author": "Tzavaras T", "n_authors": 7, "title": "Molecular cloning and characterization of a defective recombinant feline leukaemia virus associated with myeloid leukaemia.", "abstract": "The GM1 strain of feline leukaemia virus (FeLV) was isolated from a naturally occurring case of myeloid leukaemia and induces severe haematopoietic abnormalities, including myeloblastic leukaemia, on inoculation into cats. Molecular clones of FeLV-GM1 proviruses were obtained and studied by restriction enzyme mapping, blot hybridization and partial DNA sequence analysis. Two types of clone were isolated; the first was a replication-competent FeLV of subgroup A, resembling other low or minimally pathogenic FeLV-A isolates; the second was replication-defective with extensive deletions and mutations in gag and pol, although it has an intact env gene of subgroup B phenotype. Large segments of the defective proviruses, from the 5' leader sequence upstream of the gag gene to the 5' half of the env gene, show structural hallmarks of endogenous FeLV-related proviruses. Infectious FeLV-GM1 viruses recovered after transfection were tested for their leukaemogenic potential in newborn cats. Early polyclonal myeloproliferative changes were observed in cats inoculated with FeLV-A/GM1 alone, although these were more pronounced in animals receiving the full FeLV-AB/GM1 complex reconstituted by cotransfection of the defective virus FeLV-B with its FeLV-A helper. Analysis of viruses in the bone marrow showed that replication of the subgroup B component is delayed and restricted to a proportion of cats. Most of the infected cats developed persistent abnormalities of haematopoiesis and one progressed to disseminated myeloid leukaemia. The defective recombinant FeLV-B/GM1 appears to play an indirect but important role in myeloid leukaemogenesis.", "journal": "The Journal of general virology", "doi": "10.1099/0022-1317-71-2-343", "deposited_data": "Sim", "nuccore_ids": "221268", "bioproject_ids": null, "sra_ids": null}, {"year": 1991, "pmid": "1724122", "author": "Swenson CL", "n_authors": 5, "title": "Prophylactic and therapeutic effects of phosphonoformate against feline leukemia virus in vitro.", "abstract": "Phosphonoformate (PFA), a noncompetitive inhibitor of reverse transcriptase (RT), inhibited feline leukemia virus (FeLV) infection of 2 feline cell lines and inhibited progeny virus RT activity in a chronically FeLV-infected cell line. Feline leukemia virus infection of 3201 cells, an FeLV-negative lymphoma cell line, was inhibited by greater than 70% at a concentration of only 1 microM PFA and by greater than 90% at concentrations of 64 to 256 microM PFA, as evidenced by RT activity. However, FeLV antigen expression by 3201 cells remained relatively constant over noncytotoxic concentrations of PFA. Because the persistence of viral antigen expression with concomitant suppression of RT activity appears to be unique and because 3201 cells express small amounts of an endogenous retrovirus (RD-114) and contain endogenous FeLV proviral sequences, a possible role of endogenous retroviruses acting as helper viruses was suggested. Feline leukemia virus infection of 81C cells, a sarcoma-positive, leukemia-negative fibroblast cell line, was inhibited by greater than 50% at a concentration of 64 microM PFA and by greater than 98% at concentrations of 256 to 512 microM PFA, as indicated by suppression of focus formation. The feline lymphoid cell line FL-74 is a large producer of FeLV. When FL-74 cells were cultured in the presence of 256 microM PFA, virus production (virus budding and viral antigen) was not affected, but progeny virus lost RT activity and infectivity. Direct addition of PFA (256 microM) to FeLV also reduced RT activity and infectivity. These data indicate that PFA can directly and rapidly inactivate retrovirus independent of cellular processing, presumably by inhibiting RT.(ABSTRACT TRUNCATED AT 250 WORDS)", "journal": "American journal of veterinary research", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1991, "pmid": "1658356", "author": "Pandey R", "n_authors": 6, "title": "Recombination between feline leukemia virus subgroup B or C and endogenous env elements alters the in vitro biological activities of the viruses.", "abstract": "An important question in feline leukemia virus (FeLV) pathogenesis is whether, as in murine leukemia virus infection, homologous recombination between the infecting FeLV and the noninfectious endogenous FeLV-like proviruses serves as a significant base for the generation of proximal pathogens. To begin an analysis of this issue, several recombinant FeLVs were produced by using two different approaches: (i) the regions of the viral envelope (env) gene of a cloned FeLV (subgroup B virus [FeLV-B], Gardner-Arnstein strain) and those of two different endogenous proviral loci were exchanged to create specific FeLV chimeras, and (ii) vectors containing endogenous env and molecularly cloned infectious FeLV-C (Sarma strain) DNA sequences were coexpressed by transfection in nonfeline cells to facilitate recombination. The results of these combined approaches showed that up to three-fourths of the envelope glycoprotein (gp70), beginning from the N-terminal end, could be replaced by endogenous FeLV sequences to produce biologically active chimeric FeLVs. The in vitro replication efficiency or cell tropism of the recombinants appeared to be influenced by the amount of gp70 sequences replaced by the endogenous partner as well as by the locus of origin of the endogenous sequences. Additionally, a characteristic biological effect, aggregation of feline T-lymphoma cells (3201B cell line), was found to be specifically induced by replicating FeLV-C or FeLV-C-based recombinants. Multiple crossover sites in the gp70 protein selected under the conditions used for coexpression were identified. The results of induced coexpression were also supported by rapid generation of FeLV recombinants when FeLV-C was used to infect the feline 3201B cell line that constitutively expresses high levels of endogenous FeLV-specific mRNAs. Furthermore, a large, highly conserved open reading frame in the pol gene of an endogenous FeLV provirus was identified. This observation, particularly in reference to our earlier finding of extensive mutations in the gag gene, reveals a target area for potentially productive homologous recombination upstream of the functional endogenous env gene.", "journal": "Journal of virology", "doi": "10.1128/JVI.65.12.6495-6508.1991", "deposited_data": "Sim", "nuccore_ids": "163853", "bioproject_ids": null, "sra_ids": null}, {"year": 1992, "pmid": "1336243", "author": "Egberink H", "n_authors": 2, "title": "Animal immunodeficiency viruses.", "abstract": "Feline immunodeficiency virus (FIV) has morphological, physical and biochemical characteristics similar to human immunodeficiency virus (HIV), the cause of AIDS in man. However, it is antigenically and genetically distinct from HIV; an antigenic relatedness with equine infectious anaemia virus has been demonstrated. FIV has been molecularly cloned and sequenced. Diagnostic tests are commercially available and attempts at preparing inactivated, subunit and molecularly engineered vaccines are being made in different laboratories. During FIV infection a transient primary illness can be recognized, with fever, neutropenia and lymphadenopathy. After a long period of clinical normalcy a secondary stage is distinguished with signs of an immunodeficiency-like syndrome. The incubation period for this stage can be as long as 5 years, during which gradual impairment of immune function develops. Many FIV-infected cats are presented for the first time showing vague signs of illness: recurrent fevers, emaciation, lack of appetite, lymphadenopathy, anaemia, leucopenia and behavioural changes. Later, the predominant clinical signs observed are chronic stomatitis/gingivitis, enteritis, upper respiratory tract infections, and infections of the skin. Neoplasias, neurological, immunological and haematological disorder are seen in a smaller proportion. The immunodeficiency-like syndrome is progressive over a period of months to years. Concomitant infection with feline leukaemia virus has been shown to accelerate the progression of disease. In vitro, phenotypic mixing between FIV and an endogenous feline oncovirus (RD114) has been demonstrated which leads to a broadening of the cell spectrum of the lentivirus. Bovine immunodeficiency virus (BIV) has been isolated only once, and all attempts to obtain additional isolates have failed; it has been recovered from the leucocytes of cattle with persistent lymphocytosis, lymphadenopathy, lesions in the central nervous system, progressive weakness and emaciation. As with the feline representative, BIV also was found to possess a lentivirus morphology and to encode a reverse transcriptase with Mg++ preference; it replicates and induces syncytia in a variety of embryonic bovine tissues in vitro. Antigenic analyses have demonstrated a conservation of epitopes between the major core protein of BIV and HIV. The original isolate has been molecularly cloned and sequenced. Besides the three large open reading frames (ORFs) comprising the gag, pol, and env genes common to all replication-competent retroviruses, five additional small ORFs were found. Numerous point mutations and deletions were found, mostly in the env-encoding ORF. These data suggest that, within a single virus isolate, BIV displays extensive genomic variation.(ABSTRACT TRUNCATED AT 400 WORDS)", "journal": "Veterinary microbiology", "doi": "10.1016/0378-1135(92)90059-3", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1992, "pmid": "1381539", "author": "Sheets RL", "n_authors": 5, "title": "Biologically selected recombinants between feline leukemia virus (FeLV) subgroup A and an endogenous FeLV element.", "abstract": "In efforts to elucidate the proximal leukemogens that might be produced during a feline leukemia virus (FeLV) infection of cats, homologous recombinations between molecularly cloned exogenous and endogenous FeLV proviruses of known sequences were examined in cell cultures in vitro. A plasmid containing an infectious member of the most commonly occurring FeLV subgroup (FeLV subgroup A or FeLV-A) was coexpressed with noninfectious constructs containing the envelope (env) gene of an endogenously inherited FeLV-like feline genomic element in transfected feline fibroblasts. The viruses generated were selected for their ability to propagate in human cells which are resistant to infection by the parental ecotropic FeLV-A or the noninfectious endogenous constructs. An analysis of the recombinants thus derived identified a limited number of sites in the env gene which were preferentially utilized in the generation of recombinant FeLVs under the selection conditions used. These sites were clustered in the surface glycoprotein (SU) moiety of the env gene, and it appeared that most, but not all, of the SU gene product of FeLV-A, beginning from the N-terminus, can be replaced by sequences from an endogenous element, still allowing the virus to be biologically viable. In fact, these substitutions in the env gene expanded infectivity of the parental FeLV-A from ecotropic to polytropic cell tropism. Additionally, substitutions in the SU region yielded many recombinants in which a primary neutralizing pentapeptide epitope of FeLV-A was altered because of its variance in the endogenous element. In several of the recombinants, this sequence was also found to be frequently mutated. Consistent with the changes identified in this antibody-binding domain, the recombinant viruses were only weakly inhibited by a monoclonal antibody directed against this epitope, while FeLV-A was highly sensitive to neutralization.", "journal": "Virology", "doi": "10.1016/0042-6822(92)90924-e", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1992, "pmid": "1374984", "author": "Petry H", "n_authors": 6, "title": "Isolation and characterization of a retrovirus from the fish genus Xiphophorus.", "abstract": "A cell line (BsT) established from neoplastic embryonal tissues of the platyfish (Xiphophorus maculatus) released spontaneously retrovirus-like particles. The particles have a buoyant density of 1.16 g/ml, a mean diameter of 100 nm and the morphology of immature retroviruses. The particle-associated proteins p70, p65, and p28 react with an antiserum directed against the major internal feline leukemia virus structural protein p27. The particles are associated with a reverse transcriptase. The purified enzyme has a molecular weight of about 70 kDa and prefers the template primers poly(rA):oligo(dT), poly(dC):oligo(dG), and poly(rC):oligo(dG) in the presence of Mn2+. The enzyme activity is inhibited by antibodies directed against the reverse transcriptase of feline leukemia virus and simian sarcoma virus. The particles contain a ribonucleic acid of about 70 S. In an endogenous reverse transcriptase reaction nucleic acids in the range of 0.2 to 0.4 kb were synthesized. In Northern blots with these nucleic acids as probe, three transcripts of about 8.5, 4.2, and 1.5 kb were detected in BsT cells. Southern blot analysis with the same probe demonstrates related sequences in the DNA of BsT cells and the platyfish and swordtail (Xiphophorus helleri). Hybridization experiments with the LTR-gag region of the feline leukemia virus show homologous sequences in the Xiphophorus genome.", "journal": "Virology", "doi": "10.1016/0042-6822(92)90533-u", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1992, "pmid": "1316496", "author": "Pandey R", "n_authors": 6, "title": "Recombination between feline leukemia virus subgroup B or C and endogenous env elements alters the in vitro biological activities of the viruses.", "abstract": null, "journal": "Journal of virology", "doi": "10.1128/JVI.66.6.3976-.1992", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1992, "pmid": "1316466", "author": "Terry A", "n_authors": 5, "title": "Pathogenesis of feline leukemia virus T17: contrasting fates of helper, v-myc, and v-tcr proviruses in secondary tumors.", "abstract": "A naturally occurring feline thymic lymphosarcoma (T17) provided the unique observation of a T-cell antigen receptor beta-chain gene (v-tcr) transduced by a retrovirus. The primary tumor contained three classes of feline leukemia virus (FeLV) provirus, which have now been characterized in more detail as (i) v-tcr-containing recombinant proviruses, (ii) v-myc-containing recombinant proviruses, and (iii) apparently full-length helper FeLV proviruses. The two transductions appear to have been independent events, with distinct recombinational junctions and no sequence overlap in the host-derived inserts. The T17 tumor cell line releases large numbers of FeLV particles of low infectivity; all three genomes are encapsidated, but passage of FeLV-T17 on feline fibroblast and lymphoma cells led to selective loss of the recombinant viruses. The oncogenic potential of the T17 virus complex was, therefore, tested by infection of neonatal cats with virus harvested directly from the primary T17 tumor cell line. A single inoculation of FeLV-T17 caused persistent low-grade infection culminating in thymic lymphosarcoma and acute thymic atrophy, which was accelerated by coinfection with the weakly pathogenic FeLV subgroup A (FeLV-A)/Glasgow-1 helper. Molecularly cloned FeLV-tcr virus (T-31) rescued for replication by a weakly pathogenic FeLV-A/Glasgow-1 helper virus was similarly tested in vivo and induced thymic atrophy and thymic lymphosarcomas. Most FeLV-T17-induced tumors manifested either v-myc or an activated c-myc allele and had undergone rearrangement of endogenous T-cell antigen receptor beta-chain genes, supporting the proposition that the oncogenic effects of c-myc linked to the FeLV long terminal repeat are targeted to a specific window in T-cell differentiation. However, neither the FeLV-T17-induced tumors nor the T-31 + FeLV-A-induced tumors contained clonally represented v-tcr sequences. Only one of the FeLV-T17-induced tumors contained detectable v-tcr proviruses, at a low copy number. While v-tcr does not have a readily transmissible oncogenic function, a more restricted role is not excluded, perhaps involving antigenic peptide-major histocompatibility complex recognition by the T-cell receptor complex. Such a function could be obscured by the genetic diversity of the outbred domestic cat host.", "journal": "Journal of virology", "doi": "10.1128/JVI.66.6.3538-3549.1992", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1992, "pmid": "1541910", "author": "Oostendorp RA", "n_authors": 5, "title": "Synthetic hexapeptides derived from the transmembrane envelope proteins of retroviruses suppress N-formylpeptide-induced monocyte polarization.", "abstract": "Retroviral infections are frequently associated with immunosuppression. Retroviral transmembrane envelope proteins (TM proteins) play an important role in this phenomenon. CKS-17, a synthetic heptadecapeptide, represents the immunosuppressive site of these retroviral TM proteins. Here we support on the further delineation of this immunosuppressive site using CKS-17-derived hexapeptides. The N-formyl-methionyl-leucyl-phenylalanine-induced monocyte polarization assay was used throughout this study because this monocyte function has been shown to be highly sensitive to TM protein p15E-related immunosuppression. We found that in addition to CKS-17 one CKS-17-derived hexapeptide, LDLLFL, reversibly inhibited monocyte polarization, with 50% inhibitory concentrations of 20 and 2 microM respectively. LDLLFL-mediated inhibition was sequence specific because the reverse peptide LFLLDL and scrambled peptides were not inhibitory. Hexapeptides corresponding to LDLLFL, but derived from various retroviruses other than murine leukemia virus, also inhibited monocyte polarization. Peptides most homologous to LDLLFL-LDILFL (feline leukemia virus) and LDLLFW (human T lymphotropic virus types I and II)--were the most potent inhibitors. Peptides homologous to primate and human endogenous proviruses were not suppressive. LDLLFL and some of its homologous also inhibited polarization of neutrophilic granulocytes. These findings lend further support to the view that conserved retroviral TM protein-related peptides can play an important role in suppression of inflammatory cell function as encountered in retrovirus-associated immunosuppression.", "journal": "Journal of leukocyte biology", "doi": "10.1002/jlb.51.3.282", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1992, "pmid": "1733113", "author": "Takeuchi Y", "n_authors": 5, "title": "Retroviral pseudotypes produced by rescue of a Moloney murine leukemia virus vector by C-type, but not D-type, retroviruses.", "abstract": "Human HOS cells containing a Moloney murine leukemia virus (Mo-MLV) recombinant genome were infected by a panel of retroviruses. The C-type viruses simian sarcoma associated virus, feline leukemia virus subgroup B, and the feline endogenous virus RD114 were able to form pseudotypes with the Mo-MLV genome, which transferred a selectable marker gene to target cells; however, Human T cell leukemia virus-1 and the D-type viruses Mason-Pfizer monkey virus and simian retrovirus-1 failed to rescue the Mo-MLV vector. Further characterization of the RD114 pseudotype demonstrated that it retained the receptor specificity of RD114 and will therefore prove useful in receptor characterization.", "journal": "Virology", "doi": "10.1016/0042-6822(92)90049-u", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1992, "pmid": "1318467", "author": "Jarrett O", "n_authors": 1, "title": "Pathogenicity of feline leukemia virus is commonly associated with variant viruses.", "abstract": "Many of the serious diseases resulting from feline leukemia virus (FeLV) infection are associated with the generation of novel variant viruses. The prototype FeLV-A virus is highly stable and circulates in the cat population without apparent antigenic change. However, recombination with cellular oncogenes produces viruses which cause leukemia or other malignant diseases. Other recombinants within the env genes of FeLV-A and endogenous FeLV are recognized as belonging to a second subgroup, FeLV-B, the presence of which is correlated with an increased risk of infection with FeLV and a higher incidence of leukemia. Mutants of FeLV which affect the env gene are phenotypically of a third subgroup, FeLV-C, and have a close association with erythroid aplasia. None of these viruses, apart from FeLV-B, is transmitted further in nature. Therefore the generation of these novel viruses and the production of disease is an inadvertent consequence of FeLV infection.", "journal": "Leukemia", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1993, "pmid": "8254466", "author": "Tochikura TS", "n_authors": 10, "title": "Fusion activity dissociated from replication ability in feline immunodeficiency virus (FIV) in human cells.", "abstract": "Multinucleated-giant-cell formation followed by cell killing was observed after cocultivation of the feline immunodeficiency virus (FIV)-producing feline T-cell line 3201/FIV with various human cells, including T-cell lines carrying human T-cell lymphotropic virus type I (HTLV-I). The susceptibility to giant cell formation varied with the cell lines tested. Cocultivation of irradiated 3201/FIV cells with MT-2 cells resulted in giant cell formation as early as 2 h in culture, with striking resemblance to that induced by human immunodeficiency virus (HIV). MT-4 cells (HTLV-I positive) and H9 cells (HTLV-I negative) were less susceptible than MT-2 to the induction of syncytia. MOLT-4 cells (HTLV-I negative) had intermediate sensitivity to syncytia formation. No syncytia were observed in the monocytic cell line U-937 (HTLV-I negative). Syncytia formation between 3201/FIV and MT-2 cells was inhibited by polyclonal cat anti-FIV antisera but not polyclonal cat anti-feline leukemia virus (FeLV) antisera, goat anti-FeLV, uninfected specific-pathogen-free cat serum, human anti-HTLV-I antisera, or normal human and goat serum. Concentrated cell-free FIV supernatant from 3201/FIV also induced giant cells of MT-2 cells that were indistinguishable from those induced by cocultivation. Giant cells and extensive cell killing associated with giant cell formation declined and disappeared within 10 days. Surviving cells appeared to be of normal size and grew continuously without expressing FIV antigen or releasing infective virus. Although Southern blot analysis using probes specific for FIV could not detect proviral DNA in any of the five human cell lines cocultured with irradiated 3201/FIV cells, the polymerase chain reaction (PCR) technique detected FIV-specific DNA in MOLT-4 cells. DNA from the FIV-PCR positive MOLT-4 cells was PCR negative for endogenous FeLV-specific sequences, indicating that the MOLT-4 cell DNA was not contaminated with DNA from feline cells (i.e., 3201 cells). The FIV-MOLT-4 cells remained PCR positive for FIV after 40 passages, suggesting stable integration in the human cell line. These findings indicate that FIV is capable of forming proviral DNA in human T-lymphoid cells by cocultivation, although this FIV-carrying human cell line failed to produce replication-competent viruses.", "journal": "Journal of acquired immune deficiency syndromes", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1993, "pmid": "8388492", "author": "Sheets RL", "n_authors": 4, "title": "Recombinant feline leukemia virus genes detected in naturally occurring feline lymphosarcomas.", "abstract": "Using a polymerase chain reaction strategy aimed at detecting recombinant feline leukemia virus (FeLV) genomes with 5' env sequences originating from an endogenous source and 3' env sequences resulting from FeLV subgroup A (FeLV-A), we detected recombinant proviruses in approximately three-fourths of naturally occurring thymic and alimentary feline lymphosarcomas (LSAs) and one-third of the multicentric LSAs from cats determined to be FeLV capsid antigen positive by immunofluorescence assay. In contrast, only 1 of 22 naturally arising FeLV-negative feline LSAs contained recombinant proviruses, and no recombinant env gene was detected in seven samples from normal tissues or tissues from FeLV-positive animals that died from other diseases. Four preferred structural motifs were identified in the recombinants; one is FeLV-B like (recognizing that FeLV-B itself is a product of recombination between FeLV-A and endogenous env genes), and three contain variable amounts of endogenous-like env gene before crossing over to FeLV-A-related sequences: (i) a combination of full-length and deleted env genes with recombination at sites in the middle of the surface glycoprotein (SU), (ii) the entire SU encoded by endogenous-like sequences, and (iii) the entire SU and approximately half of the transmembrane protein encoded by endogenous-like sequences. Additionally, three of the thymic tumors contained recombinant proviruses with mutations in the vicinity of the major neutralizing determinant for the SU protein. These molecular genetic analyses of the LSA DNAs correspond to our previous results in vitro and support the occurrence and association of viral recombinants and mutants in vivo in FeLV-induced leukemogenesis.", "journal": "Journal of virology", "doi": "10.1128/JVI.67.6.3118-3125.1993", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1994, "pmid": "7941350", "author": "Boomer S", "n_authors": 4, "title": "Isolation of a novel subgroup B feline leukemia virus from a cat infected with FeLV-A.", "abstract": "Proviruses were cloned directly from a cat that developed neurological disorders approximately 28 months after inoculation with a molecularly cloned, minimally pathogenic subgroup A feline leukemia virus (FeLV-A). In addition to FeLV-A proviruses that were nearly identical to the inoculated virus, we detected a subgroup B-like variant in brain, bone marrow, and lymph node that apparently had acquired the major portion of its extracellular envelope gene (gp70) from endogenous FeLV-related sequences. A similar recombinant was also detected, by PCR, at low levels in bone marrow from an early time postinfection (2.5 months). A full-length proviral variant with this recombinant structure cloned from brain tissue encoded a replication-defective virus. A chimera encoding the 5' gag-pol portion of FeLV-A and the 3' env-LTR portion of the defective brain-derived clone was replication-competent and had the extended host range properties of FeLV-B.", "journal": "Virology", "doi": "10.1006/viro.1994.1597", "deposited_data": "Sim", "nuccore_ids": "413736, 413735, 413734", "bioproject_ids": null, "sra_ids": null}, {"year": 1994, "pmid": "8009844", "author": "Bechtel MK", "n_authors": 6, "title": "Abnormal processing of a recombinant feline leukemia virus envelope polyprotein and its interference with subgroup C virus infection.", "abstract": "Processing of the env polyprotein of a noninfectious feline leukemia virus (FeLV) recombinant, named r6gp, was examined in human-transfected cells. The r6gp provirus was previously generated in the frame of FeLV, subgroup B, GA clone with substitution of all but 40 C-terminal amino acid sequences of the surface glycoprotein (SU) from an endogenous FeLV provirus element (CFE-6). Although r6gp produced a normal size (85 kDa) env glycoprotein precursor, the product, unlike the precursor of the parental virus, was neither additionally glycosylated nor further processed into mature env proteins. Biochemical observations were consistent with the idea that the chimeric env polyprotein was trapped in the endoplasmic reticulum (ER) and were directly supported by immunofluorescence microscopy analyses. Interestingly, the residence of the chimeric protein in the ER specifically interfered with FeLV, subgroup C (Sarma) virus infection but not the parental FeLV-B virus infection. Since FeLV-C provirus sequences could be readily detected in the infected cells, it appeared that r6gp env expression did not block entry of the challenge virus. While FeLV-B and CFE-6 env genes share an extensive overall sequence homology, a variable region (region VI) of CFE-6 near the C-terminus of SU, which was retained in the r6gp construct, exhibits a considerably higher degree of homology to FeLV-C than FeLV-B. Thus, we propose that region VI is involved in conferring specificity for the env polyprotein oligomerization in the ER, and that co-oligomerization of the trapped r6gp env with FeLV-C is the reason for specific interference with FeLV-C infection. The results also demonstrate for the first time a functional abnormality of a recombinant FeLV env gene which is structurally similar to those commonly detected in FeLV-induced feline lymphosarcomas.", "journal": "Virology", "doi": "10.1006/viro.1994.1349", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1994, "pmid": "8138999", "author": "McDougall AS", "n_authors": 6, "title": "Defective endogenous proviruses are expressed in feline lymphoid cells: evidence for a role in natural resistance to subgroup B feline leukemia viruses.", "abstract": "Endogenous feline leukemia virus (FeLV)-related sequences (enFeLV) are a family of proviral elements found in domestic cats and their close relatives. These elements can recombine with exogenous, infectious FeLVs of subgroup A (FeLV-A), giving rise to host range variants of FeLV-B. We found that a subset of defective enFeLV proviruses is highly expressed in lymphoma cell lines and in a variety of primary tissues, including lymphoid tissues from healthy specific-pathogen-free cats. At least two RNA species were detected, a 4.5-kb RNA containing gag, env, and long terminal repeat sequences and a 2-kb RNA containing env and long terminal repeat sequences. Cloning of enFeLV cDNA from two FeLV-free lymphoma cell lines (3201 and MCC) revealed a long open reading frame (ORF) encoding a truncated env gene product corresponding to the N-terminal portion of gp70env. Interestingly, all of three natural FeLV-B isolates include 3' env sequences which are missing from the highly transcribed subset and hence must be derived from other enFeLV elements. The enFeLV env ORF cDNA clones were closely similar to a previously characterized enFeLV provirus, CFE-16, but were polymorphic at a site corresponding to an exogenous FeLV neutralization epitope. Site-specific antiserum raised to a C-terminal 30-amino-acid peptide of the enFeLV env ORF detected an intracellular product of 35 kDa which was also shed from cells in stable form. Expression of the 35-kDa protein correlated with enFeLV RNA levels and was negatively correlated with susceptibility to infection with FeLV-B. Cell culture supernatant containing the 35-kDa protein specifically blocked infection of permissive fibroblast cells with FeLV-B isolates. We suggest that the truncated env protein mediates resistance by receptor blockade and that this form of enFeLV expression mediates the natural resistance of cats to infection with FeLV-B in the absence of FeLV-A.", "journal": "Journal of virology", "doi": "10.1128/JVI.68.4.2151-2160.1994", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1994, "pmid": "8311118", "author": "Chakrabarti R", "n_authors": 5, "title": "Recombination between feline exogenous and endogenous retroviral sequences generates tropism for cerebral endothelial cells.", "abstract": "Brain tissues of domestic cats that died of aplastic anemia from infection with either parental feline leukemia virus (FeLV), subgroup C, or a mixture of FeLV-C and recombinants between FeLV-C and an endogenous FeLV provirus were examined by the immunoperoxidase staining technique using a monoclonal antibody (C11D8) directed against an epitope of the viral surface glycoprotein (SU). Positive staining of the central nervous system (CNS) capillary endothelial cells with no labeling on neuronal or glial cells was observed in cats that were inoculated with the virus mixture. This was in contrast to brain tissue of cats infected with FeLV-C alone, which showed no such staining. While non-CNS endothelial cells derived from human umbilical vein (HUVEC) could be readily infected in culture by FeLV-C, endothelial cells derived from human retina (REC) or brain (BEC) were resistant to infection by this parental virus. These latter cells in culture, however, could be infected by the viral mixture. The data suggested that at least one or more of the presumptive recombinant viruses could specifically infect CNS-derived endothelial cells. Using polymerase chain reaction and DNA sequencing strategies to amplify and analyze DNA fragments of the proviral SU region from cells infected with REC-selected viruses, we found the occurrence of a single recombinant in which two-thirds of the SU gene from the N-terminus of FeLV-C was replaced by the endogenous FeLV element. This recombinant virus, when molecularly cloned, should be useful in determining its potential in vivo neuropathogenicity.", "journal": "The American journal of pathology", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1994, "pmid": "8259654", "author": "Mathes LE", "n_authors": 7, "title": "Pathogenicity of a subgroup C feline leukemia virus (FeLV) is augmented when administered in association with certain FeLV recombinants.", "abstract": "There is evidence to suggest that infectious feline leukemia viruses (FeLVs) may be altered biologically because of homologous recombination with non-infectious endogenous FeLV (enFeLV) sequences in the infected cells. To evaluate the role of such recombination events in FeLV pathogenesis, a molecular clone of subgroup C FeLV, Sarma strain (FSC), was tested for induction of aplastic anemia in the absence or presence of mixtures of recombinants between FSC and an enFeLV element. In the recombinants, FSC sequences in the viral surface glycoprotein (SU) protein were variably replaced by the corresponding sequences of the enFeLV. The results showed that the virus mixtures varied in their infectivity to neonatal specific pathogen-free cats. One group of mixtures, although exhibiting relatively reduced infectivity, represented the most acute disease-inducing agents. The presence of recombinants in this mixture significantly accelerated the development of erythrocyte aplasia compared to cats infected with FSC alone. In addition, infected cells appeared to be distributed differently in various hematopoietic organs with respect to infection with FSC versus viral mixture. Viral recombinants which were present in this inoculum mixture, however, could not be detected in the plasma or infected tissues of the cats at the end stage of the disease, although their presence in the plasma at the early stages could be detected. Clearly, parental FSC outgrew the recombinants in the infected animals, since its detection was prominent at all stages of the progression of the disease. Therefore, we hypothesize that recombinants initially present in the infected animals, while only poorly replicated compared to FSC in the host, might have had the opportunity to infect certain target cells (potentially erythroid progenitor cells) and then disappeared with the associated cytopathic effect.", "journal": "Virology", "doi": "10.1006/viro.1994.1021", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1995, "pmid": "8553560", "author": "Pandey R", "n_authors": 7, "title": "Feline leukemia virus variants in experimentally induced thymic lymphosarcomas.", "abstract": "This study was initiated to evaluate the in vivo infectivity and pathogenicity of a group of recombinant feline leukemia viruses (rFeLVs) previously generated by in vitro forced recombination between a FeLV subgroup A virus (FeLV-A) and an endogenous FeLV (enFeLV) envelope (env) element (Sheets et al., 1992, Virology 190, 849-855). To determine infectivity of rFeLVs, neonatal cats were inoculated with rFeLVs alone or in combination with FeLV-A. The recombinant viruses were able to replicate efficiently in vivo only when administered along with FeLV-A. Of six co-infected cats, three developed thymic lymphosarcomas, one severe aplastic anemia, and two cachexia and depression; all were viremic and seroconverted shortly after inoculation. While both virus types were detected in virtually all tissues examined from these tumor-bearing cats, there was a particularly noteworthy sequence reversion in the rFeLVs. It is known that exogenous FeLV isolates carry a conserved neutralizing MGPNL epitope in the middle of the surface glycoprotein domain of the env gene. In contrast, the parental recombinant viruses used to inoculate these cats harbored the enFeLV-derived MGPNP sequence at this position. However, all in vivo-propagated recombinants displayed the MGPNL sequence, while the env-encoded backbone flanking the MGPNL sequence was that of the parental recombinant virus. These results suggest that viruses with the MGPNL epitope have an in vivo proliferative advantage. The data also provide an explanation for the conservation of this epitope in exogenous FeLVs despite the existence of variant forms in enFeLV proviral elements with which they can recombine.", "journal": "Virology", "doi": "10.1006/viro.1995.0069", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1995, "pmid": "7663052", "author": "Linenberger ML", "n_authors": 2, "title": "Haematological disorders associated with feline retrovirus infections.", "abstract": "Feline oncornavirus and lentivirus infections have provided useful models to characterize the virus and host cell factors involved in a variety of marrow suppressive disorders and haematological malignancies. Exciting recent progress has been made in the characterization of the viral genotypic features involved in FeLV-associated diseases. Molecular studies have clearly defined the causal role of variant FeLV env gene determinants in two disorders: the T-lymphocyte cytopathicity and the clinical acute immunosuppression induced by the FeLV-FAIDS variant and the pure red cell aplasia induced by FeLV-C/Sarma. Variant or enFeLV env sequences also appear to play a role in FeLV-associated lymphomas. Additional studies are required to determine the host cell processes that are perturbed by these variant env gene products. In the case of the FeLV-FAIDS variant, the aberrant env gene products appear to impair superinfection interference, resulting in accumulation of unintegrated viral DNA and cell death. In other cases it is likely that the viral env proteins interact with host products that are important in cell viability and/or proliferation. Understanding of these mechanisms will therefore provide insights to factors involved in normal lymphohaematopoiesis. Similarly, studies of FeLV-induced haematological neoplasms should reveal recombination or rearrangement events involving as yet unidentified host gene sequences that encode products involved in normal cell growth regulation. These sequences may include novel protoncogenes or sequences homologous to genes implicated in human haematological malignancies. The haematological consequences of FIV are quite similar to those associated with HIV. As with HIV, FIV does not appear to directly infect myeloid or erythroid precursors, and the mechanisms of marrow suppression likely involve virus, viral antigen, and/or infected accessory cells in the marrow microenvironment. Studies using in vitro experimental models are required to define the effects of each of these microenvironmental elements on haematopoietic progenitors. As little is known about the molecular mechanisms of FIV pathogenesis, additional studies of disease-inducing FIV strains are needed to identify the genotypic features that correlate with virulent phenotypic features. Finally, experimental FIV infection in cats provides the opportunity to correlate in vivo virological and haematological changes with in vitro observations in a large animal model that closely mimics HIV infection in man.", "journal": "Bailliere's clinical haematology", "doi": "10.1016/s0950-3536(05)80233-1", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1995, "pmid": "8828142", "author": "Roy-Burman P", "n_authors": 1, "title": "Endogenous env elements: partners in generation of pathogenic feline leukemia viruses.", "abstract": "Feline leukemia viruses (FeLVs), which are replication-competent oncoretroviruses of the domestic cat species, are contagiously transmitted in natural environments. They are capable of inducing either acute antiproliferative disease or, after prolonged latency, lymphoid malignancies in this animal population. Current knowledge of the recombinational events between infectious FeLV and noninfectious endogenously inherited FeLV-like elements is reviewed, and the potential role of the derived recombinant viruses in pathogenesis is discussed. Major observations made are as follows: (1) Up to three fourths of the exogenous FeLV envelope glycoprotein (SU), beginning from the N-terminal end, can be replaced by sequences from an endogenous FeLV to produce biologically active chimeric FeLVs. The in vitro replication efficiency or cell tropism of the recombinants appears to be influenced by the amount of SU sequences replaced by the endogenous partner, as well as by the locus of origin of the endogenous sequences. (2) Generation of FeLV recombinants in tissue culture cells corresponds closely to the findings from natural tumors. There is direct evidence, based on molecular genetic analysis, for the prevalence of recombinant proviruses in naturally arising FeLV-induced lymphomas. (3) Certain recombinants harboring an altered primary neutralizing epitope in the middle of SU corresponding to the endogenous FeLV sequence can evade immunity developed against common FeLV infection. In several other recombinants, the epitope sequence is found to be frequently mutated during the process of recombination. (4) FeLV variants with altered epitope, although they may not be efficient in replication in vivo, apparently are capable of causing focal infection in target organs. Evidence is also presented that when coinfected with an exogenous FeLV, the epitope sequence in the variants is reverted to the exogenous type, providing an explanation why this sequence is found to be conserved in all natural isolates of FeLV. (5) A prototype chimeric polyprotein containing most of the SU from the endogenous source is abnormally processed and becomes trapped in the endoplasmic reticulum. A functional consequence of such trapping is interference with specific FeLV infection. (6) Some recombinants, while only poorly replicating in the host, may have the ability to infect target erythroid progenitor cells for the induction of strong cytopathic effect. (7) Some other recombinants appear to potentiate lymphomagenesis by exogenous FeLV and others to acquire properties to infect CNS endothelial cells, an event that could potentially be related to FeLV-induced neuropathogenicity. (8) Of multiple recombinant viruses, a specific recombinant species was found to occur in each of the three cats examined in which lymphoma was experimentally induced, and it was exclusively seen in one of these cats. This recombinant FeLV may potentially be a candidate for strong leukemogenic function. In addition to commonly encountered virus envelope changes, another prominent viral factor involved in tumorigenesis is mutated FeLV transcription regulatory sequences, most frequently with enhancer duplication or triplication. Although only a limited amount of information is available in the area of insertional mutagenesis in FeLV neoplastic disease, activation of certain key nuclear transcription factor genes has been documented.", "journal": "Virus genes", "doi": "10.1007/BF01728655", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1996, "pmid": "8941325", "author": "Kabát P", "n_authors": 4, "title": "Human endogenous retrovirus HC2 is a new member of the S71 retroviral subgroup with a full-length pol gene.", "abstract": "We have isolated and characterized a new human endogenous provirus, which is closely related to the human retrovirus S71, but unlike S71 has a full-length pol gene. Two degenerate oligonucleotide primers based on highly conserved motifs within the active sites of two retroviral proteins (the protease and reverse transcriptase) were designed and used for PCR. An amplified product of 847 bp in length, which showed significant homology to protease and reverse transcriptase of several retroviruses, was used for high stringency hybridization with a human genomic library. The MuLV-related endogenous retrovirus sequence, designated HC2, was isolated and completely sequenced. HC2 is a provirus with complete gag and pol genes and a 3' LTR; the 5' LTR and env gene are missing. The gag and pol genes appear complete, since they contain sequences homologous to the matrix protein, capsid protein, and nucleocapsid protein of gag and to the protease, reverse transcriptase, tether, RNase H, and integrase of pol. Phylogenetic analysis suggests that although HC2 and S71 are MuLV-related retroviruses, their characters are quite distinct, being placed outside of a clade containing most of the previously characterized MuLV-related retroviruses such as GaLV, FeLV, BaEV, and SSV/SSAV.", "journal": "Virology", "doi": "10.1006/viro.1996.0630", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1996, "pmid": "8727505", "author": "Porter CD", "n_authors": 7, "title": "Comparison of efficiency of infection of human gene therapy target cells via four different retroviral receptors.", "abstract": "The relative efficiency of transduction of gene therapy target cells was measured for retroviruses bearing the envelopes of amphotropic murine leukemia virus (MLV-A), xenotropic murine leukemia virus (MLV-X), gibbon ape leukemia virus (GALV), feline leukemia virus subgroup B (FeLV-B), and the feline endogenous virus RD114. These viruses use various cell-surface receptors. Activated peripheral blood lymphocytes (PBL) and primary melanoma cultures were infected relatively poorly by MLV-X pseudotypes. RD114 pseudotypes infected PBL relatively well, whereas bone marrow progenitor cells were efficiently infected by all viruses. Helper-free virus bearing the envelopes of MLV-A, RD114, or GALV was similarly tested. All infected melanoma or bone marrow progenitor cells efficiently, whereas MLV-A was relatively inefficient for infection of PBL. The general utility of RD114 pseudotyped virus for gene delivery coupled with its resistance to inactivation by human serum makes this envelope the most suitable choice for in vivo gene therapy.", "journal": "Human gene therapy", "doi": "10.1089/hum.1996.7.8-913", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1996, "pmid": "8833612", "author": "Misdorp W", "n_authors": 1, "title": "Veterinary cancer epidemiology.", "abstract": "This paper reviews the impact of veterinary cancer epidemiology on veterinary oncology, human oncology, comparative oncology, and on the etiology and pathogenesis of cancer. The detection of clusters of diseased animals has led to the discovery of the infectious, viral-associated nature of malignant lymphoma of cats, poultry, and cattle. Although some viruses (FeLV, BLV) can, under experimental conditions, cross the species barrier, there is thus far no evidence for a zoonotic hazard for the human. The keeping of pet/birds or pigeons was found to be associated with an increased risk of lung cancer in the bird keepers. Dogs appear to be useful 'sentinels' for environmental hazards (asbestos, dyes, passive smoking, insecticides). The complex pathogenesis of cancer was dissected in an epidemiologic-experimental study in cows, which had intestinal papillomas and carcinomas. Endogenous genetic factors may also play a role in pathogenesis, as is evidenced by species, breed (Boxer!), and family related aggregates of tumour diseases. Epidemiology may provide a means to prevent tumour diseases by, for example, withdrawal of hormones (mammary cancer) or isolation of tumour-virus positive animals (malignant lymphoma).", "journal": "The veterinary quarterly", "doi": "10.1080/01652176.1996.9694610", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1996, "pmid": "8551576", "author": "Fulton R", "n_authors": 4, "title": "Apparent uncoupling of oncogenicity from fibroblast transformation and apoptosis in a mutant myc gene transduced by feline leukemia virus.", "abstract": "The T17 v-myc oncogene was transduced by feline leukemia virus in a spontaneous feline T-cell lymphosarcoma. Molecular cloning and sequencing of the v-myc gene revealed several unique mutations, including a large deletion affecting amino acids 49 to 124 and a 3-bp insertion within the basic DNA binding domain which converts Leu-362 to Phe-Arg. The T17 lymphoma cell line was found to express a truncated 50-kDa Myc protein at exceptionally high levels, while the endogenous c-myc gene was not detectably expressed. These observations suggest that the mutant Myc product expresses an oncogenic function in T cells. Further evidence that the T17 mutant gene retains oncogenic potential was provided by its detection in clonally integrated proviruses in secondary tumors induced by feline leukemia virus T17, where no reversion mutations were found in any of three tumors examined. However, the mutant T17 v-myc gene did not induce transformation in a chicken embryo fibroblast assay, in contrast to wild-type feline c-myc, which conferred higher growth rates on the chicken fibroblasts, along with altered morphology and the ability to form foci in soft agar. Chicken cells over-expressing feline c-myc died by apoptosis when cultured with low serum concentrations, while the T17 mutant had no discernible effect. These results suggest that the leukemogenic potential of Myc can be uncoupled from its ability to cause transformation in fibroblasts. A possible explanation for this apparent paradox is that developing T cells are acutely sensitive to a subset of Myc functions which are insufficient for fibroblast transformation.", "journal": "Journal of virology", "doi": "10.1128/JVI.70.2.1154-1162.1996", "deposited_data": "Sim", "nuccore_ids": "1173534", "bioproject_ids": null, "sra_ids": null}, {"year": 1996, "pmid": "8822790", "author": "Rojko JL", "n_authors": 5, "title": "Cytopathic feline leukemia viruses cause apoptosis in hemolymphatic cells.", "abstract": "Certain isolates of the oncoretrovirus feline leukemia virus (FeLV) are strongly cytopathic for hemolymphatic cells. A major cytopathicity determinant is encoded by the SU envelope glucoprotein gp70. Isolates with subgroup C SU gp70 genes specifically induce apoptosis in hemolymphatic cells but not fibroblasts. In vitro exposure of feline T-cells to FeLV-C leads first to productive viral replication, next to virus-induced cell agglutination, and lastly to apogenesis. This in vitro phenomenon may explain the severe progressive thymic atrophy and erythroid aplasia which follow viremic FeLV-C infection in vivo. Inappropriate apoptosis induction has also been hypothesized to explain the severe thymico-lymphoid atrophy and progressive immune deterioration associated with isolates of FeLV containing variant envelope genes. The influence of envelope hypervariability (variable regions 1 [Vr1] and 5 [Vr5] on virus tropism, viremia induction, neutralizing antibody development and cytopathicity is discussed. Certain potentially cytopathic elements in FeLV SU gp70 Vr5 may derive from replication-defective, poorly expressed, endogenous FeLVs. Other more highly conserved regions in FeLV TM envelope p15E may also influence apoptosis induction.", "journal": "Progress in molecular and subcellular biology", "doi": "10.1007/978-3-642-79850-4_2", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1997, "pmid": "9343161", "author": "Boomer S", "n_authors": 4, "title": "Three distinct envelope domains, variably present in subgroup B feline leukemia virus recombinants, mediate Pit1 and Pit2 receptor recognition.", "abstract": "Subgroup B feline leukemia viruses (FeLV-Bs) evolve from subgroup A FeLV (FeLV-A) by recombining with portions of endogenous FeLV envelope sequences in the cat genome. The replication properties of FeLV-B are distinct from those of FeLV-A; FeLV-B infects many nonfeline cell lines and recognizes the human Pit1 (HuPit1) receptor, whereas FeLV-A infects primarily feline cells, using a distinct but as yet undefined receptor. Here, we demonstrate that some FeLV-Bs can also use human Pit2 (HuPit2) and hamster Pit2 (HaPit2) for entry. By making viruses that contain chimeric surface (SU) envelope proteins from FeLV-A and FeLV-B, and testing their infectivity, we have defined genetic determinants that confer host range and specific receptor recognition. HuPit1 receptor recognition determinants localize to the N-terminal region of the FeLV-B SU, amino acids 83 to 116, encompassing the N-terminal portion of variable region A (VRA). While this 34-amino-acid domain of the FeLV-B VRA is sufficient for infection of some cells (feline, canine, and human), amino acids 146 to 249 of FeLV-B, which include variable region B (VRB), were required for efficient infection in other cell types (hamster, bovine, and rat). Chimeras encoding FeLV-B VRA and VRB also infected cells expressing HaPit2 and HuPit2 receptors more efficiently than chimeras encoding only the VRA of FeLV-B, suggesting that VRB provides a secondary determinant that is both cell and receptor specific. However, viruses containing additional FeLV-B sequences in the C terminus of SU could not recognize HuPit2, implying that there is a determinant beyond VRB that negatively affects HuPit2 interactions. Thus, Pit2 recognition may drive selection for the generation of specific FeLV-B recombinants, offering an explanation for the two major classes of FeLV-B that have been observed in vivo. Furthermore, the finding that some FeLV-Bs can use both Pit1 and Pit2 may explain previous observations that FeLV-B and GALV, which primarily uses Pit1, display nonreciprocal interference on many cell types.", "journal": "Journal of virology", "doi": "10.1128/JVI.71.11.8116-8123.1997", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1997, "pmid": "9344336", "author": "Hishikawa T", "n_authors": 12, "title": "Detection of antibodies to a recombinant gag protein derived from human endogenous retrovirus clone 4-1 in autoimmune diseases.", "abstract": "To investigate whether human endogenous retroviruses (HERV) contribute to autoimmune diseases, we prepared a recombinant p30gag protein derived from clone 4-1 of the HERV family, using a baculovirus-vector system. This p30gag protein (CA41B) was approximately 30 kDa, as expected, and reacted with antibodies for p30gag purified from both murine and feline leukemia virus. This result suggested that the antigenic determinant for p30gag was well conserved in CA41B. Analysis of serum antibodies to p30gag in patients with autoimmune diseases was done by Western blotting. CA41B detected anti-p30gag antibodies in 48.3% of systemic lupus erythematosus (SLE) patients, 35.0% of Sjögren's syndrome (SS) patients, and 33.3% of mixed connective tissue disease (MCTD) patients, whereas no anti-p30gag antibodies were found in healthy subjects. This suggested that HERV p30gag or other retroviral p30gag proteins possessing the same antigenic determinant as CA41B may play a role in these diseases. Although detection of antibodies to HERV p30gag in autoimmune diseases is indirect evidence that HERV proteins are involved, this study showed that patients with autoimmune diseases have antibodies to HERV p30gag using a recombinant HERV protein rather than synthetic peptides based on HERV or retroviral proteins of other species.", "journal": "Viral immunology", "doi": "10.1089/vim.1997.10.137", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1998, "pmid": "9811727", "author": "Lee SY", "n_authors": 3, "title": "Genetic analysis of the rat leukemia virus: influence of viral sequences in transduction of the c-ras proto-oncogene and expression of its transforming activity.", "abstract": "The rat leukemia virus (RaLV) is an endogenous retrovirus that is spontaneously released by Sprague-Dawley rat embryo cells. The overall structure of the RaLV genome resembles that of other simple, replication-competent retroviruses, but the sequence of the long terminal repeats (LTR) is unique and unrelated to the known retroviruses. Phylogenetically, the RaLV genome appears to be more closely related to the feline leukemia virus group of retroviruses than to the murine leukemia virus group. A remarkable feature of RaLV is that it is capable of transducing a ras proto-oncogene from rat tumor cells in the form of an acutely transforming virus, designated the Rasheed strain of the rat sarcoma virus (RaSV). With the exception of the c-ras sequence, the genomes of both RaLV and RaSV are collinear. The RaSV-encoded oncogene v-Ra-ras expresses a fusion protein with a molecular mass of 29 kDa, and it exhibits a unique structure that has not been described previously for any known virus. The 5' end of this gene is derived from sequences encoding RaLV matrix followed by 20 bp derived from the U5 region of the RaLV LTR (RS-U5 element) which is joined at its 3' end to sequences derived from all six (coding and noncoding) exons of the c-ras proto-oncogene at the 3' end. This recombinational event represents a novel mechanism among the acutely transforming viruses that have been studied.", "journal": "Journal of virology", "doi": "10.1128/JVI.72.12.9906-9917.1998", "deposited_data": "Sim", "nuccore_ids": "349109, 348950", "bioproject_ids": null, "sra_ids": null}, {"year": 1998, "pmid": "9696797", "author": "Chen H", "n_authors": 7, "title": "Pathogenicity induced by feline leukemia virus, Rickard strain, subgroup A plasmid DNA (pFRA).", "abstract": "A new provirus clone of feline leukemia virus (FeLV), which we named FeLV-A (Rickard) or FRA, was characterized with respect to viral interference group, host range, complete genome sequence, and in vivo pathogenicity in specific-pathogen-free newborn cats. The in vitro studies indicated the virus to be an ecotropic subgroup A FeLV with 98% nucleotide sequence homology to another FeLV-A clone (F6A/61E), which had also been fully sequenced previously. Since subgroup B polytropic FeLVs (FeLV-B) are known to arise via recombination between ecotropic FeLV-A and endogenous FeLV (enFeLV) env elements, the in vivo studies were conducted by direct intradermal inoculation of the FRA plasmid DNA so as to eliminate the possibility of coinoculation of any FeLV-B which may be present in the inoculum prepared by propagating FeLV-A in feline cell cultures. The following observations were made from the in vivo experiments: (i) subgroup conversion from FeLV-A to FeLV-A and FeLV-B, as determined by the interference assay, appeared to occur in plasma between 10 and 16 weeks postinoculation (p.i.); (ii) FeLV-B-like recombinants (rFeLVs), however, could be detected in DNA isolated from buffy coats and bone marrow by PCR as early as 1 to 2 weeks p.i.; (iii) while a mixture of rFeLV species containing various amounts of N-terminal substitution of the endogenous FeLV-derived env sequences were detected at 8 weeks p.i., rFeLV species harboring relatively greater amounts of such substitution appeared to predominate at later infection time points; (iv) the deduced amino acid sequence of rFeLV clones manifested striking similarity to natural FeLV-B isolates, within the mid-SU region of the env sequenced in this work; and (v) four of the five cats, which were kept for determination of tumor incidence, developed thymic lymphosarcomas within 28 to 55 weeks p.i., with all tumor DNAs harboring both FeLV-A and rFeLV proviruses. These results provide direct evidence for how FeLV-B species evolve in vivo from FeLV-A and present a new experimental approach for efficient induction of thymic tumors in cats, which should be useful for the study of retroviral lymphomagenesis in this outbred species.", "journal": "Journal of virology", "doi": "10.1128/JVI.72.9.7048-7056.1998", "deposited_data": "Sim", "nuccore_ids": "9630707, 3420022", "bioproject_ids": "485481", "sra_ids": null}, {"year": 1998, "pmid": "9660073", "author": "Bechtel MK", "n_authors": 5, "title": "In vivo evolution and selection of recombinant feline leukemia virus species.", "abstract": "Ecotropic feline leukemia viruses subgroup A (FeLV-A) is known to recombine with endogenous FeLV (enFeLV) env elements yielding polytropic FeLV-B viruses. However, scattered nucleotide differences exist between enFeLV env elements and corresponding sequences of exogenous FeLV-B isolates. To address this disparity, we examined recombinant FeLV (rFeLV) viruses obtained from three experimentally-induced feline thymic tumors, along with rFeLVs derived from one naturally-occurring thymic tumor. Two of the three experimental cats were challenged with a FeLV-A/Rickard preparation, while one cat received this FeLV-A along with a mixture of in vitro-generated rFeLVs. The FeLV-A/Rickard preparation employed in this study was shown to be free of detectable rFeLVs since no recombinant products were observed in this preparation following nested PCR analyses. For each of the four tumor DNAs, nucleotide sequence analysis was performed on multiple clones of rFeLV-specific PCR products derived from the surface glycoprotein (SU) portion of the recombinant proviral env gene. Relative to the parental enFeLV sequence used to generate the rFeLVs, a total of 19 nucleotide differences were found scattered within the SU region of the env gene in these in vivo-derived rFeLV clones. Most interestingly, this set of 19 differences led to complete sequence identity with natural FeLV-B isolates. Our results indicate these differences are present early in the in vivo evolution of recombinant viruses, suggesting that rFeLVs harboring these differences are strongly selected. We also present evidence indicating an in vivo selection pattern exists for specific recombinant species containing relatively greater amounts of enFeLV-derived SU sequence. This in vivo selection process appears to be gradual, occurring over the infection timecourse, yielding rFeLV species which have recombination structural motifs similar to those seen in natural FeLV-B isolates.", "journal": "Virus research", "doi": "10.1016/s0168-1702(98)00015-x", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1999, "pmid": "10507363", "author": "Linenberger ML", "n_authors": 6, "title": "Lymphokines modulate the growth and survival of thymic tumor cells containing a novel feline leukemia virus/Notch2 variant.", "abstract": "Tumorigenesis occurs through a multistep process initiated by genetic lesions and facilitated by endogenous and external growth/survival signals. In many malignancies, specific oncogenic mutations correlate with phenotypic characteristics, inferring lineage-specific pathogenic mechanisms. To characterize these relationships in a unique feline tumor, we studied primary cells and two-cell lines independently-derived from a thymic lymphoma that contained and actively expressed a novel feline leukemia virus (FeLV) recombinant with transduced host Notch2 sequences. All three tumor cell populations contained similar FeLV/Notch2 proviral variants and phenotypically resembled mature thymocytes. Multiple Notch2 transcripts were expressed in the cell lines, including species that correspond to viral genomes and spliced subgenomic viral mRNA. Tumor cell line FeLV/Notch2 virus was packaged into virions; however, the variant was not efficiently transmitted to feline cells in vitro. Primary tumor cells constitutively expressed mRNA for interleukin-4 (IL-4), IL-6 and the p40 subunit of IL-12. Lymphokine mRNA was not detected in established tumor cell lines nor was T-cell growth-promoting activity found in culture supernatants. Exogenous IL-4 enhanced primary tumor cell survival, but inhibited proliferation of the cell lines. Interleukin-4 abrogated hydrocortisone-induced apoptosis in all three populations and had divergent effects on cell line clonogenic colony formation. Exogenous IL-7 and, to a lesser degree, IL-6 also had variable positive effects on the growth and viability of the tumor cell populations. Collectively, these data suggest that thymocytes are susceptible to the transforming potential of dysregulated Notch2 and that thymopoietic factors could, through overlapping and distinct mechanisms, promote the survival and outgrowth of FeLV/Notch2-containing neoplastic cells.", "journal": "Veterinary immunology and immunopathology", "doi": "10.1016/s0165-2427(99)00075-6", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1999, "pmid": "10098636", "author": "Bechtel MK", "n_authors": 6, "title": "Recombinant feline leukemia virus (FeLV) variants establish a limited infection with altered cell tropism in specific-pathogen-free cats in the absence of FeLV subgroup A helper virus.", "abstract": "Feline leukemia virus subgroup B (FeLV-B) is commonly associated with feline lymphosarcoma and arises through recombination between endogenous retroviral elements inherited in the cat genome and corresponding regions of the envelope (env) gene from FeLV subgroup A (FeLV-A). In vivo infectivity for FeLV-B is thought to be inefficient in the absence of FeLV-A. Proposed FeLV-A helper functions include enhanced replication efficiency, immune evasion, and replication rescue for defective FeLV-B virions. In vitro analysis of the recombinant FeLV-B-like viruses (rFeLVs) employed in this study confirmed these viruses were replication competent prior to their use in an in vivo study without FeLV-A helper virus. Eight specific-pathogen-free kittens were inoculated with the rFeLVs alone. Subsequent hematology and histology results were within normal limits, however, in the absence of detectable viremia, virus expression, or significant seroconversion, rFeLV proviral DNA was detected in bone marrow tissue of 4/4 (100%) cats at 45 weeks postinoculation (pi), indicating these rFeLVs established a limited but persistent infection in the absence of FeLV-A. Altered cell tropism was also noted. Focal infection was seen in T-cell areas of the splenic follicles in 3/4 (75%) rFeLV-infected cats analyzed, while an FeLV-A-infected cat showed focal infection in B-cell areas of the splenic follicles. Nucleotide sequence analysis of the surface glycoprotein portion of the rFeLV env gene amplified from bone marrow tissue collected at 45 weeks pi showed no sequence alterations from the original rFeLV inocula.", "journal": "Veterinary pathology", "doi": "10.1354/vp.36-2-91", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 1999, "pmid": "10051606", "author": "Rasko JE", "n_authors": 5, "title": "The RD114/simian type D retrovirus receptor is a neutral amino acid transporter.", "abstract": "The RD114/simian type D retroviruses, which include the feline endogenous retrovirus RD114, all strains of simian immunosuppressive type D retroviruses, the avian reticuloendotheliosis group including spleen necrosis virus, and baboon endogenous virus, use a common cell-surface receptor for cell entry. We have used a retroviral cDNA library approach, involving transfer and expression of cDNAs from highly infectable HeLa cells to nonpermissive NIH 3T3 mouse cells, to clone and identify this receptor. The cloned cDNA, denoted RDR, is an allele of the previously cloned neutral amino acid transporter ATB0 (SLC1A5). Both RDR and ATB0 serve as retrovirus receptors and both show specific transport of neutral amino acids. We have localized the receptor by radiation hybrid mapping to a region of about 500-kb pairs on the long arm of human chromosome 19 at q13.3. Infection of cells with RD114/type D retroviruses results in impaired amino acid transport, suggesting a mechanism for virus toxicity and immunosuppression. The identification and functional characterization of this retrovirus receptor provide insight into the retrovirus life cycle and pathogenesis and will be an important tool for optimization of gene therapy using vectors derived from RD114/type D retroviruses.", "journal": "Proceedings of the National Academy of Sciences of the United States of America", "doi": "10.1073/pnas.96.5.2129", "deposited_data": "Sim", "nuccore_ids": "1676325246, 1676318081, 1519241848, 4191561, 4191555, 1907178718, 1907178716, 1676325246, 1676318081, 1519241848, 114326473", "bioproject_ids": null, "sra_ids": null}, {"year": 2000, "pmid": "11199261", "author": "Gladow M", "n_authors": 4, "title": "MLV-10A1 retrovirus pseudotype efficiently transduces primary human CD4+ T lymphocytes.", "abstract": "Previously, we showed that retroviral vectors pseudotyped with the envelope of the amphotropic murine leukemia virus 10A1 (MLV-10A1) more efficiently transduce primary human CD8+ T lymphocytes when compared with other A-MLV, gibbon ape leukemia virus (GaLV) and feline endogenous retrovirus (RD114) vector pseudotypes. For the success of several gene therapeutic approaches (ADA, HIV) it is important to effectively transduce primary human CD4+ T lymphocytes. We have used retroviral vectors encoding the enhanced green fluorescent protein (EGFP) as a marker gene and carrying envelopes of MLV-10A1, A-MLV and GaLV and have analyzed the transduction efficiency of both human CD4+ T cell lines (CEM, H9, HUT78, J16) and primary human CD4+ T lymphocytes using a RetroNectin-assisted transduction protocol and virus-containing supernatant. In CD4+ T cell lines the MLV-10A1 vector pseudotype was most effective and infected up to 85% of cells which then stably expressed GFP over time. MLV-10A1 was also superior and infected approximately 32% of primary human CD4+ T lymphocytes in comparison to GaLV (18%) and A-MLV (12%). The superior efficiency of MLV-10A1 for the transduction of CD4+ T cells correlates with the longer half-life of this pseudotype in comparison to A-MLV and, as previously shown by interference analysis, with the usage of both the A-MLV (Pit2) and the GaLV receptor (Pitl) for cell entry. MLV-10A1 is a suitable vector for transferring genes with high efficacy into primary human CD4+ T lymphocytes. The use of MLV-10A1 pseudotyped vectors should make it easier to obtain a sufficient number of gene-modified T lymphocytes for an adoptive transfer.", "journal": "The journal of gene medicine", "doi": "10.1002/1521-2254(200011/12)2:6<409::AID-JGM144>3.0.CO;2-K", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2000, "pmid": "11062034", "author": "Phipps AJ", "n_authors": 5, "title": "Inhibition of feline leukemia virus subgroup A infection by coinoculation with subgroup B.", "abstract": "Feline leukemia virus (FeLV) subgroup B arises de novo through recombination between the env genes of exogenous FeLV subgroup A and endogenous FeLV-like sequences. FeLV-B, which by itself is poorly infectious, will increase to high titer in the presence of FeLV-A, and is associated with FeLV-related neoplastic disease. Although the participation of FeLV-B in disease progression has not been definitively proven, circumstantial evidence supports the hypothesis that the generation of FeLV-B is linked to disease progression. The present study was designed to evaluate whether increasing the levels of FeLV-B early in FeLV-A infection could result in reduction of the incubation period for development of neoplastic disease. For this study, an isolate of FeLV-B, designated FeLV-1B3, was biologically cloned, partially sequenced, and subgroup typed. In in vivo studies, none of the neonatal cats inoculated with FeLV-1B3 alone converted to viremia positive, and all remained healthy throughout the observation period. All of the kittens inoculated with FeLV-A alone became chronically viremic, and those held for long-term observation all developed either neoplastic disease or anemia. However, kittens inoculated with the combination of FeLV-1B3 and FeLV-A showed attenuated infections whereby the majority of cats failed to develop chronic viremia. The apparent interference of FeLV-A infection by FeLV-B was time and titer dependent. This unexpected result suggests that FeLV-B may act as an attenuated virus, causing inhibition of FeLV-A possibly through an immune-mediated mechanism. Partial support for this view was provided by postmortem examination of cats inoculated with FeLV-1B3 alone. Even though none of these cats became viremic, FeLV antigen was detected as focal infections in select tissues, especially salivary gland epithelium, where enough antigen may be expressed to provide an immunizing dose against gag and pol cross-reacting antigens. This work may also provide another approach to vaccine development based on endogenous retrovirus vector systems.", "journal": "Virology", "doi": "10.1006/viro.2000.0606", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2000, "pmid": "11000257", "author": "Tailor CS", "n_authors": 3, "title": "Cellular and species resistance to murine amphotropic, gibbon ape, and feline subgroup C leukemia viruses is strongly influenced by receptor expression levels and by receptor masking mechanisms.", "abstract": "Chinese hamster ovary (CHO) cells are resistant to infections by gibbon ape leukemia virus (GALV) and amphotropic murine leukemia virus (A-MLV) unless they are pretreated with tunicamycin, an inhibitor of N-linked glycosylation. These viruses use the related sodium-phosphate symporters Pit1 and Pit2, respectively, as receptors in nonhamster cells, and evidence has suggested that the corresponding transporters of CHO cells may be masked by tunicamycin-sensitive secreted inhibitors. Although the E36 line of Chinese hamster cells was reported to secrete the putative Pit2 inhibitor and to be sensitive to the inhibitory CHO factors, E36 cells are highly susceptible to both GALV and A-MLV in the absence of tunicamycin. Moreover, expression of E36 Pit2 in CHO cells conferred tunicamycin-independent susceptibilities to both viruses. Based on the latter results, it was suggested that E36 Pit2 must functionally differ from the endogenous Pit2 of CHO cells. To test these ideas, we analyzed the receptor properties of CHO Pit1 and Pit2 in CHO cells. Surprisingly, and counterintuitively, transfection of a CHO Pit2 expression vector into CHO cells conferred strong susceptibility to both GALV and A-MLV, and similar overexpression of CHO Pit1 conferred susceptibility to GALV. Thus, CHO Pit2 is a promiscuous functional receptor for both viruses, and CHO Pit1 is a functional receptor for GALV. Similarly, we found that the natural resistance of Mus dunni tail fibroblasts to subgroup C feline leukemia viruses (FeLV-C) was eliminated simply by overexpression of the endogenous FeLV-C receptor homologue. These results demonstrate a novel and simple method to unmask latent retroviral receptor activities that occur in some cells. Specifically, resistances to retroviruses that are caused by subthreshold levels of receptor expression or by stoichiometrically limited masking or interference mechanisms can be efficiently overcome simply by overexpressing the endogenous receptors in the same cells.", "journal": "Journal of virology", "doi": "10.1128/jvi.74.20.9797-9801.2000", "deposited_data": "Sim", "nuccore_ids": "345842528, 10716881, 10716879, 1868056668, 1868056667, 1868056666, 345842528", "bioproject_ids": null, "sra_ids": null}, {"year": 2000, "pmid": "11000248", "author": "Ghosh SK", "n_authors": 3, "title": "Long terminal repeat regions from exogenous but not endogenous feline leukemia viruses transactivate cellular gene expression.", "abstract": "We have previously reported that the long terminal repeat (LTR) region of feline leukemia viruses (FeLVs) can enhance expression of certain cellular genes such as the collagenase IV gene and MCP-1 in trans (S. K. Ghosh and D. V. Faller, J. Virol. 73:4931-4940, 1999). Genomic DNA of all healthy feline species also contains LTR-like sequences that are related to exogenous FeLV LTRs. In this study, we evaluated the cellular gene transactivational potential of these endogenous FeLV LTR sequences. Unlike their exogenous FeLV counterparts, neither nearly full-length endogenous FeLV molecular clones (CFE-6 and CFE-16) nor their isolated LTRs were able to activate collagenase IV gene or MCP-1 expression in transient transfection assays. We had also demonstrated previously that production of an RNA transcript from exogenous FeLV LTRs correlates with their transactivational activity. In the present study, we demonstrate that the endogenous FeLV LTRs do not generate LTR-specific RNA transcripts in the feline embryo fibroblast cell line AH927. Furthermore, infection of AH927 cells by an exogenous FeLV subgroup A virus did not induce production of such LTR-specific transcripts from the endogenous proviral genomes, although the LTR-specific transcripts from the exogenous virus were readily detected. Finally, LTR-specific transcripts were not generated in BALB/3T3 cells transiently transfected with isolated CFE-6 LTR, in contrast to transfections with LTRs from exogenous viruses. Our data thus suggest that the inability of endogenous FeLV LTRs in gene transactivation is not due to cell line specificity or presence of any upstream inhibitory cis-acting element. Endogenous, nonleukemogenic FeLV LTRs, therefore, do not transactivate cellular gene expression, and this property appears to be specific to exogenous, leukemogenic FeLVs.", "journal": "Journal of virology", "doi": "10.1128/jvi.74.20.9742-9748.2000", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2000, "pmid": "10942359", "author": "Kelly PF", "n_authors": 5, "title": "Highly efficient gene transfer into cord blood nonobese diabetic/severe combined immunodeficiency repopulating cells by oncoretroviral vector particles pseudotyped with the feline endogenous retrovirus (RD114) envelope protein.", "abstract": "Limited expression of the amphotropic envelope receptor is a recognized barrier to efficient oncoretroviral vector-mediated gene transfer. Human hematopoietic cell lines and cord blood-derived CD34(+) and CD34(+), CD38(-) cell populations and the progenitors contained therein were transduced far more efficiently with oncoretroviral particles pseudotyped with the envelope protein of feline endogenous virus (RD114) than with conventional amphotropic vector particles. Similarly, human repopulating cells from umbilical cord blood capable of establishing hematopoiesis in immunodeficient mice were efficiently transduced with RD114-pseudotyped particles, whereas amphotropic particles were ineffective at introducing the proviral genome. After only a single exposure of CD34(+) cord blood cells to RD114-pseudotyped particles, all engrafted nonobese diabetic/severe combined immunodeficiency mice (15 of 15) contained genetically modified human bone marrow cells. Human cells that were positive for enhanced green fluorescent protein represented as much as 90% of the graft. The use of RD114-pseudotyped vectors may be advantageous for therapeutic gene transfer into hematopoietic stem cells. (Blood. 2000;96:1206-1214)", "journal": "Blood", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2000, "pmid": "10852967", "author": "Rasko JE", "n_authors": 5, "title": "Precise gene localization by phenotypic assay of radiation hybrid cells.", "abstract": "A high resolution map of the human genome previously has been constructed by using the G3 panel of human/hamster radiation hybrid cell lines and >15,000 unique human genetic markers. By determining whether human DNA sequences are present or absent in each of the hybrids, localization of single genes may routinely be achieved at approximately 250-kb resolution. In this paper we have tested whether similarly precise localization might be achieved by phenotypic screening of the hybrids to facilitate positional cloning of unknown genes. We assayed the susceptibility of each of the hybrid cell lines to transduction by retroviral vectors bearing different retroviral envelope proteins that recognize receptors present on human but not on hamster cells. The results for each of the retroviral vectors were informative and allowed precise localization of the receptor genes for the RD114 cat endogenous retrovirus, xenotropic murine leukemia virus, and type C feline leukemia virus. After cloning of the receptors for these retroviruses, we found that standard genotypic mapping by PCR gave results that were nearly identical to those from phenotypic mapping. These experiments show that precise gene localization by phenotypic assay of radiation hybrids is practical and was not appreciably impacted by the known instability of such hybrid cells. This technique should be applicable to many other human genes having discernible phenotypes in hamster cells and, with completion of the human genome project, will allow rapid identification of unknown genes on the basis of phenotype.", "journal": "Proceedings of the National Academy of Sciences of the United States of America", "doi": "10.1073/pnas.130200097", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2000, "pmid": "10846058", "author": "Phipps AJ", "n_authors": 5, "title": "Differential pathogenicity of two feline leukemia virus subgroup A molecular clones, pFRA and pF6A.", "abstract": "F6A, a molecular clone of subgroup A feline leukemia virus (FeLV) is considered to be highly infectious but weakly pathogenic. In recent studies with a closely related subgroup A molecular clone, FRA, we demonstrated high pathogenicity and a strong propensity to undergo recombination with endogenous FeLV (enFeLV), leading to a high frequency of transition from subgroup A to A/B. The present study was undertaken to identify mechanisms of FeLV pathogenesis that might become evident by comparing the two closely related molecular clones. F6A was shown to have an infectivity similar to that of FRA when delivered as a provirus. Virus load and antibody responses were also similar, although F6A-infected cats consistently carried higher virus loads than FRA-infected cats. However, F6A-infected cats were slower to undergo de novo recombination with enFeLV and showed slower progression to disease than FRA-infected cats. Tumors collected from nine pF6A- or pFRA-inoculated cats expressed lymphocyte markers for T cells (seven tumors) and B cells (one tumor), and non-T/B cells (one tumor). One cat with an A-to-A/C conversion developed erythrocyte hypoplasia. Genomic mapping of recombinants from pF6A- and pFRA-inoculated cats revealed similar crossover sites, suggesting that the genomic makeup of the recombinants did not contribute to increased progression to neoplastic disease. From these studies, the mechanism most likely to account for the pathologic differences between F6A and FRA is the lower propensity for F6A to undergo de novo recombination with enFeLV in vivo. A lower recombination rate is predicted to slow the transition from subgroup A to A/B and slow the progression to disease.", "journal": "Journal of virology", "doi": "10.1128/jvi.74.13.5796-5801.2000", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2001, "pmid": "11763193", "author": "Kidney BA", "n_authors": 4, "title": "Comparison of endogenous feline leukemia virus RNA content in feline vaccine and nonvaccine site-associated sarcomas.", "abstract": "To determine whether feline vaccine site-associated sarcomas (VSS) contain a higher amount of endogenous FeLV (enFeLV) RNA, compared with feline nonvaccine site-associated sarcomas (non-VSS). Formalin-fixed paraffin-embedded (FFPE) tissues from 50 VSS and 50 cutaneous non-VSS. RNA was extracted from FFPE sections of each tumor, and regions of the long terminal repeat (LTR) and envelope (env) gene of enFeLV were amplified by use of reverse transcriptase-polymerase chain reaction (RT-PCR). The density of each RT-PCR product band for enFeLV was compared with that of a constitutively expressed gene, glyceraldehyde-3-phosphate dehydrogenase (GAPDH). An integrated density value (IDV) was determined by use of densitometry, and the IDV ratio for enFeLV to GAPDH was calculated for each enFeLV primer set. The median (interquartile range) of the IDV ratio for the enFeLV LTR primer set was 0.52 (0.26 to 1.17) for the VSS group and 0.84 (0.21 to 1.53) for the non-VSS group. The median (interquartile range) of the IDV ratio for the enFeLV env primer set was 0.60 (0.37 to 0.91) for the VSS group and 0.59 (0.36 to 1.09) for the non-VSS group. Because the amount of enFeLV RNA within the LTR and env gene was not significantly different between the VSS and non-VSS groups, enFeLV replication or expression is unlikely to be involved in VSS development.", "journal": "American journal of veterinary research", "doi": "10.2460/ajvr.2001.62.1990", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2001, "pmid": "11602698", "author": "Anderson MM", "n_authors": 5, "title": "Feline Pit2 functions as a receptor for subgroup B feline leukemia viruses.", "abstract": "Different subgroups of feline leukemia virus (FeLV) use different host cell receptors for entry. Subgroup A FeLV (FeLV-A) is the virus that is transmitted from cat to cat, suggesting that cells expressing the FeLV-A receptor are important targets at the earliest stages of infection. FeLV-B evolves from FeLV-A in the infected cat through acquisition of cellular sequences that are related to the FeLV envelope gene. FeLV-Bs have been shown to infect cells using the Pit1 receptor, and some variants can infect cells at a lower efficiency using Pit2. Because these observations were made using receptor proteins of human or rodent origin, the role that Pit1 and Pit2 may play in FeLV-B replication in the cat is unclear. In this study, the feline Pit receptors were cloned and tested for their ability to act as receptors for different FeLV-Bs. Some FeLV-Bs infected cells expressing feline Pit2 and feline Pit1 with equal high efficiency. Variable region A (VRA) in the putative receptor-binding domain (RBD) was a critical determinant for both feline Pit1 and feline Pit2 binding, although other domains in the RBD appear to influence how efficiently the FeLV-B surface unit can bind to feline Pit2 and promote entry via this receptor. An arginine residue at position 73 in VRA was found to be important for envelope binding to feline Pit2 but not feline Pit1. Interestingly, this arginine is not found in endogenous FeLV sequences or in recombinant viruses recovered from feline cells infected with FeLV-A. Thus, while FeLV-Bs that are able to use feline Pit2 can evolve by recombination with endogenous sequences, a subsequent point mutation during reverse transcription may be needed to generate a virus that can efficiently enter the cells using the feline Pit2 as its receptor. These studies suggest that cells expressing the feline Pit2 protein are likely to be targets for FeLV-B infection in the cat.", "journal": "Journal of virology", "doi": "10.1128/JVI.75.22.10563-10572.2001", "deposited_data": "Sim", "nuccore_ids": "57618972, 15559051, 14916034, 2130946720, 2130946717, 2130946715, 2130946709, 2130946706, 2130946701, 2130946697, 2130946695, 2130946693, 2130946690, 57618972", "bioproject_ids": null, "sra_ids": null}, {"year": 2001, "pmid": "11559834", "author": "Gatlin J", "n_authors": 5, "title": "Engraftment of NOD/SCID mice with human CD34(+) cells transduced by concentrated oncoretroviral vector particles pseudotyped with the feline endogenous retrovirus (RD114) envelope protein.", "abstract": "Oncoretrovirus vectors pseudotyped with the feline endogenous retrovirus (RD114) envelope protein produced by the FLYRD18 packaging cell line have previously been shown to transduce human hematopoietic progenitor cells with a greater efficiency than similar amphotropic envelope-pseudotyped vectors. In this report, we describe the production and efficient concentration of RD114-pseudotyped murine leukemia virus (MLV)-based vectors. Following a single round of centrifugation, vector supernatants were concentrated approximately 200-fold with a 50 to 70% yield. Concentrated vector stocks transduced prestimulated human CD34(+) (hCD34(+)) cells with approximately 69% efficiency (n = 7, standard deviation = 4.4%) using a single addition of vector at a low multiplicity of infection (MOI = 5). Introduction of transduced hCD34(+) cells into irradiated NOD/SCID recipients resulted in multilineage engraftment with long-term transgene expression. These data demonstrate that RD114-pseudotyped MLV-based vectors can be efficiently concentrated to high titers and that hCD34(+) cells transduced with concentrated vector stocks retain in vivo repopulating potential. These results highlight the potential of RD114-pseudotyped oncoretrovirus vectors for future clinical implementation in hematopoietic stem cell gene transfer.", "journal": "Journal of virology", "doi": "10.1128/JVI.75.20.9995-9999.2001", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2001, "pmid": "11533152", "author": "Lauring AS", "n_authors": 3, "title": "Specificity in receptor usage by T-cell-tropic feline leukemia viruses: implications for the in vivo tropism of immunodeficiency-inducing variants.", "abstract": "Cytopathic, T-cell-tropic feline leukemia viruses (FeLV-T) evolve from FeLV-A in infected animals and demonstrate host cell specificities that are distinct from those of their parent viruses. We recently identified two cellular proteins, FeLIX and Pit1, required for productive infection by these immunodeficiency-inducing FeLV-T variants (M. M. Anderson, A. S. Lauring, C. C. Burns, and J. Overbaugh, Science 287:1828-1830, 2000). FeLV-T is the first example of a naturally occurring type C retrovirus that requires two proteins to gain entry into target cells. FeLIX is an endogenous protein that is highly related to the N-terminal portion of the FeLV envelope protein, which includes the receptor-binding domain. Pit1 is a multiple-transmembrane phosphate transport protein that also functions as a receptor for FeLV-B. The FeLV-B envelope gene is derived by recombination with endogenous FeLV-like sequences, and its product can functionally substitute for FeLIX in facilitating entry through the Pit1 receptor. In the present study, we tested other retrovirus envelope surface units (SUs) with their cognate receptors to determine whether they also could mediate infection by FeLV-T. Cells were engineered to coexpress the transmembrane form of the envelope proteins and their cognate receptors, or SU protein was added as a soluble protein to cells expressing the receptor. Of the FeLV, murine leukemia virus, and gibbon ape leukemia virus envelopes tested, we found that only those with receptor-binding domains derived from endogenous FeLV could render cells permissive for FeLV-T. We also found that there is a strong preference for Pit1 as the transmembrane receptor. Specifically, FeLV-B SUs could efficiently mediate infection of cells expressing the Pit1 receptor but could only inefficiently mediate infection of cells expressing the Pit2 receptor, even though these SUs are able to bind to Pit2. Expression analysis of feline Pit1 and FeLIX suggests that FeLIX is likely the primary determinant of FeLV-T tropism. These results are discussed in terms of current models for retrovirus entry and the interrelationship among FeLV variants that evolve in vivo.", "journal": "Journal of virology", "doi": "10.1128/JVI.75.19.8888-8898.2001", "deposited_data": "Sim", "nuccore_ids": "1676319575, 1653961537", "bioproject_ids": null, "sra_ids": null}, {"year": 2001, "pmid": "11507228", "author": "Chang Z", "n_authors": 5, "title": "A replication-competent feline leukemia virus, subgroup A (FeLV-A), tagged with green fluorescent protein reporter exhibits in vitro biological properties similar to those of the parental FeLV-A.", "abstract": "We previously established that lymphoid tumors could be induced in cats by intradermal injection of ecotropic feline leukemia virus (FeLV), subgroup A, plasmid DNA. In preparation for in vivo experiments to study the cell-to-cell pathway for the spread of the virus from the site of inoculation, the green fluorescent protein (GFP) transgene fused to an internal ribosome entry site (IRES) was inserted after the last nucleotide of the env gene in the ecotropic FeLV-A Rickard (FRA) provirus. The engineered plasmid was transfected into feline fibroblast cells for production of viruses and determination of GFP expression. The virions produced were highly infectious, and the infected cells could continue to mediate strong expression of GFP after long-term propagation in culture. Similar to parental virus, the transgene-containing ecotropic virus demonstrated recombinogenic activity with endogenous FeLV sequences in feline cells to produce polytropic recombinant FeLV subgroup B-like viruses which also contained the IRES-GFP transgene in the majority of recombinants. To date, the engineered virus has been propagated in cell culture for up to 8 months without diminished GFP expression. This is the first report of a replication-competent FeLV vector with high-level and stable expression of a transgene.", "journal": "Journal of virology", "doi": "10.1128/jvi.75.18.8837-8841.2001", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2001, "pmid": "11209087", "author": "Hanazono Y", "n_authors": 3, "title": "Gene transfer into nonhuman primate hematopoietic stem cells: implications for gene therapy.", "abstract": "Hematopoietic stem cells (HSCs) are desirable targets for gene therapy because of their self-renewal and multilineage differentiation abilities. Retroviral vectors are extensively used for HSC gene therapy. However, the initial human trials of HSC gene marking and therapy showed that the gene transfer efficiency into human HSCs with retroviral vectors was very low in contrast to the much higher efficiency observed in murine experiments. The more quiescent nature of human HSCs and the lower density of retroviral receptors on them hindered the efficient gene transfer with retroviral vectors. Since nonhuman primates have marked similarity to humans in all aspects including the HSC biology, their models are considered to be important to evaluate and improve gene transfer into human HSCs. Using these models, clinically relevant levels (around 10% or even more) of gene-modified cells in peripheral blood have recently been achieved after gene transfer into HSCs and their autologous transplantation. This has been made possible by improving ex vivo transduction conditions such as introduction of Flt-3 ligand and specific fibronectin fragment (CH-296) into ex vivo culture during transduction, and the use of retroviral vectors pseudotyped with the gibbon ape leukemia virus or feline endogenous retrovirus envelope. Other strategies including the use of lentiviral vectors and in vivo selective expansion of gene-modified cells with the drug resistance gene or selective amplifier gene (also designated the molecular growth switch) are now being tested to further increase the fraction of gene-modified cells using nonhuman primate models. In addition to the high gene transfer efficiency, high-level and long-term expression of transgenes in human HSCs and their progeny is also required for effective HSC gene therapy. For this purpose, other backbones of retroviral vectors such as the murine stem cell virus and cis-DNA elements, such as the ss-globin locus control region and the chromatin insulator, also need to be tested in nonhuman primate models. Nonhuman primate studies will continue to provide an important framework for human HSC gene therapy. Well-designed nonhuman primate studies will also offer unique insights into the HSCs, immune system, and transplantation biology characteristic of large animals.", "journal": "Stem cells (Dayton, Ohio)", "doi": "10.1634/stemcells.19-1-12", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2002, "pmid": "12180842", "author": "Specke V", "n_authors": 8, "title": "Virus safety in xenotransplantation: first exploratory in vivo studies in small laboratory animals and non-human primates.", "abstract": "For xenotransplantation, the transplantation of animal cells, tissues and organs into human recipients, to date, pigs are favored as potential donors. Beside ethical, immunological, physiological and technical problems, the microbiological safety of the xenograft has to be guaranteed. It will be possible to eliminate all of the known porcine microorgansims in the nearby future by vaccinating or specified pathogen-free breeding. Thus, the main risk will come from the porcine endogenous retroviruses (PERVs) which are present in the pig genome as proviruses of different subtypes. PERVs will therefore be transmitted, with the xenograft, to the human recipient. PERVs can infect numerous different types of human primary cells and cell lines in vitro and were shown to adapt to these cells by serial passaging on uninfected cells. Furthermore, PERVs have high homology to other retroviruses, such as feline leukemia virus (FeLV) or murine leukemia virus (MuLV), which are known to induce tumors or immunodeficiencies in the infected host. To evaluate the potential risk of a trans-species transmission of PERV in vivo, naive and immunosuppressed rats, guinea pigs and minks were inoculated with PERV and screened over a period of 3 months for an antibody reaction against PERV proteins or for the integration of proviral DNA into the genomic DNA of the host's cells. Furthermore, we inoculated three different species of non-human primates, rhesus monkey (Macaca mulatta), pig-tailed monkey (Macaca nemestrina) and baboon (Papio hamadryas) with high titers of a human-adapted PERV. To simulate a situation in xenotransplantation, the animals received a daily triple immunosuppression using cyclosporine A, methylprednisolone and RAD, a rapamycin derivative, presently under development by Novartis. None of the small laboratory animals or the non-human primates showed production of antibodies against PERV or evidence of integration of proviral DNA in blood cells or cells of several organs, 3 months after virus inoculation, despite the observation that cells of the animals used in the experiment were infectible in vitro. This apparent difference in the outcome of the in vitro and the in vivo data might be explained by an efficient elimination of the virus by the innate or adaptive immunity of the animals.", "journal": "Transplant immunology", "doi": "10.1016/s0966-3274(02)00039-4", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2002, "pmid": "12134012", "author": "Lauring AS", "n_authors": 4, "title": "Genetic and biochemical analyses of receptor and cofactor determinants for T-cell-tropic feline leukemia virus infection.", "abstract": "Entry by retroviruses is mediated through interactions between the viral envelope glycoprotein and the host cell receptor(s). We recently identified two host cell proteins, FeLIX and Pit1, that are necessary for infection by cytopathic, T-cell-tropic feline leukemia viruses (FeLV-T). Pit1 is a classic multiple transmembrane protein used as a receptor by several other simple retroviruses, including subgroup B FeLV (FeLV-B), and FeLIX is a secreted cellular protein expressed from endogenous FeLV-related sequences (enFeLV). FeLIX is nearly identical to FeLV-B envelope sequences that encode the N-terminal half of the viral surface unit (SU), because these FeLV-B sequences are acquired by recombination with enFeLV. FeLV-B SUs can functionally substitute for FeLIX in mediating FeLV-T infection. Both of these enFeLV-derived cofactors can efficiently facilitate FeLV-T infection only of cells expressing Pit1, not of cells expressing the related transport protein Pit2. We therefore have used chimeric Pit1/Pit2 receptors to map the determinants for cofactor binding and FeLV-T infection. Three distinct determinants appear to be required for cofactor-dependent infection by FeLV-T. We also found that Pit1 sequences within these same domains were required for binding by FeLIX to the Pit receptor. In contrast, these determinants were not all required for receptor binding by the FeLV-B SU cofactors used in this study. These data indicate that cofactor binding is not sufficient for FeLV-T infection and suggest that there may be a direct interaction between FeLV-T and the Pit1 receptor.", "journal": "Journal of virology", "doi": "10.1128/jvi.76.16.8069-8078.2002", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2002, "pmid": "11815291", "author": "Miyazawa T", "n_authors": 1, "title": "Infections of feline leukemia virus and feline immunodeficiency virus.", "abstract": "Feline retrovirus infections have been extensively studied for more than 30 years as an animal model for the persistent infections and pathogenesis caused by retroviruses in general. Two retroviruses, feline leukemia virus (FeLV) and feline immunodeficiency virus (FIV), have been recognized as causative agents of a variety of diseases including proliferative and degenerative diseases. Recent studies revealed the receptors of FeLV, its variants and FIV. FeLVs utilize at least three distinct receptors, two of which have been successfully cloned and characterized. Furthermore, an FeLV variant which induces severe immunodeficiency, utilizes a truncated envelope of the endogenous FeLV as coreceptor or cofactor for viral entry. FIV utilizes as receptor one of the chemokine receptors, CXCR4 which also is a coreceptor for the T-lymphotropic human immunodeficiency virus. This review provides an overview to the infections of FeLV and FIV, specifically focuses on the viral genomic structures, FeLV variants, the immune responses and recent findings on the receptors for FeLV and FIV. Better understanding of retroviral persistence and pathogenesis will aid the development of prophylactic vaccines and therapeutic medicine to interfere with retrovirus infections.", "journal": "Frontiers in bioscience : a journal and virtual library", "doi": "10.2741/A791", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2003, "pmid": "14708522", "author": "Kurihara T", "n_authors": 8, "title": "Sensitivity to human serum of gammaretroviruses produced from pig endothelial cells transduced with glycosyltransferase genes.", "abstract": "Reduction of pig cell-surface alpha-galactosyl (Gal) epitope, Galalpha1, 3Galbeta1, 4GlcNAc-R, by the introduction of glycosyltransferase genes is effective in suppressing hyperacute rejection (HAR) in pig-to-human xenotransplantation. The transmission of porcine endogenous retroviruses (PERVs) has been recognized as a potential risk factor associated with xenotransplantation. In this study, effects of the introduction of glycosyltransferase genes to pig cells on the sensitivity of gammaretroviruses to human serum were investigated. Pig endothelial cells (PEC), PEC transduced with alpha1,2 fucosyltransferase (FT), alpha2,3 sialyltransferase (ST), or N-acetylglucosaminyltransferase III (GnT-III), and human embryonic kidney (HEK) 293 cells were transduced with the LacZ gene with the packaging signal of murine leukemia virus (MuLV) under the control of the long terminal repeat of MuLV by a pseudotype infection. Then, the cells were further infected with PERV subtype B (PERV-B) or feline leukemia virus subgroup B (FeLV-B). Culture supernatants of the infected cells were mixed with human serum (HS) and then inoculated to HEK293 cells. The inoculated cells were histochemically stained and lacZ-positive blue foci were counted. Glycosyltransferase activity, xenoantigenicity, and alpha-Gal epitope density in the cells were measured at the time of the infection experiments. PERV-B or FeLV-B particles from the parental PEC were efficiently neutralized by HS, while those from PEC transduced with alpha1,2FT, alpha2,3ST or GnT-III were less sensitive to HS. The transduced PEC exhibited high levels of activity of the introduced glycotransferases, and expressed fewer xenoantigens and cell-surface alpha-Gal epitopes. Our results suggest that gammaretroviruses including PERVs produced by transgenic pigs, that are generally modified to reduce the cell-surface alpha-Gal epitope to overcome the HAR in xenotransplantation, are less sensitive to HS.", "journal": "Xenotransplantation", "doi": "10.1034/j.1399-3089.2003.00056.x", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2003, "pmid": "14529834", "author": "Hu J", "n_authors": 7, "title": "Direct comparison of RD114-pseudotyped versus amphotropic-pseudotyped retroviral vectors for transduction of rhesus macaque long-term repopulating cells.", "abstract": "Recently, RD114 (feline endogenous retrovirus envelope protein)-pseudotyped retroviral particles have been shown to transduce human NOD/SCID repopulating cells efficiently. In this study, we compared directly transduction of repopulating cells with RD114-pseudotyped vector to that with standard amphotropic vector in the rhesus macaque model. G-CSF/SCF-mobilized CD34(+) rhesus peripheral blood cells were cultured in the presence of SCF, Flt-3 ligand, and MGDF on Retronectin-coated flasks. To assess directly the ability of the two pseudotypes to transduce primitive cells, both vectors were added simultaneously to the target cells every 24 h, for a total of four exposures in 96 h. The cells were reinfused after the animals received 1000 cGy total body irradiation. At the end of transduction, gene marking efficiency of CFU was higher with amphotropic LNL6 vector (mean 88.4%) vs RD114-G1Na vector (mean 18.5%). After long-term engraftment in three animals, total neo gene marking levels were 4-5% in PBMNCs and 1.5-4% in granulocytes. The RD114-G1Na marking levels were consistently higher in granulocytes than in mononuclear cells, while amphotropic LNL6 marking levels were higher in PBMNCs than in granulocytes. The differential gene marking patterns suggest that RD114 and amphotropic vectors may target distinct progenitor or stem cell populations. There was no clear advantage for RD114-pseudotyped vectors in this predictive preclinical model in terms of overall long-term marking levels; however, optimization of transduction conditions by increasing m.o.i. or inducing the receptor could potentially improve results with this novel vector system.", "journal": "Molecular therapy : the journal of the American Society of Gene Therapy", "doi": "10.1016/s1525-0016(03)00239-9", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2003, "pmid": "12552012", "author": "Barnett AL", "n_authors": 5, "title": "Structure and mechanism of a coreceptor for infection by a pathogenic feline retrovirus.", "abstract": "Infection of T lymphocytes by the cytopathic retrovirus feline leukemia virus subgroup T (FeLV-T) requires FeLIX, a cellular coreceptor that is encoded by an endogenous provirus and closely resembles the receptor-binding domain (RBD) of feline leukemia virus subgroup B (FeLV-B). We determined the structure of FeLV-B RBD, which has FeLIX activity, to a 2.5-A resolution by X-ray crystallography. The structure of the receptor-specific subdomain of this glycoprotein differs dramatically from that of Friend murine leukemia virus (Fr-MLV), which binds a different cell surface receptor. Remarkably, we find that Fr-MLV RBD also activates FeLV-T infection of cells expressing the Fr-MLV receptor and that FeLV-B RBD is a competitive inhibitor of infection under these conditions. These studies suggest that FeLV-T infection relies on the following property of mammalian leukemia virus RBDs: the ability to couple interaction with one of a variety of receptors to the activation of a conserved membrane fusion mechanism. A comparison of the FeLV-B and Fr-MLV RBD structures illustrates how receptor-specific regions are linked to conserved elements critical for postbinding events in virus entry.", "journal": "Journal of virology", "doi": "10.1128/jvi.77.4.2717-2729.2003", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2004, "pmid": "15194792", "author": "Sandrin V", "n_authors": 4, "title": "Intracellular trafficking of Gag and Env proteins and their interactions modulate pseudotyping of retroviruses.", "abstract": "Glycoproteins derived from most retroviruses and from several families of enveloped viruses can form infectious pseudotypes with murine leukemia virus (MLV) and lentiviral core particles, like the MLV envelope glycoproteins (Env) that are incorporated on either virus type. However, coexpression of a given glycoprotein with heterologous core proteins does not always give rise to highly infectious viral particles, and restrictions on pseudotype formation have been reported. To understand the mechanisms that control the recruitment of viral surface glycoproteins on lentiviral and retroviral cores, we exploited the fact that the feline endogenous retrovirus RD114 glycoprotein does not efficiently pseudotype lentiviral cores derived from simian immunodeficiency virus, whereas it is readily incorporated onto MLV particles. Our results indicate that recruitment of glycoproteins by the MLV and lentiviral core proteins occurs in intracellular compartments and not at the cell surface. We found that Env and core protein colocalization in intracytoplasmic vesicles is required for pseudotype formation. By investigating MLV/RD114 Env chimeras, we show that signals in the cytoplasmic tail of either glycoprotein differentially influenced their intracellular localization; that of MLV allows endosomal localization and hence recruitment by both lentiviral and MLV cores. Furthermore, we found that upon membrane binding, MLV core proteins could relocalize Env glycoproteins in late endosomes and allow their incorporation on viral particles. Thus, intracellular colocalization, as well as interactions between Env and core proteins, may influence the recruitment of the glycoprotein onto viral particles and generate infectious pseudotyped viruses.", "journal": "Journal of virology", "doi": "10.1128/JVI.78.13.7153-7164.2004", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2004, "pmid": "15047851", "author": "Roca AL", "n_authors": 3, "title": "Genomically intact endogenous feline leukemia viruses of recent origin.", "abstract": "We isolated and sequenced two complete endogenous feline leukemia viruses (enFeLVs), designated enFeLV-AGTT and enFeLV-GGAG. In enFeLV-AGTT, the open reading frames are reminiscent of a functioning FeLV genome, and the 5' and 3' long terminal repeat sequences are identical. Neither endogenous provirus is genetically fixed in cats but polymorphic, with 8.9 and 15.2% prevalence for enFeLV-AGTT and enFeLV-GGAG, respectively, among a survey of domestic cats. Neither provirus was found in the genomes of related species of the Felis genus, previously shown to harbor enFeLVs. The absence of mutational divergence, polymorphic incidence in cats, and absence in related species suggest that these enFeLVs may have entered the germ line more recently than previously believed, perhaps coincident with domestication, and reopens the question of whether some enFeLVs might be replication competent.", "journal": "Journal of virology", "doi": "10.1128/jvi.78.8.4370-4375.2004", "deposited_data": "Sim", "nuccore_ids": "38176357, 38176356", "bioproject_ids": null, "sra_ids": null}, {"year": 2005, "pmid": "15876545", "author": "Watanabe R", "n_authors": 3, "title": "Cell-binding properties of the envelope proteins of porcine endogenous retroviruses.", "abstract": "To examine the binding properties of the envelope glycoproteins of porcine endogenous retrovirus subgroups A and B (PERV-A and PERV-B), we produced two forms of soluble envelope proteins, termed Env-ST and Env-SU, using a baculovirus expression system. Env-ST and Env-SU encompass one-third of the N-terminal and the entire surface unit (SU) of the envelope protein, respectively. Using these proteins, binding assays were performed in various mammalian cell lines. The binding properties of the Env-STs that contain the putative receptor binding domain (RBD) did not correlate with the susceptibility to the pseudotype viruses having PERV envelopes, whereas those of the Env-SUs correlated fairly well. These results suggested that the Env-SUs but not Env-STs interacted with their receptors in various cell lines. Interestingly, PERV-A Env-SU did not bind to a mink cell line (Mv1-Lu cells) that is highly susceptible to the PERV-A pseudotype virus. In addition, PERV-B Env-SU did not interfere with the PERV-B pseudotype virus on Mv1-Lu cells. These results suggest the existence of a cognate receptor-independent entry pathway as demonstrated in an immunodeficiency-inducing variant of feline leukemia virus FeLV.", "journal": "Microbes and infection", "doi": "10.1016/j.micinf.2005.01.008", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2005, "pmid": "15837241", "author": "Langhammer S", "n_authors": 4, "title": "Neutralising antibodies against the transmembrane protein of feline leukaemia virus (FeLV).", "abstract": "Neutralising antibodies specific for feline leukaemia virus (FeLV) were induced by immunisation with recombinant FeLV transmembrane envelope protein p15E. Epitope mapping revealed two epitopes located in similar regions to those previously identified for the porcine endogenous retrovirus (PERV). One of the epitopes has partial homology and both are located in regions corresponding to epitopes recognised by neutralising antibodies in patients infected with HIV-1.", "journal": "Vaccine", "doi": "10.1016/j.vaccine.2005.01.091", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2005, "pmid": "15784142", "author": "Rasheed S", "n_authors": 4, "title": "Is Melanoma a stem cell tumor? Identification of neurogenic proteins in trans-differentiated cells.", "abstract": "BACKGROUND: Although several genes and proteins have been implicated in the development of melanomas, the molecular mechanisms involved in the development of these tumors are not well understood. To gain a better understanding of the relationship between the cell growth, tumorigenesis and differentiation, we have studied a highly malignant cat melanoma cell line that trans-differentiates into neuronal cells after exposure to a feline endogenous retrovirus RD114. METHODS: To define the repertoire of proteins responsible for the phenotypic differences between melanoma and its counterpart trans-differentiated neuronal cells we have applied proteomics technology and compared protein profiles of the two cell types and identified differentially expressed proteins by 2D-gel electrophoresis, image analyses and mass spectrometry. RESULTS: The melanoma and trans-differentiated neuronal cells could be distinguished by the presence of distinct sets of proteins in each. Although approximately 60-70% of the expressed proteins were shared between the two cell types, twelve proteins were induced de novo after infection of melanoma cells with RD114 virus in vitro. Expression of these proteins in trans-differentiated cells was significantly associated with concomitant down regulation of growth promoting proteins and up-regulation of neurogenic proteins (p = < 0.001). Based on their physiologic properties, >95% proteins expressed in trans-differentiated cells could be associated with the development, differentiation and regulation of nervous system cells. CONCLUSION: Our results indicate that the cat melanoma cells have the ability to differentiate into distinct neuronal cell types and they express proteins that are essential for self-renewal. Since melanocytes arise from the neural crest of the embryo, we conclude that this melanoma arose from embryonic precursor stem cells. This model system provides a unique opportunity to identify domains of interactions between the expressed proteins that halt the tumorigenic potential of melanoma cells and drive them toward neurogenerative pathways involved in early neurogenesis. A better understanding of these proteins in a well-coordinated signaling network would also help in developing novel approaches for suppression of highly malignant tumors that arise from stem-like embryonic cells.", "journal": "Journal of translational medicine", "doi": "10.1186/1479-5876-3-14", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2005, "pmid": "15767400", "author": "Roca AL", "n_authors": 5, "title": "Insertional polymorphisms of endogenous feline leukemia viruses.", "abstract": "The number, chromosomal distribution, and insertional polymorphisms of endogenous feline leukemia viruses (enFeLVs) were determined in four domestic cats (Burmese, Egyptian Mau, Persian, and nonbreed) using fluorescent in situ hybridization and radiation hybrid mapping. Twenty-nine distinct enFeLV loci were detected across 12 of the 18 autosomes. Each cat carried enFeLV at only 9 to 16 of the loci, and many loci were heterozygous for presence of the provirus. Thus, an average of 19 autosomal copies of enFeLV were present per cat diploid genome. Only five of the autosomal enFeLV sites were present in all four cats, and at only one autosomal locus, B4q15, was enFeLV present in both homologues of all four cats. A single enFeLV occurred in the X chromosome of the Burmese cat, while three to five enFeLV proviruses occurred in each Y chromosome. The X chromosome and nine autosomal enFeLV loci were telomeric, suggesting that ectopic recombination between nonhomologous subtelomeres may contribute to enFeLV distribution. Since endogenous FeLVs may affect the infectiousness or pathogenicity of exogenous FeLVs, genomic variation in enFeLVs represents a candidate for genetic influences on FeLV leukemogenesis in cats.", "journal": "Journal of virology", "doi": "10.1128/JVI.79.7.3979-3986.2005", "deposited_data": "Sim", "nuccore_ids": "38176360, 38176359, 38176358", "bioproject_ids": null, "sra_ids": null}, {"year": 2006, "pmid": "16730653", "author": "Shojima T", "n_authors": 3, "title": "Host cell range of T-lymphotropic feline leukemia virus in vitro.", "abstract": "We compared the host cell range of T-lymphotropic feline leukemia virus (FeLV-T) with that of FeLV subgroup B (FeLV-B) by pseudotype assay in the presence of FeLIX, a truncated envelope glycoprotein of endogenous FeLV. Although both viruses use Pit1 as a receptor and FeLIX does not hamper FeLV-B infection by receptor interference, the host ranges of FeLV-T and -B were not exactly the same, suggesting a different Pit1 usage at the post-binding level. A comparison of Pit1 sequences of various mammalian species indicated that extracellular loop 1 in a topology model deduced with the PHD PredictProtein algorism may be one of the regions responsible for efficient infection by FeLV-T.", "journal": "Biochemical and biophysical research communications", "doi": "10.1016/j.bbrc.2006.05.039", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2006, "pmid": "16423059", "author": "Langhammer S", "n_authors": 4, "title": "Antibodies neutralizing feline leukaemia virus (FeLV) in cats immunized with the transmembrane envelope protein p15E.", "abstract": "The feline leukaemia virus (FeLV) vaccines that are currently in wide use are generally poor inducers of virus-neutralizing antibodies, although such antibodies appear after recovering from challenge. However, the presence of neutralizing antibodies in cats recovering from natural FeLV infection clearly correlates with resistance to subsequent infection and passive transfer of antibodies can protect other animals. After demonstrating the induction of neutralizing antibodies in rats and goats immunized with the transmembrane envelope protein p15E of FeLV, cats were immunized with the same antigen. High titres of neutralizing antibodies specific for FeLV were induced and epitope mapping revealed a pattern of recognition similar to that seen following immunization of rats and goats. These epitopes are highly related to epitopes recognized after immunization with porcine endogenous retrovirus (PERV) p15E and to epitopes recognized by neutralizing antibodies in patients infected with human immunodeficiency virus type 1. The ability of p15E to induce neutralizing antibodies in cats suggests that it should be included in the next generation of vaccines. In contrast, sera from FeLV-infected animals usually fail to recognize the neutralization-relevant epitopes in p15E. Since homologous epitope sequences are present in feline endogenous retroviruses, it appears that tolerance against these sequences is not induced.", "journal": "Immunology", "doi": "10.1111/j.1365-2567.2005.02291.x", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2007, "pmid": "17329079", "author": "Tandon R", "n_authors": 7, "title": "Copy number polymorphism of endogenous feline leukemia virus-like sequences.", "abstract": "In the cat genome, endogenous feline leukemia virus (enFeLV) exists as multiple, nearly full-length proviral sequences. Even though no infectious virus is produced from enFeLV sequences, transcription and translation have been demonstrated in tissues of healthy cats and in feline cell lines. To test the hypothesis that the enFeLV loads play a role in exogenous FeLV-A infection and pathogenesis, we designed three real-time PCR assays to quantify U3 and env enFeLV loads (two within U3 amplifying different sequences; one within env). Applying these assays, we investigated the loads in blood samples derived from Swiss privately owned domestic cats, specific pathogen-free (SPF) cats and European wildcats (Felis silvestris silvestris). Significant differences in enFeLV loads were observed between privately owned cats and SPF cats as well as among SPF cats originating from different catteries and among domestic cats of different breeds. Within privately owned cats, FeLV-infected cats had higher loads than uninfected cats. In addition, higher enFeLV loads were found in wildcats compared to domestic cats. The assays described herein are important prerequisites to quantify enFeLV loads and thus to investigate the influence of enFeLV loads on the course of FeLV infection.", "journal": "Molecular and cellular probes", "doi": "10.1016/j.mcp.2007.01.003", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2007, "pmid": "17046042", "author": "Cheng HH", "n_authors": 3, "title": "Feline leukemia virus T entry is dependent on both expression levels and specific interactions between cofactor and receptor.", "abstract": "Feline leukemia virus (FeLV) subgroup T uses both a multiple membrane-spanning receptor, FePit1, and a soluble cofactor, FeLIX, to enter feline cells. FeLIX is expressed from endogenous FeLV-related sequence and resembles the receptor binding domain (RBD) of the viral envelope protein. It remains unclear whether FeLV-T receptor activity requires specific residues within FePit1 and FeLIX and/or a threshold level of receptor/cofactor expression. To address this, we examined FeLV-T infection of cells expressing variable levels of FePit1 and other gammaretroviral receptors in the presence of variable amounts of soluble cofactor, either RBD or the envelope surface subunit (SU). Cofactor-receptor pairs fall into three groups with regard to mediating FeLV-T infection: those that are efficient at all concentrations tested, such as FePit1 and FeLIX; those requiring high expression of both cofactor and receptor; and those that are non-functional as receptors even at high expression. This suggests that both expression levels and specific interactions with receptor and cofactor are critical for mediating entry of FeLV-T.", "journal": "Virology", "doi": "10.1016/j.virol.2006.09.004", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2007, "pmid": "16863698", "author": "Arjona A", "n_authors": 8, "title": "Evaluation of a novel nested PCR for the routine diagnosis of feline leukemia virus (FeLV) and feline immunodeficiency virus (FIV).", "abstract": "Laboratory diagnosis of feline leukemia virus (FeLV) and feline immunodeficiency virus (FIV) usually involves both viruses, as the clinical signs are similar and coinfection may occur. Serological methods may not represent an accurate diagnosis: maternal antibodies or cross-reactions may give false positive results to FIV, and false negative results may occur in latent FeLV status, or in certain FIV infection stages. A nested polymerase chain reaction (PCR) technique was designed to detect FeLV, FIV and feline endogenous retrovirus simultaneously. The detection of endogenous sequences was considered indicative of successful DNA extraction. The technique was used to diagnose FIV and FeLV in the blood cells of 179 cats. The kappa value with the serological data was 0.69 for FeLV and 0.87 for FIV. The joint detection of FeLV and FIV by this novel nested PCR is sensitive, specific, fast and convenient, and its applicability for clinical diagnosis is promising, as the direct evidence of the presence of the virus is more realistic than the indirect data provided by the serological detection.", "journal": "Journal of feline medicine and surgery", "doi": "10.1016/j.jfms.2006.05.009", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2008, "pmid": "18931078", "author": "Coelho FM", "n_authors": 9, "title": "Naturally occurring feline leukemia virus subgroup A and B infections in urban domestic cats.", "abstract": "A nested-PCR (n-PCR) was used to detect feline leukemia virus (FeLV) proviral DNA in blood samples from 464 sick and 608 healthy domestic cats (Felis catus) selected by convenience, and a significantly high prevalence of FeLV infection was observed. n-PCR results revealed the presence of FeLV proviral DNA in 47.2 % of sick cats and 47.4 % of healthy cats. Phylogenetic analysis revealed that FeLV samples from healthy or sick cats were grouped into separate clades. We determined FeLV subgroups by an n-PCR based on the envelope (env) gene. The partial env gene of FeLV Minas Gerais (MG) samples were compared to various exogenous FeLV isolates and endogenous (enFeLV) provirus from the same region. FeLV-B MG samples were more similar to endogenous sequences and to natural FeLV-B isolates than to either FeLV-A or FeLV-C. The results revealed the circulation of FeLV-B in large populations of urban domestic cats in Brazil.", "journal": "The Journal of general virology", "doi": "10.1099/vir.0.2008/003855-0", "deposited_data": "Sim", "nuccore_ids": "197359152, 197359150, 197359148, 197359146, 197359144, 197359142, 194294255, 194294253, 194294251, 194294250, 194294248, 194294246, 189491029, 167047999, 156254635, 156254633, 156254631, 156254629, 156254627, 156254625, 155604121, 155604120, 155604119, 155604118, 155604116, 154980999, 154980997, 154980995, 154980993, 154980991, 154980989, 154980987, 154980985, 154980983, 154980981, 154980979, 154980977, 154980975, 154980973, 154980971, 154980969, 154980967, 154980965, 154980963, 154980961, 154980959, 154980957, 154980955, 154980953, 113013728, 113013716, 53831047", "bioproject_ids": null, "sra_ids": null}, {"year": 2008, "pmid": "18715690", "author": "Flygare J", "n_authors": 4, "title": "Gene therapy of Diamond Blackfan anemia CD34(+) cells leads to improved erythroid development and engraftment following transplantation.", "abstract": "Diamond-Blackfan anemia (DBA) is a rare congenital hypoplastic anemia caused by mutations in ribosomal protein (RP) genes. Our aim is to develop gene therapy for DBA patients with mutations in RPS19. We previously demonstrated that RPS19 gene transfer partially corrects erythroid development in vitro. In this study, we asked if RPS19 gene transfer corrects erythroid development in unsorted cells transplanted to immunodeficient mice and if the RPS19-corrected fraction has a proliferative advantage after transplantation. We further determined if high level of RPS19 expression is required for correction. Mobilized peripheral blood CD34(+) cells were transduced by oncoretroviral vector particles pseudotyped with the feline endogenous retrovirus envelope. Vectors containing two different promoters with different RPS19 transgene expression levels were compared. Transduced cells were transplanted to immunocompromised nonobese diabetic/severe combined immunodeficient-beta2 microglobulin null mice in order to assess therapeutic effects of RPS19 gene transfer in vivo. We show that correction of erythroid development requires high RPS19 expression. The corrected fraction of unselected DBA cells have a survival advantage in vivo, suggesting that successful gene therapy may only require correction of a fraction of the patient cells. Our findings are fundamental for development of clinical gene therapy for DBA because they demonstrate increased engraftment of RPS19-transduced cells without selection of gene-corrected cells prior to transplantation, an essential prelude to studying long-term therapeutic effects in emerging animal models for DBA.", "journal": "Experimental hematology", "doi": "10.1016/j.exphem.2008.06.012", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2008, "pmid": "18695960", "author": "Cattori V", "n_authors": 2, "title": "Absolute quantitation of feline leukemia virus proviral DNA and viral RNA loads by TaqMan real-time PCR and RT-PCR.", "abstract": "Sensitive TaqMan real-time polymerase chain reaction (PCR)-based methods have been developed recently for the detection and quantitation of feline leukemia virus (FeLV) proviral DNA in infected cats. In this chapter, we outline the design and implementation of a TaqMan real-time PCR assay to quantify total FeLV proviral and viral RNA loads in infected cats. The assay is designed to amplify all three FeLV subtypes (A-C), but not FeLV-related endogenous retroviral sequences. The system is tested and optimized using proviral DNA or viral RNA from cells infected with reference strains. The sequence used to produce the standard DNA and RNA is amplified, subcloned into a vector, and sequenced. cRNA is synthesized from the linearized plasmid DNA. Standard DNA and RNA are quantified, diluted and used to determine efficiency, sensitivity, linear amplification range, and precision of the quantitative TaqMan real-time PCR assays.", "journal": "Methods in molecular biology (Clifton, N.J.)", "doi": "10.1007/978-1-60327-040-3_6", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2008, "pmid": "18629345", "author": "Yuhki N", "n_authors": 5, "title": "Sequences, annotation and single nucleotide polymorphism of the major histocompatibility complex in the domestic cat.", "abstract": "Two sequences of major histocompatibility complex (MHC) regions in the domestic cat, 2.976 and 0.362 Mbps, which were separated by an ancient chromosome break (55-80 MYA) and followed by a chromosomal inversion were annotated in detail. Gene annotation of this MHC was completed and identified 183 possible coding regions, 147 human homologues, possible functional genes and 36 pseudo/unidentified genes) by GENSCAN and BLASTN, BLASTP RepeatMasker programs. The first region spans 2.976 Mbp sequence, which encodes six classical class II antigens (three DRA and three DRB antigens) lacking the functional DP, DQ regions, nine antigen processing molecules (DOA/DOB, DMA/DMB, TAPASIN, and LMP2/LMP7,TAP1/TAP2), 52 class III genes, nineteen class I genes/gene fragments (FLAI-A to FLAI-S). Three class I genes (FLAI-H, I-K, I-E) may encode functional classical class I antigens based on deduced amino acid sequence and promoter structure. The second region spans 0.362 Mbp sequence encoding no class I genes and 18 cross-species conserved genes, excluding class I, II and their functionally related/associated genes, namely framework genes, including three olfactory receptor genes. One previously identified feline endogenous retrovirus, a baboon retrovirus derived sequence (ECE1) and two new endogenous retrovirus sequences, similar to brown bat endogenous retrovirus (FERVmlu1, FERVmlu2) were found within a 140 Kbp interval in the middle of class I region. MHC SNPs were examined based on comparisons of this BAC sequence and MHC homozygous 1.9x WGS sequences and found that 11,654 SNPs in 2.84 Mbp (0.00411 SNP per bp), which is 2.4 times higher rate than average heterozygous region in the WGS (0.0017 SNP per bp genome), and slightly higher than the SNP rate observed in human MHC (0.00337 SNP per bp).", "journal": "PloS one", "doi": "10.1371/journal.pone.0002674", "deposited_data": "Sim", "nuccore_ids": "193506889, 193506888", "bioproject_ids": null, "sra_ids": null}, {"year": 2008, "pmid": "18407367", "author": "Tandon R", "n_authors": 9, "title": "Association between endogenous feline leukemia virus loads and exogenous feline leukemia virus infection in domestic cats.", "abstract": "Recently, we demonstrated that endogenous feline leukemia virus (enFeLV) loads may vary among cats of different populations and that FeLV-infected cats have higher enFeLV loads than uninfected cats. Thus, we hypothesized that enFeLV might influence the pathogenesis and outcome of FeLV infection. No significant difference in the infection outcome (regressive versus progressive infection) was observed between groups of cats with high or low enFeLV loads following FeLV-A challenge. However, cats with high enFeLV loads showed higher viral replication (plasma viral RNA and p27 antigen levels) than cats with low enFeLV loads in the early phase of the infection. The enFeLV transcription level varied at different time points, but no clear-cut pattern was observed. In conclusion, our results demonstrated an association between enFeLV loads and FeLV replication but not outcome of infection. enFeLV should be considered as an important confounder in experimental FeLV infection or vaccination studies.", "journal": "Virus research", "doi": "10.1016/j.virusres.2008.02.016", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2008, "pmid": "18295344", "author": "Tandon R", "n_authors": 5, "title": "Quantification of endogenous and exogenous feline leukemia virus sequences by real-time PCR assays.", "abstract": "Endogenous retroviruses are integrated in the genome of most vertebrates. They represent footprints of ancient retroviral infection and are vertically transmitted from parents to their offspring. In the genome of all domestic cats, sequences closely related to exogenous FeLV known as endogenous feline leukemia virus (enFeLV), are present. enFeLV are incapable of giving rise to infectious virus particles. However, transcription and translation of enFeLV have been demonstrated in tissues of healthy cats and in feline cell lines. The presence of enFeLV-env has been shown in specific embryonic tissues and adult thymic cells. In addition, the enFeLV-env region recombines with FeLV subgroup A giving rise to an infectious FeLV-B virus. enFeLV envelope protein, FeLIX (FeLV infectivity X-essory protein) is also involved in mediating FeLV-T infection. In order to test the hypothesis that the enFeLV loads play a role in exogenous FeLV-A infection and pathogenesis, quantitative real-time PCR and RT-PCR assays were developed. An assay, specific to U3 region of all different subtypes of exogenous FeLV, was designed and applied to quantify exogenous FeLV proviral or viral load in cats, while three real-time PCR assays were designed to quantify U3 and env enFeLV loads (two within U3 amplifying different sequences; one within env). enFeLV loads were investigated in blood samples derived from Swiss privately owned domestic cats, specific pathogen-free (SPF) cats and European wildcats (Felis silvestris silvestris). Significant differences in enFeLV loads were observed between privately owned cats and SPF cats as well as among SPF cats originating from different catteries and among domestic cats of different breeds. When privately owned cats were compared, FeLV-infected cats had higher loads than uninfected cats. In addition, wildcats had higher enFeLV loads than domestic cats. In conclusion, the quantitative real-time PCR assays described herein are important prerequisites to quantify enFeLV proviral loads in felids and thus are important tools to investigate the role of enFeLV loads in FeLV infection.", "journal": "Veterinary immunology and immunopathology", "doi": "10.1016/j.vetimm.2008.01.027", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2008, "pmid": "18258118", "author": "Brown MA", "n_authors": 6, "title": "Genetic characterization of feline leukemia virus from Florida panthers.", "abstract": "From 2002 through 2005, an outbreak of feline leukemia virus (FeLV) occurred in Florida panthers (Puma concolor coryi). Clinical signs included lymphadenopathy, anemia, septicemia, and weight loss; 5 panthers died. Not associated with FeLV outcome were the genetic heritage of the panthers (pure Florida vs. Texas/Florida crosses) and co-infection with feline immunodeficiency virus. Genetic analysis of panther FeLV, designated FeLV-Pco, determined that the outbreak likely came from 1 cross-species transmission from a domestic cat. The FeLV-Pco virus was closely related to the domestic cat exogenous FeLV-A subgroup in lacking recombinant segments derived from endogenous FeLV. FeLV-Pco sequences were most similar to the well-characterized FeLV-945 strain, which is highly virulent and strongly pathogenic in domestic cats because of unique long terminal repeat and envelope sequences. These unique features may also account for the severity of the outbreak after cross-species transmission to the panther.", "journal": "Emerging infectious diseases", "doi": "10.3201/eid1402.070981", "deposited_data": "Sim", "nuccore_ids": "158523425, 158523424, 158523423, 158523422, 158523420, 158523418, 158523416, 158523414, 158523412, 158523410", "bioproject_ids": null, "sra_ids": null}, {"year": 2009, "pmid": "20218331", "author": "Miyazawa T", "n_authors": 1, "title": "[Receptors for animal retroviruses].", "abstract": "Diseases caused by animal retroviruses have been recognized since 19th century in veterinary field. Most livestock and companion animals have own retroviruses. To disclose the receptors for these retroviruses will be useful for understanding retroviral pathogenesis, developments of anti-retroviral drugs and vectors for human and animal gene therapies. Of retroviruses in veterinary field, receptors for the following viruses have been identified; equine infectious anemia virus, feline immunodeficiency virus, feline leukemia virus subgroups A, B, C, and T, Jaagsiekte sheep retrovirus, enzootic nasal tumor virus, avian leukosis virus subgroups A, B, C, D, E, and J, reticuloendotheliosis virus, RD-114 virus (a feline endogenous retrovirus), and porcine endogenous retrovirus subgroup A. Primate lentiviruses require two molecules (CD4 and chemokine receptors such as CXCR4) as receptors. Likewise, feline immunodeficiency virus also requires two molecules, i.e., CD134 (an activation marker of CD4 T cells) and CXCR4 in infection. Gammaretroviruses utilize multi-spanning transmembrane proteins, most of which are transporters of amino acids, vitamins and inorganic ions. Betaretroviruses and alpharetroviruses utilize transmembrane and/or GPI-anchored proteins as receptors. In this review, I overviewed receptors for animal retroviruses in veterinary field.", "journal": "Uirusu", "doi": "10.2222/jsv.59.223", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2009, "pmid": "19270739", "author": "Meli ML", "n_authors": 15, "title": "Feline leukemia virus and other pathogens as important threats to the survival of the critically endangered Iberian lynx (Lynx pardinus).", "abstract": "The Iberian lynx (Lynx pardinus) is considered the most endangered felid species in the world. In order to save this species, the Spanish authorities implemented a captive breeding program recruiting lynxes from the wild. In this context, a retrospective survey on prevalence of selected feline pathogens in free-ranging lynxes was initiated. We systematically analyzed the prevalence and importance of seven viral, one protozoan (Cytauxzoon felis), and several bacterial (e.g., hemotropic mycoplasma) infections in 77 of approximately 200 remaining free-ranging Iberian lynxes of the Doñana and Sierra Morena areas, in Southern Spain, between 2003 and 2007. With the exception of feline immunodeficiency virus (FIV), evidence of infection by all tested feline pathogens was found in Iberian lynxes. Fourteen lynxes were feline leukemia virus (FeLV) provirus-positive; eleven of these were antigenemic (FeLV p27 positive). All 14 animals tested negative for other viral infections. During a six-month period in 2007, six of the provirus-positive antigenemic lynxes died. Infection with FeLV but not with other infectious agents was associated with mortality (p<0.001). Sequencing of the FeLV surface glycoprotein gene revealed a common origin for ten of the eleven samples. The ten sequences were closely related to FeLV-A/61E, originally isolated from cats in the USA. Endogenous FeLV sequences were not detected. It was concluded that the FeLV infection most likely originated from domestic cats invading the lynx's habitats. Data available regarding the time frame, co-infections, and outcome of FeLV-infections suggest that, in contrast to the domestic cat, the FeLV strain affecting the lynxes in 2007 is highly virulent to this species. Our data argue strongly for vaccination of lynxes and domestic cats in and around lynx's habitats in order to prevent further spread of the virus as well as reduction the domestic cat population if the lynx population is to be maintained.", "journal": "PloS one", "doi": "10.1371/journal.pone.0004744", "deposited_data": "Sim", "nuccore_ids": "167650792, 167650790, 167650788, 167650786, 167650784, 167650782, 167650780, 167650778, 167650776, 167650774, 167650772, 167650770, 167650768, 167650766, 167650764, 167650762, 167650760, 167650758, 167650756, 167650754", "bioproject_ids": null, "sra_ids": null}, {"year": 2010, "pmid": "20817587", "author": "Powell CC", "n_authors": 4, "title": "Bartonella species, feline herpesvirus-1, and Toxoplasma gondii PCR assay results from blood and aqueous humor samples from 104 cats with naturally occurring endogenous uveitis.", "abstract": "Toxoplasma gondii, Bartonella henselae and feline herpesvirus-1 (FHV-1) have been implicated as causative agents in feline uveitis. The usefulness of serum and aqueous humor (AH) antibody testing for these agents is limited as antibodies can be detected in both healthy cats and cats with uveitis. Very few studies using polymerase chain reaction (PCR) assays to amplify organism DNA from samples from cats with uveitis have been performed. In this study, assays to detect T gondii antibodies, feline leukemia virus antigen, feline immunodeficiency virus antibody, and Bartonella species antibodies were performed on serum and PCR assays for amplification of T gondii, Bartonella species, and FHV-1 DNA were performed on blood and AH samples from 104 cats with endogenous uveitis and 19 healthy cats. Results suggest the addition of the PCR assay to the diagnostic work-up for cats with uveitis will increase the detection of T gondii and FHV-1; however, the diagnostic usefulness of these additional data is not clear.", "journal": "Journal of feline medicine and surgery", "doi": "10.1016/j.jfms.2010.07.003", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2010, "pmid": "20615520", "author": "Polani S", "n_authors": 5, "title": "Evolutionary dynamics of endogenous feline leukemia virus proliferation among species of the domestic cat lineage.", "abstract": "Endogenous feline leukemia viruses (enFeLVs) occur in the germ lines of the domestic cat and related wild species (genus Felis). We sequenced the long terminal repeats and part of the env region of enFeLVs in domestic cats and five wild species. A total of 305 enFeLV sequences were generated across 17 individuals, demonstrating considerable diversity within two major clades. Distinct proliferations of enFeLVs occurred before and after the black-footed cat diverged from the other species. Diversity of enFeLVs was limited for the sand cat and jungle cat suggesting that proliferation of enFeLVs occurred within these species after they diverged. Relationships among enFeLVs were congruent with host species relationships except for the jungle cat, which carried only enFeLVs from a lineage that recently invaded the germline (enFeLV-AGTT). Comparison of wildcat and domestic cat enFeLVs indicated that a distinctive germ line invasion of enFeLVs has not occurred since the cat was domesticated.", "journal": "Virology", "doi": "10.1016/j.virol.2010.06.010", "deposited_data": "Sim", "nuccore_ids": "304360592, 304360591, 304360590, 304360589, 304360588, 304360587, 304360586, 304360585, 304360584, 304360583, 304360582, 304360581, 304360580, 304360579, 304360578, 304360577, 304360576, 304360575, 304360574, 304360573, 304360572, 304360571, 304360570, 304360569, 304360568, 304360567, 304360566, 304360565, 304360564, 304360563, 304360562, 304360561, 304360560, 304360559, 304360558, 304360557, 304360556, 304360555, 304360554, 304360553, 304360552, 304360551, 304360550, 304360549, 304360548, 304360547, 304360546, 304360545, 304360544, 304360543, 304360542, 304360541, 304360540, 304360539, 304360538, 304360537, 304360536, 304360535, 304360534, 304360533, 304360532, 304360531, 304360530, 304360529, 304360528, 304360527, 304360526, 304360525, 304360524, 304360523, 304360522, 304360521, 304360520, 304360519, 304360518, 304360517, 304360516, 304360515, 304360514, 304360513, 304360512, 304360511, 304360510, 304360509, 304360508, 304360507, 304360506, 304360505, 304360504, 304360503, 304360502, 304360501, 304360500, 304360499, 304360498, 304360497, 304360496, 304360495, 304360494, 304360493, 304360492, 304360491, 304360490, 304360489, 304360488, 304360487, 304360486, 304360485, 304360484, 304360483, 304360482, 304360481, 304360480, 304360479, 304360478, 304360477, 304360476, 304360475, 304360474, 304360473, 304360472, 304360471, 304360470, 304360469, 304360468, 304360467, 304360466, 304360465, 304360464, 304360463, 304360462, 304360461, 304360460, 304360459, 304360458, 304360457, 304360456, 304360455, 304360454, 304360453, 304360452, 304360451, 304360450, 304360449, 304360448, 304360447, 304360446, 304360445, 304360444, 304360443, 304360442, 304360441, 304360440, 304360439, 304360438, 304360437, 304360436, 304360435, 304360434, 304360433, 304360432, 304360431, 304360430, 304360429, 304360428, 304360427, 304360426, 304360425, 304360424, 304360423, 304360422, 304360421, 304360420, 304360419, 304360418, 304360417, 304360416, 304360415, 304360414, 304360413, 304360412, 304360411, 304360410, 304360409, 304360408, 304360407, 304360406, 304360405, 304360404, 304360403, 304360402, 304360401, 304360400, 304360399, 304360398, 304360397, 304360396, 304360395, 304360394, 304360393, 304360392, 304360391, 304360390, 304360389, 304360388, 304360387, 304360386, 304360385, 304360384, 304360383, 304360382, 304360381, 304360380, 304360379, 304360378, 304360377, 304360376, 304360375, 304360374, 304360373, 304360372, 304360371, 304360370, 304360369, 304360368, 304360367, 304360366, 304360365, 304360364, 304360363, 304360362, 304360361, 304360360, 304360359, 304360358, 304360357, 304360356, 304360355, 304360354, 304360353, 304360352, 304360351, 304360350, 304360349, 304360348, 304360347, 304360346, 304360345, 304360344, 304360343, 304360342, 304360341, 304360340, 304360339, 304360338, 304360337, 304360336, 304360335, 304360334, 304360333, 304360332, 304360331, 304360330", "bioproject_ids": null, "sra_ids": null}, {"year": 2010, "pmid": "20451235", "author": "Ahmad S", "n_authors": 2, "title": "The frequency of occurrence and nature of recombinant feline leukemia viruses in the induction of multicentric lymphoma by infection of the domestic cat with FeLV-945.", "abstract": "During feline leukemia virus (FeLV) infection in the domestic cat, viruses with a novel envelope gene arise by recombination between endogenous FeLV-related elements and the exogenous infecting species. These recombinant viruses (FeLV-B) are of uncertain disease association, but have been linked to the induction of thymic lymphoma. To assess the role of FeLV-B in the induction of multicentric lymphoma and other non-T-cell disease, the frequency of occurrence and nature of FeLV-B were examined in diseased tissues from a large collection of FeLV-infected animals. Diseased tissues were examined by Southern blot and PCR amplification to detect the presence of FeLV-B. Further analysis was performed to establish the recombination junctions and infectivity of FeLV-B in diseased tissues. The results confirmed the frequent association of FeLV-B with thymic lymphoma but showed infrequent generation, low levels and lack of infectivity of FeLV-B in non-T-cell diseases including multicentric lymphoma.", "journal": "Virology", "doi": "10.1016/j.virol.2010.04.011", "deposited_data": "Sim", "nuccore_ids": "289976733, 289976730, 289976727, 289976724, 289976722, 289976719, 289976716, 289976712, 289976708, 289976706, 289976703", "bioproject_ids": null, "sra_ids": null}, {"year": 2010, "pmid": "20372106", "author": "Kim YS", "n_authors": 7, "title": "Transduction of human primitive repopulating hematopoietic cells with lentiviral vectors pseudotyped with various envelope proteins.", "abstract": "Lentiviral vectors are useful for transducing primitive hematopoietic cells. We examined four envelope proteins for their ability to mediate lentiviral transduction of mobilized human CD34(+) peripheral blood cells. Lentiviral particles encoding green fluorescent protein (GFP) were pseudotyped with the vesicular stomatitis virus envelope glycoprotein (VSV-G), the amphotropic (AMPHO) murine leukemia virus envelope protein, the endogenous feline leukemia viral envelope protein or the feline leukemia virus type C envelope protein. Because the relative amount of genome RNA per ml was similar for each pseudotype, we transduced CD34(+) cells with a fixed volume of each vector preparation. Following an overnight transduction, CD34(+) cells were transplanted into immunodeficient mice which were sacrificed 12 weeks later. The average percentages of engrafted human CD45(+) cells in total bone marrow were comparable to that of the control, mock-transduced group (37-45%). Lenti-particles pseudotyped with the VSV-G envelope protein transduced engrafting cells two- to tenfold better than particles pseudotyped with any of the gamma-retroviral envelope proteins. There was no correlation between receptor mRNA levels for the gamma-retroviral vectors and transduction efficiency of primitive hematopoietic cells. These results support the use of the VSV-G envelope protein for the development of lentiviral producer cell lines for manufacture of clinical-grade vector.", "journal": "Molecular therapy : the journal of the American Society of Gene Therapy", "doi": "10.1038/mt.2010.48", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2010, "pmid": "19997089", "author": "Trobridge GD", "n_authors": 8, "title": "Cocal-pseudotyped lentiviral vectors resist inactivation by human serum and efficiently transduce primate hematopoietic repopulating cells.", "abstract": "Lentiviral vectors are established as efficient and convenient vehicles for gene transfer. They are almost always pseudotyped with the envelope glycoprotein of vesicular stomatitis virus (VSV-G) due to the high titers that can be achieved, their stability, and broad tropism. We generated a novel cocal vesiculovirus envelope glycoprotein plasmid and compared the properties of lentiviral vectors pseudotyped with cocal, VSV-G, and a modified feline endogenous retrovirus envelope glycoprotein (RD114/TR). Cocal-pseudotyped lentiviral vectors can be produced at titers as high as with VSV-G, have a broad tropism, and are stable, allowing for efficient concentration by centrifugation. Additionally, cocal vectors are more resistant to inactivation by human serum than VSV-G-pseudotyped vectors, and efficiently transduce human CD34(+) nonobese diabetic/severe combined immunodeficient (NOD/SCID) mouse-repopulating cells (SRCs), and long-term primate hematopoietic repopulating cells. These studies establish the potential of cocal-pseudotyped lentiviral vectors for a variety of scientific and therapeutic gene transfer applications, including in vivo gene delivery and hematopoietic stem cell (HSC) gene therapy.", "journal": "Molecular therapy : the journal of the American Society of Gene Therapy", "doi": "10.1038/mt.2009.282", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2010, "pmid": "19915325", "author": "Nakaya Y", "n_authors": 4, "title": "Focus assay on FeLIX-dependent feline leukemia virus.", "abstract": "T-lymphotropic feline leukemia virus (FeLV-T) induces immunodeficiency in cats. FeLV-T is fusion-defective and requires a cofactor, termed FeLIX, for infection. FeLIX is a truncated envelope glycoprotein of an endogenous FeLV and mediates infection by binding a phosphate transporter Pit-1. In this study, we established a feline sarcoma-positive leukemia-negative cell line expressing FeLIX, named QN/FeLIX cells. Upon infection, FeLV-T induced prominent foci with syncytia in QN/FeLIX cells and could be titrated by the focus assay. In addition, we established a FeLIX-expressing feline fibroblast cell line, named AH/FeLIX cells. FeLV-T productively infected AH/FeLIX cells and induced severe CPE with syncytia. QN/FeLIX and AH/FeLIX cells will be useful for the study of FeLIX-dependent mutants in FeLV-infected cats.", "journal": "The Journal of veterinary medical science", "doi": "10.1292/jvms.09-0194", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2011, "pmid": "22168342", "author": "Fukuma A", "n_authors": 7, "title": "Viral and cellular requirements for the budding of feline endogenous retrovirus RD-114.", "abstract": "RD-114 virus is a feline endogenous retrovirus and produced as infectious viruses in some feline cell lines. Recently, we reported the contamination of an infectious RD-114 virus in a proportion of live attenuated vaccines for dogs and cats. It is very difficult to completely knock out the RD-114 proviruses from cells, as endogenous retroviruses are usually integrated multiply into the host genome. However, it may be possible to reduce the risk of contamination of RD-114 virus by regulating the viral release from cells. In this study, to understand the molecular mechanism of RD-114 virus budding, we attempted to identify the viral and cellular requirements for RD-114 virus budding. Analyses of RD-114 L-domain mutants showed that the PPPY sequence in the pp15 region of Gag plays a critical role in RD-114 virus release as viral L-domain. Furthermore, we investigated the cellular factors required for RD-114 virus budding. We demonstrated that RD-114 virus release was inhibited by overexpression of dominant negative mutants of Vps4A, Vps4B, and WWP2. These results strongly suggest that RD-114 budding utilizes the cellular multivesicular body sorting pathway similar to many other retroviruses.", "journal": "Virology journal", "doi": "10.1186/1743-422X-8-540", "deposited_data": "Sim", "nuccore_ids": "2462547180, 2462547178, 2462547176, 2462547174, 2462547172, 2462547170, 2462547168, 2462547166, 2462547164, 2462547162, 2462547160, 2217304381, 2217304380, 2217304379, 2217304377, 2217304376, 2217304374, 2217304372, 2217304370, 2217304369, 2217304368, 2217304367, 1890333865, 1677556751, 1677500547, 1677499753, 1677498624", "bioproject_ids": null, "sra_ids": null}, {"year": 2011, "pmid": "21900723", "author": "Boenzli E", "n_authors": 10, "title": "In vitro inhibition of feline leukaemia virus infection by synthetic peptides derived from the transmembrane domain.", "abstract": "The feline leukaemia virus (FeLV) is a gammaretrovirus commonly affecting cats. Infection with this virus often leads to fatal outcomes and, so far, no cure is available for this disease. Synthetic peptides with structures mimicking the transmembrane protein of the viral surface proteins hold the potential to effectively interfere with viral entry by hampering the fusion of viral and host cell membranes and constitute a novel approach for the treatment of infections with retroviruses. We identified and synthetically produced 11 FeLV peptides and evaluated their potential to block FeLV infection in vitro. Cell cultures were exposed to FeLV subgroup A prior to the addition of the peptides. The inhibitory effect of the peptides was assessed by measuring FeLV gag protein in the supernatant of peptide versus mock-treated cell cultures using an ELISA. A peptide (EPK364) of 37 amino acids in length, with sequence homology to the HIV fusion inhibitor T-20, significantly suppressed viral replication by 88%, whereas no effects were found for shorter peptides. Two structurally modified variants of EPK364 also inhibited viral replication by up to 58% (EPK397) and 27% (EPK398). Our data support the identification of synthetic FeLV peptides that have the potential for a curative short-term therapy of viraemic cats. In addition, these peptides might become an important tool in xenotransplantation, where endogenous gammaretroviruses of the donor species might be able to infect the host.", "journal": "Antiviral therapy", "doi": "10.3851/IMP1850", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2011, "pmid": "21715022", "author": "Stewart H", "n_authors": 4, "title": "Are endogenous feline leukemia viruses really endogenous?", "abstract": "Full length endogenous feline leukemia virus (FeLV) proviruses exist within the genomes of many breeds of domestic cat raising the possibility that they may also exist in a transmissible exogenous form. Such viruses would share receptor usage with the recombinant FeLV-B subgroup, a viral subgroup that arises in vivo by recombination between exogenous subgroup A virus (FeLV-A) and endogenous FeLV. Accordingly, all isolates of FeLV-B made to date have contained a \"helper\" FeLV-A, consistent with their recombinatorial origin. In order to assess whether endogenous viruses are transmitted between cats, we examined primary isolates of FeLV for which the viral subgroup had been determined for the presence of a subgroup B virus that lacked an FeLV-A. Here we describe the identification of two primary field isolates of FeLV (2518 and 4314) that appeared to contain subgroup B virus only by classical interference assays, raising the possibility of between-host transmission of endogenous FeLV. Sequencing of the env gene and U3 region of the 3' long terminal repeat (LTR) confirmed that both viral genomes contained endogenous viral env genes. However the viral 3' LTRs appeared exogenous in origin with a putative 3' recombination breakpoint residing at the 3' end of the env gene. Further, the FeLV-2518 virions also co-packaged a truncated FeLV-A genome containing a defective env gene, termed FeLV-2518(A) whilst no helper subgroup A viral genome was detected in virions of FeLV-4314. The acquisition of an exogenous LTR by the endogenous FeLV in 4314 may have allowed a recombinant FeLV variant to outgrow an exogenous FeLV-A virus that was presumably present during first infection. Given time, a similar evolution may also occur within the 2518 isolate. The data suggest that endogenous FeLVs may be mobilised by acquisition of exogenous LTRs yielding novel viruses that type biologically as FeLV-B.", "journal": "Veterinary immunology and immunopathology", "doi": "10.1016/j.vetimm.2011.06.011", "deposited_data": "Sim", "nuccore_ids": "407809837, 407809834, 339461609", "bioproject_ids": null, "sra_ids": null}, {"year": 2011, "pmid": "21479233", "author": "Fukuma A", "n_authors": 5, "title": "Cloning and characterization of the antiviral activity of feline Tetherin/BST-2.", "abstract": "Human Tetherin/BST-2 has recently been identified as a cellular antiviral factor that blocks the release of various enveloped viruses. In this study, we cloned a cDNA fragment encoding a feline homolog of Tetherin/BST-2 and characterized the protein product. The degree of amino acid sequence identity between human Tetherin/BST-2 and the feline homolog was 44.4%. Similar to human Tetherin/BST-2, the expression of feline Tetherin/BST-2 mRNA was inducible by type I interferon (IFN). Exogenous expression of feline Tetherin/BST-2 efficiently inhibited the release of feline endogenous retrovirus RD-114. The extracellular domain of feline Tetherin/BST-2 has two putative N-linked glycosylation sites, N79 and N119. Complete loss of N-linked glycosylation by introduction of mutations into both sites resulted in almost complete abolition of its antiviral activity. In addition, feline Tetherin/BST-2 was insensitive to antagonism by HIV-1 Vpu, although the antiviral activity of human Tetherin/BST-2 was antagonized by HIV-1 Vpu. Our data suggest that feline Tetherin/BST-2 functions as a part of IFN-induced innate immunity against virus infection and that the induction of feline Tetherin/BST-2 in vivo may be effective as a novel antiviral strategy for viral infection.", "journal": "PloS one", "doi": "10.1371/journal.pone.0018247", "deposited_data": "Sim", "nuccore_ids": "340545528, 327343214, 340545528", "bioproject_ids": null, "sra_ids": null}, {"year": 2011, "pmid": "21345697", "author": "Narushima R", "n_authors": 3, "title": "Development of a real-time reverse-transcription-PCR method for detection of RD114 virus in canine vaccines.", "abstract": "It is known that certain feline cell lines, such as the Crandell-Rees feline kidney cell, produce an RD-114-like virus. As a feline endogenous retrovirus, RD114 virus, exists in the genome of all cats, it can be assumed that contamination with the virus in feline and canine live vaccines manufactured by culturing cells of feline origin occurs. To detect an infectious RD114 virus in vitro, a LacZ marker rescue assay has recently been established. In feline and canine live vaccines approved in Japan, feline cell lines are widely used to produce vaccines, especially those containing canine parvovirus components. The LacZ marker rescue assay detects infectious viral particles, but the real-time reverse-transcription-PCR detects both infectious and defective viruses. The canine live vaccines manufactured in cells of feline origin showed positive results for the env gene by the real-time reverse-transcription-PCR, including all of the 8 vaccines produced in feline cell lines that were negative in the LacZ marker rescue assay. In conclusion, the present investigation suggests that the newly developed method has the advantages of shorter time requirements and can be applied as a valuable screening method to detect RD114 viral RNA in vaccines.", "journal": "Biologicals : journal of the International Association of Biological Standardization", "doi": "10.1016/j.biologicals.2011.01.004", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2011, "pmid": "21269522", "author": "Narushima R", "n_authors": 6, "title": "Experimental infection of dogs with a feline endogenous retrovirus RD-114.", "abstract": "The feline endogenous retrovirus RD114 is contained in the genome of cats. The virus may contaminate live canine vaccines based on cultured feline cells. The in vivo infectivity, acute and subacute pathogenicity, and viral proliferation of the RD114 virus were evaluated by experimental infection of dogs. Nine specific pathogen free dogs were divided into three groups, with each group consisting of one female and two male dogs. Dogs were subcutaneously inoculated in the neck with either 1 ml RD114 stock virus (group A), inactivated RD114 virus suspension (group B), or cell culture medium (group C) as a negative control. To assess blood cell counts and biochemical properties, blood samples from each group were collected 5 days before inoculation, just prior to inoculation, and 1, 3, 7 and 10 days post-inoculation. During the experimental period of 51 days, none of the dogs inoculated with RD114 virus showed any clinical signs, significant increases in rectal temperature or abnormal blood biochemical characteristics including C-reactive protein when compared with the negative controls. We were not able to re-isolate the RD114 virus from buffy coat cells of group A dogs. Additionally, we could not detect RD114 provirus in the genomic DNA isolated from peripheral blood leukocytes, lymph node, spleen and sternal bone marrow cells. Signs of RD114 virus proliferation were not found after subcutaneous infection of dogs. Although the potential risk caused by infection with RD114 virus in dogs could not be assessed in this study, we suspect that RD114 virus has little or no virulence in dogs.", "journal": "Acta veterinaria Scandinavica", "doi": "10.1186/1751-0147-53-3", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2011, "pmid": "21029758", "author": "Okada M", "n_authors": 5, "title": "Susceptibility and production of a feline endogenous retrovirus (RD-114 virus) in various feline cell lines.", "abstract": "RD-114 virus is a replication-competent feline endogenous retrovirus that has been classified as a xenotropic virus. In this study, we examined the expression of the receptors for RD-114 virus in feline cell lines by conducting a pseudotype virus infection assay. Six out of eight feline cell lines were susceptible to the RD-114 pseudotype virus and two cell lines (MCC and FER cells) were resistant. The two resistant cell lines and one cell line (CRFK cells) weakly sensitive to the RD-114 pseudotype virus were found to produce replication-competent RD114-like viruses by the LacZ marker rescue assay and the interference assay. These data strongly suggest that RD-114 virus is polytropic and resistance to RD-114 virus in certain cell lines is due to receptor interference but not polymorphism of the RD-114 receptors. In addition, we determined the amino acid sequences of the envelope region of RD-114-like viruses produced from MCC, FER and CRFK cells. The sequences were identical with the authentic RD-114 virus. Because many feline cell lines are used to manufacture live attenuated vaccines for companion animals, attention should be paid to contamination of the RD-114 virus in vaccines.", "journal": "Virus research", "doi": "10.1016/j.virusres.2010.10.020", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2011, "pmid": "20829603", "author": "Langhammer S", "n_authors": 4, "title": "Increased neutralizing antibody response after simultaneous immunization with leucogen and the feline leukemia virus transmembrane protein.", "abstract": "To develop improved vaccination strategies against feline leukemia virus (FeLV), rats were immunized with the transmembrane envelope protein p15E of FeLV alone or in combination with the commercial vaccine Leucogen® comprising the nonglycosylated FeLV surface envelope protein. Binding and neutralizing antibodies were induced in both groups and in the group immunized with Leucogen alone. Higher titers of antibodies neutralizing FeLV were induced by simultaneous immunization with Leucogen and p15E compared to the responses using Leucogen or p15E alone, suggesting that combination vaccines should be used in the future. Epitope mapping of p15E-specific antibodies induced by simultaneous immunization with Leucogen and p15E revealed the same pattern of response as obtained after immunization with p15E alone: one epitope was localized in the membrane-proximal external region (MPER) and the other in the fusion peptide-proximal region, and they are related to the epitopes detected after immunization with p15E of the porcine endogenous retrovirus and the koala retrovirus. The data indicate that these epitopes in the MPER are an effective target for neutralization and that antigens containing them may therefore prove to be a useful component of vaccines against retroviruses, including HIV-1.", "journal": "Intervirology", "doi": "10.1159/000318892", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2012, "pmid": "23041594", "author": "Narushima R", "n_authors": 4, "title": "Detection of RD-114 virus by a reverse transcriptase assay based on product enhancement.", "abstract": "RD-114 virus is a feline endogenous retrovirus that exists in the genome of all cats. It can be assumed that feline and canine live vaccines manufactured by culturing cells of feline origin are contaminated with the virus. The current study is attempted to develop a product enhanced reverse transcriptase (PERT) assay to detect replication-competent RD-114 virus. Since culture supernatants of Crandell-Rees feline kidney (CRFK) cells do not have detectable reverse transcriptase activity in case of do not passage on other cell lines, these results raise the possibility that RD-114 virus grow efficiently in other retrovirus producing cell lines. For the PERT assay, RD-114 virus isolated from CRFK cells may need to be passaged more than four times on 293T cells to be expressed at appreciable levels. The PERT assay described here provides an accurate method for determining the presence of RD-114 in culture supernatants and will help monitor live vaccines produced in endogenous virus producing cell lines.", "journal": "Biologicals : journal of the International Association of Biological Standardization", "doi": "10.1016/j.biologicals.2012.09.002", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2012, "pmid": "22674983", "author": "Anai Y", "n_authors": 7, "title": "Infectious endogenous retroviruses in cats and emergence of recombinant viruses.", "abstract": "Endogenous retroviruses (ERVs) comprise a significant percentage of the mammalian genome, and it is poorly understood whether they will remain as inactive genomes or emerge as infectious retroviruses. Although several types of ERVs are present in domestic cats, infectious ERVs have not been demonstrated. Here, we report a previously uncharacterized class of endogenous gammaretroviruses, termed ERV-DCs, that is present and hereditary in the domestic cat genome. We have characterized a subset of ERV-DC proviral clones, which are numbered according to their genomic insertions. One of these, ERV-DC10, located in the q12-q21 region on chromosome C1, is an infectious gammaretrovirus capable of infecting a broad range of cells, including human. Our studies indicate that ERV-DC10 entered the genome of domestic cats in the recent past and appeared to translocate to or reintegrate at a distinct locus as infectious ERV-DC18. Insertional polymorphism analysis revealed that 92 of 244 domestic cats had ERV-DC10 on a homozygous or heterozygous locus. ERV-DC-like sequences were found in primate and rodent genomes, suggesting that these ERVs, and recombinant viruses such as RD-114 and BaEV, originated from an ancestor of ERV-DC. We also found that a novel recombinant virus, feline leukemia virus subgroup D (FeLV-D), was generated by ERV-DC env transduction into feline leukemia virus in domestic cats. Our results indicate that ERV-DCs behave as donors and/or acceptors in the generation of infectious, recombinant viruses. The presence of such infectious endogenous retroviruses, which could be harmful or beneficial to the host, may affect veterinary medicine and public health.", "journal": "Journal of virology", "doi": "10.1128/JVI.00280-12", "deposited_data": "Sim", "nuccore_ids": "396077194, 396077193, 396077192, 396077191, 396077190, 396077189, 396077188, 396077186, 396077185, 396077183, 396077181, 396077179, 396077176, 396077174, 396077171, 396077168, 396077165, 396077164, 396077162, 396077161, 396077160, 396077158, 396077156, 396077154, 396077152, 396077150, 396077148, 396077146", "bioproject_ids": null, "sra_ids": null}, {"year": 2012, "pmid": "22639102", "author": "Shimode S", "n_authors": 7, "title": "Sequence comparison of three infectious molecular clones of RD-114 virus.", "abstract": "RD-114 virus is a replication-competent feline endogenous retrovirus. RD-114 virus contaminates several feline and canine live attenuated vaccines and the issue of contamination of RD-114 virus in vaccines should be solved. To date, three infectious molecular clones (pSc3c, pCRT1, and pRD-UCL) have been reported. In this study, we sequenced the entire nucleotide sequence of pRD-UCL and compared the nucleotide sequences of the three infectious molecular clones. As a result, these three infectious clones were nearly identical with each other in gag-pol and env coding regions. These data support the notion that the active locus of infectious RD-114 virus is single in the feline genome. The length of long terminal repeat (LTR) of pCRT1 was 47 bp shorter than those of pSc3c and pRD-UCL. The 47-bp sequence named direct repeat A (DR-A) was duplicated in the U3 region in pSc3c and pRD-UCL. Although several potential enhancer binding sites are present in the DR-A, there was no significant difference in promoter activities between the LTRs of pRD-UCL and pCRT1 in two human cell lines. We also analyzed the splicing pattern of the RD-114 virus by reverse transcription-polymerase chain reaction and confirmed that RD-114 virus is a simple retrovirus. The data presented here will provide basic information about RD-114 virus to solve the contamination issue in live attenuated vaccines.", "journal": "Virus genes", "doi": "10.1007/s11262-012-0759-0", "deposited_data": "Sim", "nuccore_ids": "389560276, 389560273", "bioproject_ids": null, "sra_ids": null}, {"year": 2012, "pmid": "22405627", "author": "Mazari PM", "n_authors": 8, "title": "Comparison of the convergent receptor utilization of a retargeted feline leukemia virus envelope with a naturally-occurring porcine endogenous retrovirus A.", "abstract": "In vitro screening of randomized FeLV Envelope libraries identified the CP isolate, which enters cells through HuPAR-1, one of two human receptors utilized by porcine endogenous retrovirus-A (PERV-A), a distantly related gammaretrovirus. The CP and PERV-A Envs however, share little amino acid homology. Their receptor utilization was examined to define the common receptor usage of these disparate viral Envs. We demonstrate that the receptor usage of CP extends to HuPAR-2 but not to the porcine receptor PoPAR, the cognate receptor for PERV-A. Reciprocal interference between virus expressing CP and PERV-A Envs was observed on human cells. Amino acid residues localized to within the putative second extracellular loop (ECL-2) of PAR-1 and PAR-2 are found to be critical for CP envelope function. Through a panel of receptor chimeras and point mutations, this area was also found to be responsible for the differential usage of the PoPAR receptor between CP and PERV-A.", "journal": "Virology", "doi": "10.1016/j.virol.2012.02.012", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2012, "pmid": "21997239", "author": "Yoshikawa R", "n_authors": 3, "title": "Presence of infectious RD-114 virus in a proportion of canine parvovirus isolates.", "abstract": "We recently found that certain canine live attenuated vaccines produced using `non-feline' cell lines were contaminated with an infectious feline endogenous retrovirus, termed RD-114 virus. We suspected that RD-114 virus may have contaminated the seed stock of canine parvovirus (CPV) during the production of the contaminated vaccines. In this study, we collected stock viruses of CPVs propagated in a feline cell line, and checked the presence of infectious RD-114 virus. Consequently, we found that RD-114 viral RNA was present in all stock viruses, and 7 out of 18 stock viruses were contaminated with infectious RD-114 virus. We also found that RD-114 virus was stable physically and is capable of retaining its infectivity for a long period at -80°C.", "journal": "The Journal of veterinary medical science", "doi": "10.1292/jvms.11-0219", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2013, "pmid": "24148555", "author": "Denner J", "n_authors": 2, "title": "Koala retroviruses: characterization and impact on the life of koalas.", "abstract": "Koala retroviruses (KoRV) have been isolated from wild and captive koalas in Australia as well as from koala populations held in zoos in other countries. They are members of the genus Gammaretrovirus, are most closely related to gibbon ape leukemia virus (GaLV), feline leukemia virus (FeLV) and porcine endogenous retrovirus (PERV) and are likely the result of a relatively recent trans-species transmission from rodents or bats. The first KoRV to be isolated, KoRV-A, is widely distributed in the koala population in both integrated endogenous and infectious exogenous forms with evidence from museum specimens older than 150 years, indicating a relatively long engagement with the koala population. More recently, additional subtypes of KoRV that are not endogenized have been identified based on sequence differences and host cell receptor specificity (KoRV-B and KoRV-J). A specific association with fatal lymphoma and leukemia has been recently suggested for KoRV-B. In addition, it has been proposed that the high viral loads found in many animals may lead to immunomodulation resulting in a higher incidence of diseases such as chlamydiosis. Although the molecular basis of this immunomodulation is still unclear, purified KoRV particles and a peptide corresponding to a highly conserved domain in the envelope protein have been shown to modulate cytokine expression in vitro, similar to that induced by other gammaretroviruses. While much is still to be learned, KoRV induced lymphoma/leukemia and opportunistic disease arising as a consequence of immunomodulation are likely to play an important role in the stability of koala populations both in the wild and in captivity.", "journal": "Retrovirology", "doi": "10.1186/1742-4690-10-108", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2013, "pmid": "23966402", "author": "Ito J", "n_authors": 8, "title": "Refrex-1, a soluble restriction factor against feline endogenous and exogenous retroviruses.", "abstract": "The host defense against viral infection is acquired during the coevolution or symbiosis of the host and pathogen. Several cellular factors that restrict retroviral infection have been identified in the hosts. Feline leukemia virus (FeLV) is a gammaretrovirus that is classified into several receptor interference groups, including a novel FeLV-subgroup D (FeLV-D) that we recently identified. FeLV-D is generated by transduction of the env gene of feline endogenous gammaretrovirus of the domestic cat (ERV-DCs) into FeLV. Some ERV-DCs are replication competent viruses which are present and hereditary in cats. We report here the determination of new viral receptor interference groups and the discovery of a soluble antiretroviral factor, termed Refrex-1. Detailed analysis of FeLV-D strains and ERV-DCs showed two receptor interference groups that are distinct from other FeLV subgroups, and Refrex-1 specifically inhibited one of them. Refrex-1 is characterized as a truncated envelope protein of ERV-DC and includes the N-terminal region of surface unit, which is a putative receptor-binding domain, but lacks the transmembrane region. Refrex-1 is efficiently secreted from the cells and appears to cause receptor interference extracellularly. Two variants of Refrex-1 encoded by provirus loci, ERV-DC7 and DC16, are expressed in a broad range of feline tissues. The host retains Refrex-1 as an antiretroviral factor, which may potentially prevent reemergence of the ERVs and the emergence of novel ERV-related viruses in cats. Refrex-1 may have been acquired during endogenization of ERV-DCs and may play an important role in retroviral restriction and antiviral defense in cats.", "journal": "Journal of virology", "doi": "10.1128/JVI.01267-13", "deposited_data": "Sim", "nuccore_ids": "543583510, 543583508, 543583506, 543583504, 543583503, 543583502, 2131078298, 2130975037, 2130975034, 2130975031, 2130975028, 2130975025, 2130907928", "bioproject_ids": null, "sra_ids": null}, {"year": 2013, "pmid": "23585909", "author": "Fukuma A", "n_authors": 4, "title": "A new approach to establish a cell line with reduced risk of endogenous retroviruses.", "abstract": "Endogenous retroviruses (ERVs) are integrated as DNA proviruses in the genomes of all mammalian species. Several ERVs are replication-competent and produced as fully infectious viruses from host cell. Thus, live-attenuated vaccines and biological substances have been prepared using the cell lines which may produce ERV. Indeed, we recently reported that several commercial live-attenuated vaccines for pets were contaminated with the infectious feline endogenous retrovirus, RD-114. In this study, to establish a cell line for vaccine manufacture with reduced risk of ERVs, we generated a cell line stably expressing human tetherin (Teth-CRFK cells). The release of infectious ERV from Teth-CRFK cells was suppressed to undetectable levels, while the production of parvovirus in Teth-CRFK cells was similar to that in parental CRFK cells. These observations suggest that Teth-CRFK cells will be useful as a cell line for the manufacture of live-attenuated vaccines or biological substances with reduced risk of ERV.", "journal": "PloS one", "doi": "10.1371/journal.pone.0061530", "deposited_data": "Sim", "nuccore_ids": "1519313265", "bioproject_ids": null, "sra_ids": null}, {"year": 2013, "pmid": "23580426", "author": "Shimode S", "n_authors": 4, "title": "Characterization of feline ASCT1 and ASCT2 as RD-114 virus receptor.", "abstract": "RD-114 virus is a replication-competent feline endogenous retrovirus (ERV). RD-114 virus had been thought to be xenotropic; however, recent findings indicate that RD-114 virus is polytropic and can infect and grow efficiently in feline cells. Receptor(s) for RD-114 virus has not been identified and characterized in cats. In this study, we confirmed that two feline sodium-dependent neutral amino acid transporters (ASCTs), fASCT1 and fASCT2, function as RD-114 virus receptors. By chimeric analyses of feline and murine ASCTs, we revealed that extracellular loop 2 of both fASCT1 and fASCT2 determines the susceptibility to RD-114 virus. Further, we revealed ubiquitous expression of these genes, consistent with the general metabolic role of the ASCT molecules. Our study indicates that RD-114 virus may reinfect tissues and cells in cats, once the virus is activated. Implications of the involvement of RD-114 virus in feline oncogenesis are also discussed.", "journal": "The Journal of general virology", "doi": "10.1099/vir.0.052928-0", "deposited_data": "Sim", "nuccore_ids": "589811488, 523704453, 499534780, 499534778, 2131055927, 2131055925, 589811488, 523704453", "bioproject_ids": null, "sra_ids": null}, {"year": 2013, "pmid": "23405366", "author": "Stewart H", "n_authors": 4, "title": "Complete genome sequences of two feline leukemia virus subgroup B isolates with novel recombination sites.", "abstract": "It is generally accepted that all primary isolates of feline leukemia virus (FeLV) contain a subgroup A virus (FeLV-A) that is essential for transmission. In contrast, FeLV-B is thought to arise de novo in the infected animal through RNA recombination events with endogenous FeLV transcripts, presumably through copackaging of RNA from endogenous FeLV and exogenous FeLV-A. Here, we report the complete genome sequences of two novel strains of FeLV-B (FeLV-2518 and FeLV-4314) that were isolated in the absence of FeLV-A. The env genes of these isolates have been characterized previously, and the 3' recombination sites have been identified. We describe herein the 5' recombination breakpoints of each virus. These breakpoints were found to be within the signal peptide of the env gene and the reverse transcriptase-coding region, respectively. This is the first report of a recombination site within the pol gene of an FeLV-B genome and the first genetic characterization of multiple independently arising FeLV-B isolates that have been identified without a functional FeLV-A ancestral virus.", "journal": "Genome announcements", "doi": "10.1128/genomeA.00036-12", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2013, "pmid": "23269813", "author": "Mendoza R", "n_authors": 3, "title": "Disruption of thiamine uptake and growth of cells by feline leukemia virus subgroup A.", "abstract": "Feline leukemia virus (FeLV) is still a major cause of morbidity and mortality in domestic cats and some wild cats despite the availability of relatively effective vaccines against the virus. FeLV subgroup A (FeLV-A) is transmitted in natural infections, and FeLV subgroups B, C, and T can evolve directly from FeLV-A by mutation and/or recombination with endogenous retroviruses in domestic cats, resulting in a variety of pathogenic outcomes. The cell surface entry receptor for FeLV-A is a putative thiamine transporter (THTR1). Here, we have addressed whether FeLV-A infection might disrupt thiamine uptake into cells and, because thiamine is an essential nutrient, whether this disruption might have pathological consequences. First, we cloned the cat ortholog of the other of the two known thiamine transporters in mammals, THTR2, and we show that feline THTR1 (feTHTR1) and feTHTR2 both mediate thiamine uptake, but feTHTR2 does not function as a receptor for FeLV-A. We found that feTHTR1 is widely expressed in cat tissues and in cell lines, while expression of feTHTR2 is restricted. Thiamine uptake mediated by feTHTR1 was indeed blocked by FeLV-A infection, and in feline fibroblasts that naturally express feTHTR1 and not feTHTR2, this blockade resulted in a growth arrest at physiological concentrations of extracellular thiamine. The growth arrest was reversed at high extracellular concentrations of thiamine. Our results show that FeLV-A infection can indeed disrupt thiamine uptake with pathological consequences. A prediction of these experiments is that raising the plasma levels of thiamine in FeLV-infected cats may ameliorate the pathogenic effects of infection.", "journal": "Journal of virology", "doi": "10.1128/JVI.03203-12", "deposited_data": "Sim", "nuccore_ids": "523704407, 410695830, 90403621, 89112747, 2131068042, 2131002666, 2131002664, 2131002662, 2131002661, 2131002660, 2131002659, 2131002657, 2131002656, 2131002654, 2131002653, 2131002652, 2131002651, 523704407, 90403621", "bioproject_ids": null, "sra_ids": null}, {"year": 2013, "pmid": "23249763", "author": "Denner J", "n_authors": 1, "title": "Immunising with the transmembrane envelope proteins of different retroviruses including HIV-1: a comparative study.", "abstract": "The induction of neutralizing antibodies is a promising way to prevent retrovirus infections. Neutralizing antibodies are mainly directed against the envelope proteins, which consist of two molecules, the surface envelope (SU) protein and the transmembrane envelope (TM) protein. Antibodies broadly neutralizing the human immunodeficiencvy virus-1 (HIV-1) and binding to the TM protein gp41 of the virus have been isolated from infected individuals. Their epitopes are located in the membrane proximal external region (MPER). Since there are difficulties to induce such neutralizing antibodies as basis for an effective AIDS vaccine, we performed a comparative analysis immunising with the TM proteins of different viruses from the family Retroviridae. Both subfamilies, the Orthoretrovirinae and the Spumaretrovirinae were included. In this study, the TM proteins of three gammaretroviruses including (1) the porcine endogenous retrovirus (PERV), (2) the Koala retrovirus (KoRV), (3) the feline leukemia virus (FeLV), of two lentiviruses, HIV-1, HIV-2, and of two spumaviruses, the feline foamy virus (FFV) and the primate foamy virus (PFV) were used for immunisation. Whereas in all immunisation studies binding antibodies were induced, neutralizing antibodies were only found in the case of the gammaretroviruses. The induced antibodies were directed against the MPER and the fusion peptide proximal region (FPPR) of their TM proteins; however only the antibodies against the MPER were neutralizing. Most importantly, the epitopes in the MPER were localized in the same position as the epitopes of the antibodies broadly neutralizing HIV-1 in the TM protein gp41 of HIV-1, indicating that the MPER is an effective target for the neutralization of retroviruses.", "journal": "Human vaccines & immunotherapeutics", "doi": "10.4161/hv.23221", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2014, "pmid": "25143822", "author": "Tamazian G", "n_authors": 25, "title": "Annotated features of domestic cat - Felis catus genome.", "abstract": "Domestic cats enjoy an extensive veterinary medical surveillance which has described nearly 250 genetic diseases analogous to human disorders. Feline infectious agents offer powerful natural models of deadly human diseases, which include feline immunodeficiency virus, feline sarcoma virus and feline leukemia virus. A rich veterinary literature of feline disease pathogenesis and the demonstration of a highly conserved ancestral mammal genome organization make the cat genome annotation a highly informative resource that facilitates multifaceted research endeavors. Here we report a preliminary annotation of the whole genome sequence of Cinnamon, a domestic cat living in Columbia (MO, USA), bisulfite sequencing of Boris, a male cat from St. Petersburg (Russia), and light 30× sequencing of Sylvester, a European wildcat progenitor of cat domestication. The annotation includes 21,865 protein-coding genes identified by a comparative approach, 217 loci of endogenous retrovirus-like elements, repetitive elements which comprise about 55.7% of the whole genome, 99,494 new SNVs, 8,355 new indels, 743,326 evolutionary constrained elements, and 3,182 microRNA homologues. The methylation sites study shows that 10.5% of cat genome cytosines are methylated. An assisted assembly of a European wildcat, Felis silvestris silvestris, was performed; variants between F. silvestris and F. catus genomes were derived and compared to F. catus. The presented genome annotation extends beyond earlier ones by closing gaps of sequence that were unavoidable with previous low-coverage shotgun genome sequencing. The assembly and its annotation offer an important resource for connecting the rich veterinary and natural history of cats to genome discovery.", "journal": "GigaScience", "doi": "10.1186/2047-217X-3-13", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2014, "pmid": "25085922", "author": "David VA", "n_authors": 13, "title": "Endogenous retrovirus insertion in the KIT oncogene determines white and white spotting in domestic cats.", "abstract": "The Dominant White locus (W) in the domestic cat demonstrates pleiotropic effects exhibiting complete penetrance for absence of coat pigmentation and incomplete penetrance for deafness and iris hypopigmentation. We performed linkage analysis using a pedigree segregating White to identify KIT (Chr. B1) as the feline W locus. Segregation and sequence analysis of the KIT gene in two pedigrees (P1 and P2) revealed the remarkable retrotransposition and evolution of a feline endogenous retrovirus (FERV1) as responsible for two distinct phenotypes of the W locus, Dominant White, and white spotting. A full-length (7125 bp) FERV1 element is associated with white spotting, whereas a FERV1 long terminal repeat (LTR) is associated with all Dominant White individuals. For purposes of statistical analysis, the alternatives of wild-type sequence, FERV1 element, and LTR-only define a triallelic marker. Taking into account pedigree relationships, deafness is genetically linked and associated with this marker; estimated P values for association are in the range of 0.007 to 0.10. The retrotransposition interrupts a DNAase I hypersensitive site in KIT intron 1 that is highly conserved across mammals and was previously demonstrated to regulate temporal and tissue-specific expression of KIT in murine hematopoietic and melanocytic cells. A large-population genetic survey of cats (n = 270), representing 30 cat breeds, supports our findings and demonstrates statistical significance of the FERV1 LTR and full-length element with Dominant White/blue iris (P < 0.0001) and white spotting (P < 0.0001), respectively.", "journal": "G3 (Bethesda, Md.)", "doi": "10.1534/g3.114.013425", "deposited_data": "Sim", "nuccore_ids": "612176508, 612176507", "bioproject_ids": null, "sra_ids": null}, {"year": 2014, "pmid": "24688176", "author": "Munro HJ", "n_authors": 5, "title": "Seroprevalence of feline immunodeficiency virus (FIV) and feline leukemia virus (FeLV) in shelter cats on the island of Newfoundland, Canada.", "abstract": "Feline immunodeficiency virus (FIV) and feline leukemia virus (FeLV) are retroviruses found within domestic and wild cat populations. These viruses cause severe illnesses that eventually lead to death. Housing cats communally for long periods of time makes shelters at high risk for virus transmission among cats. We tested 548 cats from 5 different sites across the island of Newfoundland for FIV and FeLV. The overall seroprevalence was 2.2% and 6.2% for FIV and FeLV, respectively. Two sites had significantly higher seroprevalence of FeLV infection than the other 3 sites. Analysis of sequences from the FeLV env gene (envelope gene) from 6 positive cats showed that 4 fell within the FeLV subtype-A, while 2 sequences were most closely related to FeLV subtype-B and endogenous feline leukemia virus (en FeLV). Varying seroprevalence and the variation in sequences at different sites demonstrate that some shelters are at greater risk of FeLV infections and recombination can occur at sites of high seroprevalence.", "journal": "Canadian journal of veterinary research = Revue canadienne de recherche veterinaire", "doi": null, "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2014, "pmid": "24486949", "author": "Vinchi F", "n_authors": 8, "title": "Heme exporter FLVCR1a regulates heme synthesis and degradation and controls activity of cytochromes P450.", "abstract": "The liver has one of the highest rates of heme synthesis of any organ. More than 50% of the heme synthesized in the liver is used for synthesis of P450 enzymes, which metabolize exogenous and endogenous compounds that include natural products, hormones, drugs, and carcinogens. Feline leukemia virus subgroup C cellular receptor 1a (FLVCR1a) is plasma membrane heme exporter that is ubiquitously expressed and controls intracellular heme content in hematopoietic lineages. We investigated the role of Flvcr1a in liver function in mice. We created mice with conditional disruption of Mfsd7b, which encodes Flvcr1a, in hepatocytes (Flvcr1a(fl/fl);alb-cre mice). Mice were analyzed under basal conditions, after phenylhydrazine-induced hemolysis, and after induction of cytochromes P450 synthesis. Livers were collected and analyzed by histologic, quantitative real-time polymerase chain reaction, and immunoblot analyses. Hepatic P450 enzymatic activities were measured. Flvcr1a(fl/fl);alb-cre mice accumulated heme and iron in liver despite up-regulation of heme oxygenase 1, ferroportin, and ferritins. Hepatic heme export activity of Flvcr1a was closely associated with heme biosynthesis, which is required to sustain cytochrome induction. Upon cytochromes P450 stimulation, Flvcr1a(fl/fl);alb-cre mice had reduced cytochrome activity, associated with accumulation of heme in hepatocytes. The expansion of the cytosolic heme pool in these mice was likely responsible for the early inhibition of heme synthesis and increased degradation of heme, which reduced expression and activity of cytochromes P450. In livers of mice, Flvcr1a maintains a free heme pool that regulates heme synthesis and degradation as well as cytochromes P450 expression and activity. These findings have important implications for drug metabolism.", "journal": "Gastroenterology", "doi": "10.1053/j.gastro.2014.01.053", "deposited_data": "Sim", "nuccore_ids": "924181778, 924181484, 124486924, 2697292347, 2697292226, 2697292200, 2697292197, 2697292190, 2697292183, 2199610746, 2199610745, 2199610739, 2199610697, 2199610589, 2199610575, 1907148755, 1907148752, 1907148749, 1907148747, 1907148745, 1907148743, 1907148740, 1907148738, 1907148736, 1907148733, 924181778, 924181484, 195947362, 124486924", "bioproject_ids": null, "sra_ids": null}, {"year": 2014, "pmid": "24068581", "author": "Yoshikawa R", "n_authors": 4, "title": "Contamination of live attenuated vaccines with an infectious feline endogenous retrovirus (RD-114 virus).", "abstract": "Retroviruses are classified as exogenous and endogenous retroviruses according to the mode of transmission. Endogenous retroviruses (ERVs) are retroviruses which have been integrated into germ-line cells and inherited from parents to offspring. Most ERVs are inactivated by deletions and mutations; however, certain ERVs maintain their infectivity and infect the same host and new hosts as exogenous retroviruses. All domestic cats have infectious ERVs, termed RD-114 virus. Several canine and feline attenuated vaccines are manufactured using RD-114 virus-producing cell lines such as Crandell-Rees feline kidney cells; therefore, it is possible that infectious RD-114 virus contaminates live attenuated vaccines. Recently, Japanese and UK research groups found that several feline and canine vaccines were indeed contaminated with infectious RD-114 virus. This was the first incidence of contamination of 'infectious' ERVs in live attenuated vaccines. RD-114 virus replicates efficiently in canine cell lines and primary cells. Therefore, it is possible that RD-114 virus infects dogs following inoculation with contaminated vaccines and induces proliferative diseases and immune suppression, if it adapts to grow efficiently in dogs. In this review, we summarize the incidence of contamination of RD-114 virus in live attenuated vaccines and potential risks of infection with RD-114 virus in dogs.", "journal": "Archives of virology", "doi": "10.1007/s00705-013-1809-1", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2015, "pmid": "26581999", "author": "Ito J", "n_authors": 4, "title": "Ancestral Mutations Acquired in Refrex-1, a Restriction Factor against Feline Retroviruses, during its Cooption and Domestication.", "abstract": "Endogenous retroviruses (ERVs) are remnants of ancestral retroviral infections of germ cells. Retroviral endogenization is an adaptation process for the host genome, and ERVs are gradually attenuated or inactivated by mutation. However, some ERVs that have been \"domesticated\" by their hosts eventually gain physiological functions, such as placentation or viral resistance. We previously reported the discovery of Refrex-1, a soluble antiretroviral factor in domestic cats that specifically inhibits infection by feline leukemia virus subgroup D (FeLV-D), a chimeric virus of FeLV, and a feline ERV, ERV-DC. Refrex-1 is a truncated envelope protein (Env) encoded by both ERV-DC7 and ERV-DC16 proviral loci. Here, we reconstituted ancestral and functional Env from ERV-DC7 and ERV-DC16 envelope genes (env) by inducing reverse mutations. Unexpectedly, ERV-DC7 and ERV-DC16 full-length Env (ERV-DC7 fl and ERV-DC16 fl), reconstructed by removing stop codons, did not produce infectious viral particles. ERV-DC7 fl and ERV-DC16 fl were highly expressed in cells but were not cleaved into surface subunits (SU) and transmembrane subunits, nor were they incorporated into virions. G407R/N427I-A429T and Y431D substitutions within the SU C-terminal domain of ERV-DC7 fl and ERV-DC16 fl, respectively, caused these dysfunctions. The residues glycine 407 and tyrosine 431 are relatively conserved among infectious gammaretroviruses, and their substitution causes the same dysfunctions as the tested retroviruses. Our results reveal that specific mutations within the SU C-terminal domain suppressed Env cleavage and incorporation into virions and indicate that these mutations contributed to the domestication of Refrex-1 through multistep events that occurred in the postintegration period. Domestic cats are colonized with various exogenous retroviruses (exRVs), such as feline leukemia virus (FeLV), and their genomes contain numerous ERVs, some of which are replication-competent proviruses. The feline hosts, exRVs, and ERVs have complicated genetic interactions and provide an interesting field model for triangular relationships: recombination between FeLV and ERV-DC, which is a feline ERV, generated FeLV-D, a chimeric virus, and FeLV-D is restricted by Refrex-1, an antiretroviral factor corresponding to truncated Env of ERV-DC7 and ERV-DC16. Here, we reconstructed ancestral, functional Env from ERV-DC7 and ERV-DC16 env by inducing reverse mutations to elucidate how Refrex-1 was generated from its ancestor. Our results reveal that they were repeatedly inactivated by mutations preventing Env maturation. Our results provide insights into how ERVs were \"domesticated\" by their hosts and identify the mutations that mediated these evolutions. Notably, experiments that restore inactivated ERVs might uncover previously unrecognized features or properties of retroviruses.", "journal": "Journal of virology", "doi": "10.1128/JVI.01904-15", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2015, "pmid": "26164289", "author": "Hashimoto-Gotoh A", "n_authors": 3, "title": "Comparison between S+L- assay and LacZ marker rescue assay for detecting replication-competent gammaretroviruses.", "abstract": "To avoid contamination of adventitious gammaretroviruses in biological products such as vaccines, it is necessary to check the master seed cells for manufacturing. There are several assays to detect infectious gammaretroviruses. Among these, sarcoma-positive, leukemia-negative (S+L-) assay is a classical infectivity assay, which is often recommended in governmental guidelines. The S+L- cells used in S+L- assay generate unique focus upon the infection of replication-competent gammaretroviruses. Although S+L- assay is well recognized for the detection, their applicability is questionable in some cases. On the other hand, LacZ marker rescue (LMR) assay detects infectious gammaretroviruses by transducing LacZ marker gene to the target cells, which shows lacZ-positive foci if the infectious virus is present. In this study, we compared LMR and S+L- assays for detection of a variety of endogenous and exogenous gammaretroviruses. As results, LMR assay could detect all gammaretroviruses examined. On the other hand, S+L- assay using feline S+L- cells, termed QN10S, could not detect porcine endogenous retrovirus (PERV) subgroups A/B. Further, S+L- mink cells could not detect feline leukemia virus subgroups B in addition to PERV-A/B. These data indicate that LMR assay is better suited to detect wider range of gammaretroviruses.", "journal": "Biologicals : journal of the International Association of Biological Standardization", "doi": "10.1016/j.biologicals.2015.06.007", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2015, "pmid": "25936996", "author": "Miyaho RN", "n_authors": 9, "title": "Susceptibility of domestic animals to a pseudotype virus bearing RD-114 virus envelope protein.", "abstract": "Retroviral vectors are used for gene transduction into cells and have been applied to gene therapy. Retroviral vectors using envelope protein (Env) of RD-114 virus, a feline endogenous retrovirus, have been used for gene transduction. In this study, we investigated the susceptibility to RD-114 Env-pseudotyped virus in twelve domestic animals including cattle, sheep, horse, pig, dog, cat, ferret, mink, rabbit, rat, mouse, and quail. Comparison of nucleotide sequences of ASCT2 (SLC1A5), a receptor of RD-114 virus, in 10 mammalian and 2 avian species revealed that insertion and deletion events at the region C of ASCT2 where RD-114 viral Env interacts occurred independently in the mouse and rat lineage and in the chicken and quail lineage. By the pseudotype virus infection assay, we found that RD-114 Env-pseudotyped virus could efficiently infect all cell lines except those from mouse and rat. Furthermore, we confirmed that bovine ASCT2 (bASCT2) functions as a receptor for RD-114 virus infection. We also investigated bASCT2 mRNA expression in cattle tissues and found that it is expressed in various tissues including lung, spleen and kidney. These results indicate that retrovirus vectors with RD-114 virus Env can be used for gene therapy in large domestic animals in addition to companion animals such as cat and dog.", "journal": "Gene", "doi": "10.1016/j.gene.2015.04.079", "deposited_data": "Sim", "nuccore_ids": "733168337, 31341563, 1676325246, 1676318081, 1519241848, 31341563", "bioproject_ids": null, "sra_ids": null}, {"year": 2015, "pmid": "25892717", "author": "Kawamura M", "n_authors": 7, "title": "Genetic diversity in the feline leukemia virus gag gene.", "abstract": "Feline leukemia virus (FeLV) belongs to the Gammaretrovirus genus and is horizontally transmitted among cats. FeLV is known to undergo recombination with endogenous retroviruses already present in the host during FeLV-subgroup A infection. Such recombinant FeLVs, designated FeLV-subgroup B or FeLV-subgroup D, can be generated by transduced endogenous retroviral env sequences encoding the viral envelope. These recombinant viruses have biologically distinct properties and may mediate different disease outcomes. The generation of such recombinant viruses resulted in structural diversity of the FeLV particle and genetic diversity of the virus itself. FeLV env diversity through mutation and recombination has been studied, while gag diversity and its possible effects are less well understood. In this study, we investigated recombination events in the gag genes of FeLVs isolated from naturally infected cats and reference isolates. Recombination and phylogenetic analyses indicated that the gag genes often contain endogenous FeLV sequences and were occasionally replaced by entire endogenous FeLV gag genes. Phylogenetic reconstructions of FeLV gag sequences allowed for classification into three distinct clusters, similar to those previously established for the env gene. Analysis of the recombination junctions in FeLV gag indicated that these variants have similar recombination patterns within the same genotypes, indicating that the recombinant viruses were horizontally transmitted among cats. It remains to be investigated whether the recombinant sequences affect the molecular mechanism of FeLV transmission. These findings extend our understanding of gammaretrovirus evolutionary patterns in the field.", "journal": "Virus research", "doi": "10.1016/j.virusres.2015.04.008", "deposited_data": "Sim", "nuccore_ids": "675822143, 675822142, 675821855, 675821853, 675821852, 675821851, 675821849, 675821848, 675821846, 675821844, 675821842, 675821841, 675821840, 675821838, 675821837, 675821836, 675821835, 675821834, 675821833, 675821832, 675821831, 675821830, 675821829, 675821828, 675821827, 675821826, 675821825, 675821824, 675821823, 675821822, 675821821, 675821820, 675821819, 675821818, 675821817, 675821816, 675821815, 675821814, 675821813, 675821812, 675821811, 675821810, 675821809, 675821808, 675821807, 675821806, 675821805, 675821804, 675821803, 675821801, 675821800, 675821798, 675821796, 675821794, 675821792, 675821790, 675821789, 675821787, 675821785, 675821783, 675821781, 675821780, 675821778, 675821776, 675821774, 675821772, 675821770, 675821768, 675821766, 675821764, 675821762, 675821760, 675821758, 675821756, 675821754, 675821752, 675821750, 675821748, 675821746, 675821744, 675821742, 675821741, 675821739, 675821737, 675821735, 675821733, 675821731, 675821729, 675821727, 675821725, 675821723, 675821721, 675821719, 675821717, 675821715, 675821713, 675821711, 675821709, 675821707, 675821706, 675821704, 675821702, 675821700, 675821698, 675821696, 675821694, 675821692, 675821691, 675821689, 675821687, 675821685, 675821684, 675821683, 675821681, 675821679, 675821677, 675821675, 675821673, 675821671, 675821669, 675821667, 675821665, 675821664, 675821662, 675821660, 675821658, 675821656, 675821654, 675821652, 675821650, 675821648, 675821647, 675821645, 675821643, 675821641, 675821639, 675821637, 675821635, 675821633, 675821631, 675821629, 675821627, 675821625, 675821623, 675821622, 675821620, 675821619, 675821617", "bioproject_ids": null, "sra_ids": null}, {"year": 2015, "pmid": "25879730", "author": "Krunic M", "n_authors": 7, "title": "Decreased expression of endogenous feline leukemia virus in cat lymphomas: a case control study.", "abstract": "Cats infected with exogenous feline leukemia virus (exFeLV) have a higher chance of lymphoma development than uninfected cats. Furthermore, an increased exFeLV transcription has been detected in lymphomas compared to non-malignant tissues. The possible mechanisms of lymphoma development by exFeLV are insertional mutagenesis or persistent stimulation of host immune cells by viral antigens, bringing them at risk for malignant transformation. Vaccination of cats against exFeLV has in recent years decreased the overall infection rate in most countries. Nevertheless, an increasing number of lymphomas have been diagnosed among exFeLV-negative cats. Endogenous feline leukemia virus (enFeLV) is another retrovirus for which transcription has been observed in cat lymphomas. EnFeLV provirus elements are present in the germline of various cat species and share a high sequence similarity with exFeLV but, due to mutations, are incapable of producing infectious viral particles. However, recombination between exFeLV and enFeLV could produce infectious particles. We examined the FeLV expression in cats that have developed malignant lymphomas and discussed the possible mechanisms that could have induced malignant transformation. For expression analysis we used next-generation RNA-sequencing (RNA-Seq) and for validation reverse transcription quantitative PCR (RT-qPCR). First, we showed that there was no expression of exFeLV in all samples, which eliminates the possibility of recombination between exFeLV and enFeLV. Next, we analyzed the difference in expression of three enFeLV genes between control and lymphoma samples. Our analysis showed an average of 3.40-fold decreased viral expression for the three genes in lymphoma compared to control samples. The results were confirmed by RT-qPCR. There is a decreased expression of enFeLV genes in lymphomas versus control samples, which contradicts previous observations for the exFeLV. Our results suggest that a persistent stimulation of host immune cells is not an appropriate mechanism responsible for malignant transformation caused by feline endogenous retroviruses.", "journal": "BMC veterinary research", "doi": "10.1186/s12917-015-0378-9", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2015, "pmid": "25809630", "author": "Krengel A", "n_authors": 12, "title": "Gammaretrovirus-specific antibodies in free-ranging and captive Namibian cheetahs.", "abstract": "The cheetah population in Namibia is the largest free-ranging population in the world and a key population for research regarding the health status of this species. We used serological methods and quantitative real-time PCR to test free-ranging and captive Namibian cheetahs for the presence of feline leukemia virus (FeLV), a gammaretrovirus that can be highly aggressive in populations with low genetic diversity, such as cheetahs. We also assessed the presence of antibodies to other gammaretroviruses and the responses to a FeLV vaccine developed for domestic cats. Up to 19% of the free-ranging cheetahs, 27% of the captive nonvaccinated cheetahs, and 86% of the captive vaccinated cheetahs tested positive for FeLV antibodies. FeLV-antibody-positive free-ranging cheetahs also tested positive for Rauscher murine leukemia virus antibodies. Nevertheless, FeLV was not detectable by quantitative real-time PCR and no reverse transcriptase activity was detectable by product-enhanced reverse transcriptase assay in the plasma of cheetahs or the supernatants from cultures of peripheral blood mononuclear cells. The presence of antibodies to gammaretroviruses in clinically healthy specimens may be caused either by infection with a low-pathogenic retrovirus or by the expression of endogenous retroviral sequences. The strong humoral immune responses to FeLV vaccination demonstrate that cheetahs can respond to the vaccine and that vaccination against FeLV infection may be beneficial should FeLV infection ever become a threat, as was seen in Iberian lynx and Florida panthers.", "journal": "Clinical and vaccine immunology : CVI", "doi": "10.1128/CVI.00705-14", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2015, "pmid": "25500005", "author": "Boesch A", "n_authors": 9, "title": "Evaluation of the effect of short-term treatment with the integrase inhibitor raltegravir (Isentress) on the course of progressive feline leukemia virus infection.", "abstract": "Cats persistently infected with the gammaretrovirus feline leukemia virus (FeLV) are at risk to die within months to years from FeLV-associated disease, such as immunosuppression, anemia or lymphoma/leukemia. The integrase inhibitor raltegravir has been demonstrated to reduce FeLV replication in vitro. The aim of the present study was to investigate raltegravir in vivo for its safety and efficacy to suppress FeLV replication. The safety was tested in three naïve specified pathogen-free (SPF) cats during a 15 weeks treatment period (initially 20mg then 40mg orally b.i.d.). No adverse effects were noted. The efficacy was tested in seven persistently FeLV-infected SPF cats attained from 18 cats experimentally exposed to FeLV-A/Glasgow-1. The seven cats were treated during nine weeks (40mg then 80mg b.i.d.). Raltegravir was well tolerated even at the higher dose. A significant decrease in plasma viral RNA loads (∼5×) was found; however, after treatment termination a rebound effect was observed. Only one cat developed anti-FeLV antibodies and viral RNA loads remained decreased after treatment termination. Of note, one of the untreated FeLV-A infected cats developed fatal FeLV-C associated anemia within 5 weeks of FeLV-A infection. Moreover, progressive FeLV infection was associated with significantly lower enFeLV loads prior to infection supporting that FeLV susceptibility may be related to the genetic background of the cat. Overall, our data demonstrate the ability of raltegravir to reduce viral replication also in vivo. However, no complete control of viremia was achieved. Further investigations are needed to find an optimized treatment against FeLV. (250 words).", "journal": "Veterinary microbiology", "doi": "10.1016/j.vetmic.2014.10.031", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2015, "pmid": "25462351", "author": "Argaw T", "n_authors": 2, "title": "Mutations altering the gammaretrovirus endoproteolytic motif affect glycosylation of the envelope glycoprotein and early events of the virus life cycle.", "abstract": "Previously, we found that mutation of glutamine to proline in the endoproteolytic cleavage signal of the PERV-C envelope (RQKK to RPKK) resulted in non-infectious vectors. Here, we show that RPKK results in a non-infectious vector when placed in not only a PERV envelope, but also the envelope of a related gammaretrovirus, FeLV-B. The amino acid substitutions do not prevent envelope precursor cleavage, viral core and genome assembly, or receptor binding. Rather, the mutations result in the formation of hyperglycosylated glycoprotein and a reduction in the reverse transcribed minus strand synthesis and undetectable 2-LTR circular DNA in cells exposed to vectors with these mutated envelopes. Our findings suggest novel functions associated with the cleavage signal sequence that may affect trafficking through the glycosylation machinery of the cell. Further, the glycosylation status of the envelope appears to impact post-binding events of the viral life cycle, either membrane fusion, internalization, or reverse transcription.", "journal": "Virology", "doi": "10.1016/j.virol.2014.11.010", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2015, "pmid": "25395593", "author": "Sakaguchi S", "n_authors": 4, "title": "A soluble envelope protein of endogenous retrovirus (FeLIX) present in serum of domestic cats mediates infection of a pathogenic variant of feline leukemia virus.", "abstract": "T-lymphotropic feline leukemia virus (FeLV-T), a highly pathogenic variant of FeLV, induces severe immunosuppression in cats. FeLV-T is fusion defective because in its PHQ motif, a gammaretroviral consensus motif in the N terminus of an envelope protein, histidine is replaced with aspartate. Infection by FeLV-T requires FeLIX, a truncated envelope protein encoded by an endogenous FeLV, for transactivation of infectivity and Pit1 for binding FeLIX. Although Pit1 is present in most tissues in cats, the expression of FeLIX is limited to certain cells in lymphoid organs. Therefore, the host cell range of FeLV-T was thought to be restricted to cells expressing FeLIX. However, because FeLIX is a soluble factor and is expressed constitutively in lymphoid organs, we presumed it to be present in blood and evaluated its activities in sera of various mammalian species using a pseudotype assay. We demonstrated that cat serum has FeLIX activity at a functional level, suggesting that FeLIX is present in the blood and that FeLV-T may be able to infect cells expressing Pit1 regardless of the expression of FeLIX in vivo. In addition, FeLIX activities in sera were detected only in domestic cats and not in other feline species tested. To our knowledge, this is the first report to prove that a large amount of truncated envelope protein of endogenous retrovirus is circulating in the blood to facilitate the infection of a pathogenic exogenous retrovirus.", "journal": "The Journal of general virology", "doi": "10.1099/vir.0.071688-0", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2016, "pmid": "27466428", "author": "Kuse K", "n_authors": 9, "title": "Existence of Two Distinct Infectious Endogenous Retroviruses in Domestic Cats and Their Different Strategies for Adaptation to Transcriptional Regulation.", "abstract": "Endogenous retroviruses (ERVs) are the remnants of ancient retroviral infections of germ cells. Previous work identified one of the youngest feline ERV groups, ERV-DC, and reported that two ERV-DC loci, ERV-DC10 and ERV-DC18 (ERV-DC10/DC18), can replicate in cultured cells. Here, we identified another replication-competent provirus, ERV-DC14, on chromosome C1q32. ERV-DC14 differs from ERV-DC10/DC18 in its phylogeny, receptor usage, and, most notably, transcriptional activities; although ERV-DC14 can replicate in cultured cells, it cannot establish a persistent infection owing to its low transcriptional activity. Furthermore, we examined ERV-DC transcription and its regulation in feline tissues. Quantitative reverse transcription-PCR (RT-PCR) detected extremely low ERV-DC10 expression levels in feline tissues, and bisulfite sequencing showed that 5' long terminal repeats (LTRs) of ERV-DC10/DC18 are significantly hypermethylated in feline blood cells. Reporter assays found that the 5'-LTR promoter activities of ERV-DC10/DC18 are high, whereas that of ERV-DC14 is low. This difference in promoter activity is due to a single substitution from A to T in the LTR, and reverse mutation at this nucleotide in ERV-DC14 enhanced its replication and enabled it to persistently infect cultured cells. Therefore, ERV-DC LTRs can be divided into two types based on this nucleotide, the A type or T type, which have strong or attenuated promoter activity, respectively. Notably, ERV-DCs with T-type LTRs, such as ERV-DC14, have expanded in the cat genome significantly more than A-type ERV-DCs, despite their low promoter activities. Our results provide insights into how the host controls potentially infectious ERVs and, conversely, how ERVs adapt to and invade the host genome. The domestic cat genome contains many endogenous retroviruses, including ERV-DCs. These ERV-DCs have been acquired through germ cell infections with exogenous retroviruses. Some of these ERV-DCs are still capable of producing infectious virions. Hosts must tightly control these ERVs because replication-competent viruses in the genome pose a risk to the host. Here, we investigated how ERV-DCs are adapted by their hosts. Replication-competent viruses with strong promoter activity, such as ERV-DC10 and ERV-DC18, were suppressed by promoter methylation in LTRs. On the other hand, replication-competent viruses with weak promoter activity, such as ERV-DC14, seemed to escape strict control via promoter methylation by the host. Interestingly, ERV-DCs with weak promoter activity, such as ERV-DC14, have expanded in the cat genome significantly more than ERV-DCs with strong promoter activity. Our results improve the understanding of the host-virus conflict and how ERVs adapt in their hosts over time.", "journal": "Journal of virology", "doi": "10.1128/JVI.00716-16", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2016, "pmid": "27138041", "author": "Hübner J", "n_authors": 14, "title": "Generation of Genetically Engineered Precursor T-Cells From Human Umbilical Cord Blood Using an Optimized Alpharetroviral Vector Platform.", "abstract": "Retroviral engineering of hematopoietic stem cell-derived precursor T-cells (preTs) opens the possibility of targeted T-cell transfer across human leukocyte antigen (HLA)-barriers. Alpharetroviral vectors exhibit a more neutral integration pattern thereby reducing the risk of insertional mutagenesis. Cord blood-derived CD34+ cells were transduced and differentiated into preTs in vitro. Two promoters, elongation-factor-1-short-form, and a myeloproliferative sarcoma virus variant in combination with two commonly used envelopes were comparatively assessed choosing enhanced green fluorescent protein or a third-generation chimeric antigen receptor (CAR) against CD123 as gene of interest. Furthermore, the inducible suicide gene iCaspase 9 has been validated. Combining the sarcoma virus-derived promoter with a modified feline endogenous retrovirus envelope glycoprotein yielded in superior transgene expression and transduction rates. Fresh and previously frozen CD34+ cells showed similar transduction and expansion rates. Transgene-positive cells did neither show proliferative impairment nor alteration in their lymphoid differentiation profile. The sarcoma virus-derived promoter only could express sufficient levels of iCaspase 9 to mediate dimerizer-induced apoptosis. Finally, the CD123 CAR was efficiently expressed in CD34+ cells and proved to be functional when expressed on differentiated T-cells. Therefore, the transduction of CD34+ cells with alpharetroviral vectors represents a feasible and potentially safer approach for stem cell-based immunotherapies for cancer.", "journal": "Molecular therapy : the journal of the American Society of Gene Therapy", "doi": "10.1038/mt.2016.89", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2016, "pmid": "26747244", "author": "Ramírez H", "n_authors": 6, "title": "Genotyping of feline leukemia virus in Mexican housecats.", "abstract": "Feline leukemia virus (FeLV) is a retrovirus with variable rates of infection globally. DNA was obtained from cats' peripheral blood mononuclear cells, and proviral DNA of pol and env genes was detected using PCR. Seventy-six percent of cats scored positive for FeLV using env-PCR; and 54 %, by pol-PCR. Phylogenetic analysis of both regions identified sequences that correspond to a group that includes endogenous retroviruses. They form an independent branch and, therefore, a new group of endogenous viruses. Cat gender, age, outdoor access, and cohabitation with other cats were found to be significant risk factors associated with the disease. This strongly suggests that these FeLV genotypes are widely distributed in the studied feline population in Mexico.", "journal": "Archives of virology", "doi": "10.1007/s00705-015-2740-4", "deposited_data": "Sim", "nuccore_ids": "927348086, 927348085, 927348083, 927348082, 927348080, 927348078, 927348076, 927348074, 927348072, 927348070, 927348068, 927348066, 927348064, 927348062, 927348060, 927348058, 927348056, 927348054, 927348052, 927348050, 927348048, 927348046, 927348044, 927348042, 927348040, 927348038, 927348036, 927348034, 927348032, 927348030, 927348028, 927348026, 927348024, 927348022, 927348020, 927348018, 927348016, 927348014, 927348012, 927348010, 927348008, 927348006, 927348004, 927348002, 927348000, 927347998, 927347996, 927347994, 927347992, 927347990, 927347988, 927347986, 927347984, 927347982, 927347980, 927347978, 927347976", "bioproject_ids": null, "sra_ids": null}, {"year": 2016, "pmid": "28484175", "author": "Miyazawa T", "n_authors": 3, "title": "[RD-114 virus story: from RNA rumor virus to a useful viral tool for elucidating the world cats' journey].", "abstract": "RD-114 virus is a feline endogenous retrovirus (ERV) isolated from human rhabdomyosarcoma in 1971 and classified as endogenous gammaretrovirus in domestic cats (Felis catus). Based on the previous reports in 70's, it has been considered that a horizontal, infectious event occurred to transfer the virus from ancient baboon species to ancient cat species, whereupon it became endogenous in the cat species about several million years ago in Mediterranean Basin. Although it has been believed that all domestic cats harbor infectious RD-114 provirus in their genome, we revealed that cats do not have infectious RD-114 viral loci, but infectious RD-114 virus is resurrected by recombination between uninfectious RD-114 virus-related ERVs [here we designated them as RD-114-related sequences (RDRSs)]. Further, we also revealed the RDRSs which would potentially be resurrected as RD-114 virus (here we refer to them as ''new'' RDRSs) had entered the genome of the domestic cat after domestication of the cat around 10 thousand years ago. The fractions and positions of RDRSs in the cat genome differed in Western and Eastern cat populations and cat breeds. Our study revealed that RDRS would be a useful tool for elucidating the world travel routes of domestic cats after domestication.", "journal": "Uirusu", "doi": "10.2222/jsv.66.21", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2016, "pmid": "26559384", "author": "Jinks MR", "n_authors": 3, "title": "Causes of endogenous uveitis in cats presented to referral clinics in North Carolina.", "abstract": "To investigate the causes of endogenous uveitis in cats presenting to referral ophthalmology clinics in North Carolina. Medical records of cats diagnosed with endogenous uveitis at North Carolina State University's College of Veterinary Medicine (NCSU-CVM) or Animal Eye Care Associates of Cary, NC between 2003 and 2015 were reviewed. Inclusion criteria were cats that had complete diagnostic workups, including clinical, clinicopathological, serological, and histopathological data, as well as imaging modalities. Serology was consistently completed for feline leukemia virus (FeLV), feline immunodeficiency virus (FIV), feline coronavirus (FCoV), Toxoplasma gondii, and Bartonella spp. One hundred and twenty cats met the inclusion criteria. Seroprevalence of FeLV (2.7%), FIV (7.3%), FCoV (34.7%), T. gondii (23.7%), and Bartonella spp. (43.2%) was observed, with a combined seroprevalence of 59.2%. Nineteen cats (15.8%) were diagnosed with feline infectious peritonitis (FIP) based on clinical, hematological, serological, histopathological, and necropsy findings. The average age of all cases was 7.62 years, while the average age of cats diagnosed with FIP was 1.82 years. Neoplasia was diagnosed in six cats (5.0%). No underlying etiology was found in 49 cats (40.8%). Both idiopathic and neoplastic causes of uveitis were less prevalent than previously reported in studies, while seropositivity was higher than previously reported for the study area. This may be due to improved diagnostic capabilities or that cats with infectious disease were more likely to be referred. Because of the high prevalence of FIP, young cats with uveitis should be evaluated for hyperglobulinemia and FCoV serology should be performed as minimal diagnostics.", "journal": "Veterinary ophthalmology", "doi": "10.1111/vop.12324", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2017, "pmid": "29149857", "author": "Filoni C", "n_authors": 7, "title": "Putative progressive and abortive feline leukemia virus infection outcomes in captive jaguarundis (Puma yagouaroundi).", "abstract": "Feline leukemia virus (FeLV) is an exogenous gammaretrovirus of domestic cats (Felis catus) and some wild felids. The outcomes of FeLV infection in domestic cats vary according to host susceptibility, virus strain, and infectious challenge dose. Jaguarundis (Puma yagouaroundi) are small wild felids from South and Central America. We previously reported on FeLV infections in jaguarundis. We hypothesized here that the outcomes of FeLV infection in P. yagouaroundi mimic those observed in domestic cats. The aim of this study was to investigate the population of jaguarundis at Fundação Parque Zoológico de São Paulo for natural FeLV infection and resulting outcomes. We investigated the jaguarundis using serological and molecular methods and monitored them for FeLV-related diseases for 5 years. We retrieved relevant biological and clinical information for the entire population of 23 jaguarundis held at zoo. Post-mortem findings from necropsies were recorded and histopathological and immunohistopathological analyses were performed. Sequencing and phylogenetic analyses were performed for FeLV-positive samples. For sample prevalence, 95% confidence intervals (CI) were calculated. Fisher's exact test was used to compare frequencies between infected and uninfected animals. P-values <0.05 were considered significant. In total, we detected evidence of FeLV exposure in four out of 23 animals (17%; 95% CI 5-39%). No endogenous FeLV (enFeLV) sequences were detected. An intestinal B-cell lymphoma in one jaguarundi was not associated with FeLV. Two jaguarundis presented FeLV test results consistent with an abortive FeLV infection with seroconversion, and two other jaguarundis had results consistent with a progressive infection and potentially FeLV-associated clinical disorders and post-mortem changes. Phylogenetic analysis of env revealed the presence of FeLV-A, a common origin of the virus in both animals (100% identity) and the closest similarity to FeLV-FAIDS and FeLV-3281 (98.4% identity), originally isolated from cats in the USA. We found evidence of progressive and abortive FeLV infection outcomes in jaguarundis, and domestic cats were probably the source of infection in these jaguarundis.", "journal": "Virology journal", "doi": "10.1186/s12985-017-0889-z", "deposited_data": "Sim", "nuccore_ids": "881841304", "bioproject_ids": null, "sra_ids": null}, {"year": 2017, "pmid": "28768854", "author": "Kawasaki J", "n_authors": 5, "title": "Presence of a Shared 5'-Leader Sequence in Ancestral Human and Mammalian Retroviruses and Its Transduction into Feline Leukemia Virus.", "abstract": "Recombination events induce significant genetic changes, and this process can result in virus genetic diversity or in the generation of novel pathogenicity. We discovered a new recombinant feline leukemia virus (FeLV) ", "journal": "Journal of virology", "doi": "10.1128/JVI.00829-17", "deposited_data": "Sim", "nuccore_ids": "1227954422, 1227954421, 1227954420, 1227954419, 1227954418, 1227954417, 1227954416, 1227954415, 1227954414, 1227954413, 1227954412, 1227954411, 1227954338, 1227954337, 1227954336, 1227954335, 1227954334, 1227954333, 1227954332, 1227954331, 1227954330, 1227954329, 1227954328, 1227954327, 1227954326, 1227954325, 1227954324, 1227954323, 1227954322, 1227954321, 1227954320, 1227954319, 1227954318, 1227954317, 1227954316, 1227954315, 1227954314, 2130996210, 2130949117", "bioproject_ids": null, "sra_ids": null}, {"year": 2018, "pmid": "29976676", "author": "Powers JA", "n_authors": 9, "title": "Feline Leukemia Virus (FeLV) Disease Outcomes in a Domestic Cat Breeding Colony: Relationship to Endogenous FeLV and Other Chronic Viral Infections.", "abstract": "Exogenous feline leukemia virus (FeLV) is a feline gammaretrovirus that results in a variety of disease outcomes. Endogenous FeLV (enFeLV) is a replication-defective provirus found in species belonging to the ", "journal": "Journal of virology", "doi": "10.1128/JVI.00649-18", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2018, "pmid": "29642384", "author": "Kawasaki J", "n_authors": 2, "title": "Tracking the Continuous Evolutionary Processes of an Endogenous Retrovirus of the Domestic Cat: ERV-DC.", "abstract": "An endogenous retrovirus (ERV) is a remnant of an ancient retroviral infection in the host genome. Although most ERVs have lost their viral productivity, a few ERVs retain their replication capacity. In addition, partially inactivated ERVs can present a potential risk to the host via their encoded virulence factors or the generation of novel viruses by viral recombination. ERVs can also eventually acquire a biological function, and this ability has been a driving force of host evolution. Therefore, the presence of an ERV can be harmful or beneficial to the host. Various reports about paleovirology have revealed each event in ERV evolution, but the continuous processes of ERV evolution over millions of years are mainly unknown. A unique ERV family, ERV-DC, is present in the domestic cat (", "journal": "Viruses", "doi": "10.3390/v10040179", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2018, "pmid": "29320424", "author": "Chiu ES", "n_authors": 3, "title": "A Retrospective Examination of Feline Leukemia Subgroup Characterization: Viral Interference Assays to Deep Sequencing.", "abstract": "Feline leukemia virus (FeLV) was the first feline retrovirus discovered, and is associated with multiple fatal disease syndromes in cats, including lymphoma. The original research conducted on FeLV employed classical virological techniques. As methods have evolved to allow FeLV genetic characterization, investigators have continued to unravel the molecular pathology associated with this fascinating agent. In this review, we discuss how FeLV classification, transmission, and disease-inducing potential have been defined sequentially by viral interference assays, Sanger sequencing, PCR, and next-generation sequencing. In particular, we highlight the influences of endogenous FeLV and host genetics that represent FeLV research opportunities on the near horizon.", "journal": "Viruses", "doi": "10.3390/v10010029", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2019, "pmid": "31534037", "author": "Ngo MH", "n_authors": 9, "title": "Tracking the Fate of Endogenous Retrovirus Segregation in Wild and Domestic Cats.", "abstract": "Endogenous retroviruses (ERVs) of domestic cats (ERV-DCs) are one of the youngest feline ERV groups in domestic cats (", "journal": "Journal of virology", "doi": "10.1128/JVI.01324-19", "deposited_data": "Sim", "nuccore_ids": "1737725642, 1737725641, 1737725640, 1737725639, 1737725638, 1737725637, 1737725636, 1737725635, 1737725634, 1737725633, 1737725632, 1737725631", "bioproject_ids": null, "sra_ids": null}, {"year": 2019, "pmid": "30996094", "author": "Miyake A", "n_authors": 8, "title": "Reduced Folate Carrier: an Entry Receptor for a Novel Feline Leukemia Virus Variant.", "abstract": "Feline leukemia virus (FeLV) is horizontally transmitted among cats and causes a variety of hematopoietic disorders. Five subgroups of FeLV, A to D and T, each with distinct receptor usages, have been described. Recently, we identified a new FeLV Env (TG35-2) gene from a pseudotyped virus that does not belong to any known subgroup. FeLV-A is the primary virus from which other subgroups have emerged via mutation or recombination of the subgroup A ", "journal": "Journal of virology", "doi": "10.1128/JVI.00269-19", "deposited_data": "Sim", "nuccore_ids": "2462583176, 2462583174, 2462583172, 2462583170, 2462583168, 2462583166, 2462583164, 2462583162, 2462583160, 2462583158, 2462583156, 2462583154, 2462583152, 2462583150, 2462583148, 2462583146, 2462583144, 2462583142, 2462583140, 2462499610, 2462499608, 2462499606, 2462499604, 2462499602, 2462499600, 2462499598, 2462499596, 2462499594, 2462499592, 2462499590, 2462499588, 2462499586, 2462499584, 2462499582, 2462499580, 2462499578, 2462499576, 2462499574, 2217338142, 2217338140, 2217338138, 2217338136, 2217338135, 2217338133, 2217338131, 2217338129, 2217338128, 2217338126, 2217338125, 2217338124, 2217338122, 2217338120, 2217338118, 2217338116, 2217338115, 2217338113, 2217338112, 1890343338, 1890268074, 1676319583, 1675172771, 1675133521, 1519243035, 34823294", "bioproject_ids": null, "sra_ids": null}, {"year": 2019, "pmid": "30941311", "author": "Destefanis F", "n_authors": 4, "title": "Investigating the Connection Between Endogenous Heme Accumulation and COX2 Activity in Cancer Cells.", "abstract": "Heme, an iron-containing porphyrin, is fundamental for a variety of functions in cell homeostasis. Nevertheless, recent data indicate that dysregulation of heme metabolism might promote tumorigenesis. The intracellular heme pool is finely regulated through the control of heme synthesis, degradation, incorporation into hemoproteins and trafficking across membranes. All these processes might be potentially targeted to alter endogenous heme content in order to counteract cancer growth. Nevertheless, these putative therapeutic interventions have to take into account the possibility of undesired side effects, such as the over-activation of heme-dependent enzymes involved in cancer. Among them, cyclooxygenase-2 is a prostaglandin-producing hemoprotein, induced during inflammation and in different types of tumor, particularly in colorectal cancer. The aim of this study was to evaluate whether modulation of endogenous heme may affect cyclooxygenase-2 expression and activity, taking advantage of two different approaches able to alter heme levels: the silencing of the heme exporter Feline Leukemia Virus subgroup C receptor 1 and the induction of heme synthesis by 5-aminolevulinic acid administration. Our data demonstrate that the down-regulation of the heme exporter in colorectal cancer cells does not affect cyclooxygenase-2 expression and activity. Conversely, 5-aminolevulinic acid administration results in decreased cyclooxygenase-2 expression. However, the overall cyclooxygenase-2 enzymatic activity is maintained. The present work sheds light on the complex modulation of cyclooxygenase-2 by endogenous heme and support the idea that targeting heme metabolism could be a valuable therapeutic option against cancer.", "journal": "Frontiers in oncology", "doi": "10.3389/fonc.2019.00162", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2020, "pmid": "32817213", "author": "Chiu ES", "n_authors": 2, "title": "Presence of Endogenous Viral Elements Negatively Correlates with Feline Leukemia Virus Susceptibility in Puma and Domestic Cat Cells.", "abstract": "While feline leukemia virus (FeLV) has been shown to infect felid species other than the endemic domestic cat host, differences in FeLV susceptibility among species has not been evaluated. Previous reports have noted a negative correlation between endogenous FeLV (enFeLV) copy number and exogenous FeLV (exFeLV) infection outcomes in domestic cats. Since felids outside the genus ", "journal": "Journal of virology", "doi": "10.1128/JVI.01274-20", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2020, "pmid": "31683165", "author": "Chiu ES", "n_authors": 4, "title": "A novel test for determination of wild felid-domestic cat hybridization.", "abstract": "In October 2018, Colorado Parks and Wildlife seized an animal believed to be an illegally possessed bobcat. The owner claimed the animal was a bobcat/domestic cat hybrid, exempted from license requirements. Burden of proof lay with CPW to determine the lineage of the animal. Commercial microsatellite arrays and DNA barcoding have not been developed for identification of bobcat/domestic cat hybrids, and limited time and resources prevented development of such tests for this application. Instead, we targeted endogenous feline leukemia virus (enFeLV) to quickly and inexpensively demonstrate the absence of domestic cat DNA in the contested animal. Using this assay, we were able to confirm that the contested animal lacked enFeLV, and therefore was not a domestic cat hybrid.", "journal": "Forensic science international. Genetics", "doi": "10.1016/j.fsigen.2019.102160", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2021, "pmid": "34944329", "author": "Denner J", "n_authors": 1, "title": "Vaccination against the Koala Retrovirus (KoRV): Problems and Strategies.", "abstract": "The koala retrovirus (KoRV) is spreading in the koala population from the north to the south of Australia and is also in the process of endogenization into the koala genome. Virus infection is associated with tumorigenesis and immunodeficiency and is contributing to the decline of the animal population. Antibody production is an excellent marker of retrovirus infection; however, animals carrying endogenous KoRV are tolerant. Therefore, the therapeutic immunization of animals carrying endogenous KoRV seems to be ineffective. Using the recombinant transmembrane (TM) envelope protein of the KoRV, we immunized goats, rats and mice, obtaining in all cases neutralizing antibodies which recognize epitopes in the fusion peptide proximal region (FPPR), and in the membrane-proximal external region (MPER). Immunizing several animal species with the corresponding TM envelope protein of the closely related porcine endogenous retrovirus (PERV), as well as the feline leukemia virus (FeLV), we also induced neutralizing antibodies with similar epitopes. Immunizing with the TM envelope protein in addition to the surface envelope proteins of all three viruses resulted in higher titers of neutralizing antibodies. Immunizing KoRV-negative koalas with our vaccine (which is composed of both envelope proteins) may protect these animals from infection, and these may be the starting points of a virus-free population.", "journal": "Animals : an open access journal from MDPI", "doi": "10.3390/ani11123555", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2021, "pmid": "34495702", "author": "Chiu ES", "n_authors": 3, "title": "Endogenous Feline Leukemia Virus (FeLV) siRNA Transcription May Interfere with Exogenous FeLV Infection.", "abstract": "Endogenous retroviruses (ERVs) are increasingly recognized for biological impacts on host cell function and susceptibility to infectious agents, particularly in relation to interactions with exogenous retroviral progenitors (XRVs). ERVs can simultaneously promote and restrict XRV infections using mechanisms that are virus and host specific. The majority of endogenous-exogenous retroviral interactions have been evaluated in experimental mouse or chicken systems, which are limited in their ability to extend findings to naturally infected outbred animals. Feline leukemia virus (FeLV) has a relatively well-characterized endogenous retrovirus with a coexisting virulent exogenous counterpart and is endemic worldwide in domestic cats. We have previously documented an association between endogenous FeLV (enFeLV) long terminal repeat (LTR) copy number and abrogated exogenous FeLV in naturally infected cats and experimental infections in tissue culture. Analyses described here examine limited FeLV replication in experimentally infected peripheral blood mononuclear cells, which correlates with higher enFeLV transcripts in these cells compared to fibroblasts. We further examine NCBI Sequence Read Archive RNA transcripts to evaluate enFeLV transcripts and RNA interference (RNAi) precursors. We find that lymphoid-derived tissues, which are experimentally less permissive to exogenous FeLV infection, transcribe higher levels of enFeLV under basal conditions. Transcription of enFeLV-LTR segments is significantly greater than that of other enFeLV genes. We documented transcription of a 21-nucleotide (nt) microRNA (miRNA) just 3' to the enFeLV 5'-LTR in the feline miRNAome of all data sets evaluated (", "journal": "Journal of virology", "doi": "10.1128/JVI.00070-21", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2021, "pmid": "34232703", "author": "Erbeck K", "n_authors": 6, "title": "Feline Leukemia Virus (FeLV) Endogenous and Exogenous Recombination Events Result in Multiple FeLV-B Subtypes during Natural Infection.", "abstract": "Feline leukemia virus (FeLV) is associated with a range of clinical signs in felid species. Differences in disease processes are closely related to genetic variation in the envelope (", "journal": "Journal of virology", "doi": "10.1128/JVI.00353-21", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2021, "pmid": "34229197", "author": "Muz D", "n_authors": 13, "title": "The molecular and serological investigation of Feline immunodeficiency virus and Feline leukemia virus in stray cats of Western Turkey.", "abstract": "This study aimed to investigate the Feline immunodeficiency virus (FIV) / Feline leukemia virus (FeLV) infection prevalence among looking healthy stray cats in Western Turkey by serologic and molecular-based tests. A total of 1008 blood samples from the stray cats were used in this study. All samples were tested for FIV antibodies / proviral DNA and FeLV antibodies / antigens / proviral DNA. The genetic characterization and phylogenetic analysis of FeLV and FIV were carried out in this study. These cats also tested for Leishmaniasis and Toxoplasmosis previously. FIV Ab and proviral DNA detected in 25.2 % and 25.5 % of samples, respectively. FeLV Ab, Ag, proviral DNA positivity was in 45.2 %, in 3.3 %, in 69.7 %, respectively. The molecular detection and phylogenetic analysis of the current FeLV pol gene and FIV gag gene performed. The molecular characterization for the pol gene of FeLV (enFeLV and exFeLV) among Turkey's cat population was reported for the first time. The exFeLV pol sequences closer to the FeLV-A genotype, and the enFeLV pol sequences overlapped with other enFeLV. The current FIV gag sequences were clustered within the subtypes A, B, and C. The findings revealed FeLV subtype A and FIV subtype-A, subtype-B, subtype-C circulate among Turkish stray cats. Single and multiple co-infection positivity was found higher compared to previous reports.", "journal": "Comparative immunology, microbiology and infectious diseases", "doi": "10.1016/j.cimid.2021.101688", "deposited_data": "Sim", "nuccore_ids": "2069681559, 2069681557, 2069681555, 2069681553, 2069681551, 2069681549, 2067168707, 2067168705, 2067168694, 1534889306, 1534889305, 1534889304, 1534889303, 1534889302, 1534889301, 1534889300, 1534889299, 1534889298, 1534889297, 1534889296, 1534889295, 1534889294, 1534889293, 1534889292", "bioproject_ids": null, "sra_ids": null}, {"year": 2021, "pmid": "33290087", "author": "Chiu ES", "n_authors": 2, "title": "Endogenous Retroviruses Drive Resistance and Promotion of Exogenous Retroviral Homologs.", "abstract": "Endogenous retroviruses (ERVs) serve as markers of ancient viral infections and provide invaluable insight into host and viral evolution. ERVs have been exapted to assist in performing basic biological functions, including placentation, immune modulation, and oncogenesis. A subset of ERVs share high nucleotide similarity to circulating horizontally transmitted exogenous retrovirus (XRV) progenitors. In these cases, ERV-XRV interactions have been documented and include (", "journal": "Annual review of animal biosciences", "doi": "10.1146/annurev-animal-050620-101416", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2022, "pmid": "36534205", "author": "Acevedo-Jiménez GE", "n_authors": 5, "title": "Detection and genetic characterization of feline retroviruses in domestic cats with different clinical signs and hematological alterations.", "abstract": "Feline leukemia virus (FeLV) and feline immunodeficiency virus (FIV) are globally distributed retroviruses that infect domestic cats and cause various syndromes that can lead to death. The aim of this study was to detect and genotype feline retroviruses in Mexican domestic cats. We used PCR assays to identify proviral DNA and viral RNA in 50 domestic cats with different clinical signs and hematological alterations. Endogenous FeLV (enFeLV) was identified in the genomic DNA of all cats in the study, and we detected transcripts of the LTR region of enFeLV in 48 individuals. Exogenous FeLV (exFeLV) was found in 13 cats. Furthermore, we detected FIV proviral DNA in 10 cats. The enFeLV sequences were shown to be the most variable, while the exFeLV sequences were highly conserved and related to previously reported subgroup A sequences. Sequencing of the FIV gag gene revealed the presence of subtype B in the infected cats.", "journal": "Archives of virology", "doi": "10.1007/s00705-022-05627-z", "deposited_data": "Sim", "nuccore_ids": "2281570017, 2281570015, 2281570013, 2281570011, 2281570009, 2281570007, 2281570005, 2281570003, 2281570001, 2281569999, 2281569998, 2281569997, 2281569996, 2281569995, 2281569994, 2281569993, 2281569992, 2281569991, 2281569990, 2281569989, 2281569988, 2281569987, 2281569986, 2281569985, 2281569984, 2281569983, 2281569982, 2281569981, 2281569980, 2281569979, 2281569978, 2281569977, 2281569976, 2281569975, 2281569974, 2281569973, 2281569972, 2281569971", "bioproject_ids": null, "sra_ids": null}, {"year": 2022, "pmid": "36374109", "author": "Petch RJ", "n_authors": 13, "title": "Feline Leukemia Virus Frequently Spills Over from Domestic Cats to North American Pumas.", "abstract": "Feline leukemia virus (FeLV) is a gammaretrovirus with horizontally transmitted and endogenous forms. Domestic cats are the primary reservoir species, but FeLV outbreaks in endangered Florida panthers and Iberian lynxes have resulted in mortalities. To assess prevalence and interspecific/intraspecific transmission, we conducted an extensive survey and phylogenetic analysis of FeLV infection in free-ranging pumas (", "journal": "Journal of virology", "doi": "10.1128/jvi.01201-22", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2022, "pmid": "35749360", "author": "Miyake A", "n_authors": 7, "title": "Convergent evolution of antiviral machinery derived from endogenous retrovirus truncated envelope genes in multiple species.", "abstract": "Host genetic resistance to viral infection controls the pathogenicity and epidemic dynamics of infectious diseases. Refrex-1 is a restriction factor against feline leukemia virus subgroup D (FeLV-D) and an endogenous retrovirus (ERV) in domestic cats (ERV-DC). Refrex-1 is encoded by a subset of ERV-DC loci with truncated envelope genes and secreted from cells as a soluble protein. Here, we identified the copper transporter CTR1 as the entry receptor for FeLV-D and genotype I ERV-DCs. We also identified CTR1 as a receptor for primate ERVs from crab-eating macaques and rhesus macaques, which were found in a search of intact envelope genes capable of forming infectious viruses. Refrex-1 counteracted infection by FeLV-D and ERV-DCs via competition for the entry receptor CTR1; the antiviral effects extended to primate ERVs with CTR1-dependent entry. Furthermore, truncated ERV envelope genes found in chimpanzee, bonobo, gorilla, crab-eating macaque, and rhesus macaque genomes could also block infection by feline and primate retroviruses. Genetic analyses showed that these ERV envelope genes were acquired in a species- or genus-specific manner during host evolution. These results indicated that soluble envelope proteins could suppress retroviral infection across species boundaries, suggesting that they function to control retroviral spread. Our findings revealed that several mammalian species acquired antiviral machinery from various ancient retroviruses, leading to convergent evolution for host defense.", "journal": "Proceedings of the National Academy of Sciences of the United States of America", "doi": "10.1073/pnas.2114441119", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2022, "pmid": "35652657", "author": "Tury S", "n_authors": 6, "title": "Identification of Copper Transporter 1 as a Receptor for Feline Endogenous Retrovirus ERV-DC14.", "abstract": "Vertebrates harbor hundreds of endogenous retroviral (ERV) sequences in their genomes, which are considered signs of past infections that occurred during evolution. On rare occasions, ERV genes like ", "journal": "Journal of virology", "doi": "10.1128/jvi.00229-22", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2022, "pmid": "35319227", "author": "Hötzel I", "n_authors": 1, "title": "Deep-Time Structural Evolution of Retroviral and Filoviral Surface Envelope Proteins.", "abstract": "The retroviral surface envelope protein subunit (SU) mediates receptor binding and triggers membrane fusion by the transmembrane (TM) subunit. SU evolves rapidly under strong selective conditions, resulting in seemingly unrelated SU structures in highly divergent retroviruses. Structural modeling of the SUs of several retroviruses and related endogenous retroviral elements with AlphaFold 2 identifies a TM-proximal SU β-sandwich structure that has been conserved in the orthoretroviruses for at least 110 million years. The SU of orthoretroviruses diversified by the differential expansion of the β-sandwich core to form domains involved in virus-host interactions. The β-sandwich domain is also conserved in the SU equivalent GP", "journal": "Journal of virology", "doi": "10.1128/jvi.00063-22", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2022, "pmid": "35215842", "author": "Cano-Ortiz L", "n_authors": 5, "title": "Could Phylogenetic Analysis Be Used for Feline Leukemia Virus (FeLV) Classification?", "abstract": "The surface envelope (SU) protein determines the cell tropism and consequently the pathogenesis of the feline leukemia virus (FeLV) in felids. Recombination of exogenous FeLV (exFeLV) with endogenous retroviruses (enFeLV) allows the emergence of more pathogenic variants. Currently, phenotypic testing through interference assays is the only method to distinguish among subgroups-namely, FeLV-A, -B, -C, -E, and -T. This study proposes a new method for FeLV classification based on molecular analysis of the ", "journal": "Viruses", "doi": "10.3390/v14020249", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2022, "pmid": "34954236", "author": "Cano-Ortiz L", "n_authors": 12, "title": "Feline Leukemia Virus-B Envelope Together With its GlycoGag and Human Immunodeficiency Virus-1 Nef Mediate Resistance to Feline SERINC5.", "abstract": "Human SERINC5 (SER5) protein is a recently described restriction factor against human immunodeficiency virus-1 (HIV-1), which is antagonized by HIV-1 Nef protein. Other retroviral accessory proteins such as the glycosylated Gag (glycoGag) from the murine leukemia virus (MLV) can also antagonize SER5. In addition, some viruses escape SER5 restriction by expressing a SER5-insensitive envelope (Env) glycoprotein. Here, we studied the activity of human and feline SER5 on HIV-1 and on the two pathogenic retroviruses in cats, feline immunodeficiency virus (FIV) and feline leukemia virus (FeLV). HIV-1 in absence of Nef is restricted by SER5 from domestic cats and protected by its Nef protein. The sensitivity of feline retroviruses FIV and FeLV to human and feline SER5 is considerably different: FIV is sensitive to feline and human SER5 and lacks an obvious mechanism to counteract SER5 activity, while FeLV is relatively resistant to SER5 inhibition. We speculated that similar to MLV, FeLV-A or FeLV-B express glycoGag proteins and investigated their function against human and feline SER5 in wild type and envelope deficient virus variants. We found that the endogenous FeLV recombinant virus, FeLV-B but not wild type exogenous FeLV-A envelope mediates a strong resistance against human and feline SER5. GlycoGag has an additional but moderate role to enhance viral infectivity in the presence of SER5 that seems to be dependent on the FeLV envelope. These findings may explain, why in vivo FeLV-B has a selective advantage and causes higher FeLV levels in infected cats compared to infections of FeLV-A only.", "journal": "Journal of molecular biology", "doi": "10.1016/j.jmb.2021.167421", "deposited_data": "Sim", "nuccore_ids": "2462601969, 2462601967, 2462601965, 2217355471, 2217355469, 2217355468, 1701216772, 1700660365, 1675150712, 1675115504, 1519241846", "bioproject_ids": null, "sra_ids": null}, {"year": 2022, "pmid": "34787790", "author": "Shimode S", "n_authors": 2, "title": "Characterization of DNA methylation and promoter activity of long terminal repeat elements of feline endogenous retrovirus RDRS C2a.", "abstract": "Endogenous retroviruses (ERVs) are genomic elements derived from retroviral infections in ancestral germ lines. Most ERVs are inactivated by genetic or epigenetic mechanisms, such as DNA methylation. RD-114-virus-related sequence (RDRS) C2a is a feline endogenous retrovirus present in all domestic cats; however, its expression and function are not clearly known. DNA methylation at CpG dinucleotides is a hallmark of silenced ERVs. This study aimed to investigate whether long terminal repeats (LTRs) of RDRS C2a function as a gene regulatory region. The DNA methylation status of RDRS C2a was examined by bisulfite sequencing, and CpG sites in 5' LTR of RDRS C2a were found hypomethylated, whereas those in 3' LTR were hypermethylated in feline cells. Several transcription factor-binding sites were identified in LTRs of RDRS C2a. Luciferase assay suggested that 5' LTR of RDRS C2a exhibited strong transcriptional activity, which was suppressed by in vitro DNA methylation. The study indicates that 5' LTR of RDRS C2a possibly functions as a promoter for itself or neighboring genes.", "journal": "Virus genes", "doi": "10.1007/s11262-021-01878-1", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2023, "pmid": "38022580", "author": "Ciulean IS", "n_authors": 10, "title": "CD44v6 specific CAR-NK cells for targeted immunotherapy of head and neck squamous cell carcinoma.", "abstract": "Head and neck squamous cell carcinoma (HNSCC) is a major challenge for current therapies. CAR-T cells have shown promising results in blood cancers, however, their effectiveness against solid tumors remains a hurdle. Recently, CD44v6-directed CAR-T cells demonstrated efficacy in controlling tumor growth in multiple myeloma and solid tumors such as HNSCC, lung and ovarian adenocarcinomas. Apart from CAR-T cells, CAR-NK cells offer a safe and allogenic alternative to autologous CAR-T cell therapy. In this paper, we investigated the capacity of CAR-NK cells redirected against CD44v6 to execute cytotoxicity against HNSCC. Anti-CD44v6 CAR-NK cells were generated from healthy donor peripheral blood-derived NK cells using gamma retroviral vectors (gRVs). The NK cell transduction was optimized by exploring virus envelope proteins derived from the baboon endogenous virus envelope (BaEV), feline leukemia virus (FeLV, termed RD114-TR) and gibbon ape leukemia virus (GaLV), respectively. BaEV pseudotyped gRVs induced the highest transduction rate compared to RD114-TR and GaLV envelopes as measured by EGFP and surface CAR expression of transduced NK cells. CAR-NK cells showed a two- to threefold increase in killing efficacy against various HNSCC cell lines compared to unmodified, cytokine-expanded primary NK cells. Anti-CD44v6 CAR-NK cells were effective in eliminating tumor cell lines with high and low CD44v6 expression levels. Overall, the improved cytotoxicity of CAR-NK cells holds promise for a therapeutic option for the treatment of HNSCC. However, further preclinical trials are necessary to test ", "journal": "Frontiers in immunology", "doi": "10.3389/fimmu.2023.1290488", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2023, "pmid": "37864512", "author": "Awazu A", "n_authors": 4, "title": "Possibilities of skin coat color-dependent risks and risk factors of squamous cell carcinoma and deafness of domestic cats inferred via RNA-seq data.", "abstract": "The transcriptome data of skin cells from domestic cats with brown, orange, and white coats were analyzed using a public database to investigate the possible relationship between coat color-related gene expression and squamous cell carcinoma risk, as well as the mechanism of deafness in white cats. We found that the ratio of the expression level of genes suppressing squamous cell carcinoma to that of genes promoting squamous cell carcinoma might be considerably lower than the theoretical estimation in skin cells with orange and white coats in white-spotted cat. We also found the possibility of the frequent production of KIT lacking the first exon (d1KIT) in skin cells with white coats, and d1KIT production exhibited a substantial negative correlation with the expression of SOX10, which is essential for melanocyte formation and adjustment of hearing function. Additionally, the production of d1KIT was expected to be due to the insulating activity of the feline endogenous retrovirus 1 (FERV1) LTR in the first intron of KIT by its CTCF binding sequence repeat. These results contribute to basic veterinary research to understand the relationship between cat skin coat and disease risk, as well as the underlying mechanism.", "journal": "Genes to cells : devoted to molecular & cellular mechanisms", "doi": "10.1111/gtc.13076", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2023, "pmid": "36947073", "author": "Gozashti L", "n_authors": 3, "title": "Transposable Element Interactions Shape the Ecology of the Deer Mouse Genome.", "abstract": "The genomic landscape of transposable elements (TEs) varies dramatically across species, with some TEs demonstrating greater success in colonizing particular lineages than others. In mammals, long interspersed nuclear element (LINE) retrotransposons are typically more common than any other TE. Here, we report an unusual genomic landscape of TEs in the deer mouse, Peromyscus maniculatus. In contrast to other previously examined mammals, long terminal repeat elements occupy more of the deer mouse genome than LINEs (11% and 10%, respectively). This pattern reflects a combination of relatively low LINE activity and a massive invasion of lineage-specific endogenous retroviruses (ERVs). Deer mouse ERVs exhibit diverse origins spanning the retroviral phylogeny suggesting they have been host to a wide range of exogenous retroviruses. Notably, we trace the origin of one ERV lineage, which arose ∼5-18 million years ago, to a close relative of feline leukemia virus, revealing inter-ordinal horizontal transmission. Several lineage-specific ERV subfamilies have very high copy numbers, with the top five most abundant accounting for ∼2% of the genome. We also observe a massive amplification of Kruppel-associated box domain-containing zinc finger genes, which likely control ERV activity and whose expansion may have been facilitated by ectopic recombination between ERVs. Finally, we find evidence that ERVs directly impacted the evolutionary trajectory of LINEs by outcompeting them for genomic sites and frequently disrupting autonomous LINE copies. Together, our results illuminate the genomic ecology that shaped the unique deer mouse TE landscape, shedding light on the evolutionary processes that give rise to variation in mammalian genome structure.", "journal": "Molecular biology and evolution", "doi": "10.1093/molbev/msad069", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2023, "pmid": "36924831", "author": "Biezus G", "n_authors": 8, "title": "Phylogenetic identification of feline leukemia virus A and B in cats with progressive infection developing into lymphoma and leukemia.", "abstract": "To date, only a few studies have examined the impacts of feline leukemia virus (FeLV) subgroups on disease development in spontaneously infected cats. The present study identified FeLV-A and FeLV-B subgroups in cats with lymphoma and leukemia and explored the phylogenetic relationships of env sequences. Twenty-six cats with lymphoma (n=16) or leukemia (n=10) were selected. FeLV p27 antigen positivity was determined using ELISA, and proviral DNA in blood samples was detected using nested PCR. Positive animals in both tests were classified as cases of FeLV progressive infection and subjected to a second nested PCR for env amplification and subgroup determination. Six samples of FeLV-A and five samples of FeLV-B were sequenced using the Sanger method, and the results were used to build a phylogenetic tree and estimate evolutionary divergence. Among cats with lymphoma, 68.8% carried FeLV-AB and 31.2% FeLV-A. Among cats with leukemia, 70% carried FeLV-AB and 30% FeLV-A. Regarding cat characteristics, 50% were young, 30.8% young adults, and 19.2% adults; 88.5% were mixed-breed and 11.5% pure breed; and 42.3% were males and 57.7% were females. Among lymphomas, 62.5% were mediastinal, 31.3% multicentric, and 6.3% extranodal. Regarding histological classification, lymphoblastic and small non-cleaved-cell lymphomas were the most frequently detected. Among leukemia cases, 30% were acute lymphoid, 30% chronic myeloid, and 40% acute myeloid. Phylogenetic analysis showed that FeLV-A SC sequences were closely related to the Arena, Glasgow-1, and FeLV-FAIDS variants. Meanwhile, FeLV-B SC sequences were divergent from one another but similar to the endogenous FELV env gene (enFeLV). In conclusion, FeLV-AB is prevalent in cats with lymphoma and leukemia, highlighting the genetic diversity involved in the pathogenesis of these neoplasms in Brazil.", "journal": "Virus research", "doi": "10.1016/j.virusres.2023.199093", "deposited_data": "Sim", "nuccore_ids": "2462483771, 2462483770, 2462483768, 2462483766, 2462483764, 2462483762, 2462483760, 2462483758, 2462483756, 2459163109", "bioproject_ids": null, "sra_ids": null}, {"year": 2023, "pmid": "36178295", "author": "Canto-Valdés MC", "n_authors": 4, "title": "What role do endogenous retroviruses play in domestic cats infected with feline leukaemia virus?", "abstract": "Feline leukaemia virus (FeLV) is a retrovirus that infects domestic and wild cats around the world. FeLV infection is associated with the development of neoplasms, bone marrow disorders and immunosuppression. Viral subgroups arise from mutations in the FeLV genome or from recombination of FeLV with ancestral endogenous retroviruses in the cat genome. The retroviral endogenisation process has allowed generation of a diversity of endogenous viruses, both functional and defective. These elements may be part of the normal functioning of the feline genome and may also interact with FeLV to form recombinant FeLV subgroups, enhance pathogenicity of viral subgroups, or inhibit and/or regulate other retroviral infections. Recombination of the env gene occurs most frequently and appears to be the most significant in terms of both the quantity and diversification of pathogenic effects in the viral population, as well as affecting cell tropism and types of disease that occur in infected cats. This review focuses on available information regarding genetic diversity, pathogenesis and diagnosis of FeLV as a result of the interaction between endogenous and exogenous viruses.", "journal": "New Zealand veterinary journal", "doi": "10.1080/00480169.2022.2131648", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2024, "pmid": "39153451", "author": "Pramono D", "n_authors": 10, "title": "Endogenous retrovirus ERV-DC8 highly integrated in domestic cat populations is a replication-competent provirus.", "abstract": "Endogenous retroviruses (ERVs) are remnants of ancient retroviral infections in vertebrate genomes and are inherited by offspring. ERVs can produce pathogenic viruses through gene mutations or recombination. ERVs in domestic cats (ERV-DCs) generate feline leukemia virus subgroup D (FeLV-D) through viral recombination. Herein, we characterized the locus ERV-DC8, on chromosome B1, as an infectious replication-competent provirus. ERV-DC8 infected several cell lines, including human cells. Transmission electron microscopy of ERV-DC8 identified the viral release as a Gammaretrovirus. ERV-DC8 was identified as the FeLV-D viral interference group, with feline copper transporter 1 as its viral receptor. Insertional polymorphism analysis showed high ERV-DC8 integration in domestic cats. This study highlights the role, pathogenicity, and evolutionary relationships between ERVs and their hosts.", "journal": "Biochemical and biophysical research communications", "doi": "10.1016/j.bbrc.2024.150521", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2024, "pmid": "38440982", "author": "Pramono D", "n_authors": 9, "title": "FeLIX is a restriction factor for mammalian retrovirus infection.", "abstract": "Endogenous retroviruses (ERVs) are remnants of ancestral viral infections. Feline leukemia virus (FeLV) is an exogenous and endogenous retrovirus in domestic cats. It is classified into several subgroups (A, B, C, D, E, and T) based on viral receptor interference properties or receptor usage. ERV-derived molecules benefit animals, conferring resistance to infectious diseases. However, the soluble protein encoded by the defective envelope (", "journal": "Journal of virology", "doi": "10.1128/jvi.01771-23", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2024, "pmid": "38347535", "author": "Chiu ES", "n_authors": 6, "title": "Endogenous feline leukemia virus long terminal repeat integration site diversity is highly variable in related and unrelated domestic cats.", "abstract": "Endogenous retroviruses (ERV) are indicators of vertebrate evolutionary history and play important roles as homeostatic regulators. ERV long terminal repeat (LTR) elements may act as cis-activating promoters or trans-activating enhancer elements modifying gene transcription distant from LTR insertion sites. We previously documented that endogenous feline leukemia virus (FeLV)-LTR copy number variation in individual cats tracks inversely with susceptibility to virulent FeLV disease. To evaluate FeLV-LTR insertion characteristics, we assessed enFeLV-LTR integration site diversity in 20 cats from three genetically distinct populations using a baited linker-mediated PCR approach. We documented 765 individual integration sites unequally represented among individuals. Only three LTR integration sites were shared among all individuals, while 412 sites were unique to a single individual. When primary fibroblast cultures were challenged with exogenous FeLV, we found significantly increased expression of both exogenous and endogenous FeLV orthologs, supporting previous findings of potential exFeLV-enFeLV interactions; however, viral challenge did not elicit transcriptional changes in genes associated with the vast majority of integration sites. This study assesses FeLV-LTR integration sites in individual animals, providing unique transposome genotypes. Further, we document substantial individual variation in LTR integration site locations, even in a highly inbred population, and provide a framework for understanding potential endogenous retroviral element position influence on host gene transcription.", "journal": "Retrovirology", "doi": "10.1186/s12977-024-00635-0", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2024, "pmid": "38338028", "author": "Korkulu E", "n_authors": 7, "title": "Status Quo of Feline Leukaemia Virus Infection in Turkish Cats and Their Antigenic Prevalence.", "abstract": "Feline leukaemia virus (FeLV) is a member of the Gammaretrovirus genus, which has two genotypes in cats: endogenous (replication-defective provirus) and exogenous (replication-competent). In this study, 550 cats were examined, and 112 of them (20.36%) were found to have the endogenous FeLV (enFeLV) genotype. EnFeLV-positive animals were also tested for additional viral infections, and 48 cats (42.85%) were discovered to be co-infected with other viruses. According to co-infection data, these cats were infected with feline coronavirus (FCoV) (27/112, 24.1%), feline panleukopenia virus (FPV) (14/112, 12.5%), feline immunodeficiency virus (FIV) (0/112, 0%), and domestic cat hepadnavirus (DCH) (13/112, 11.6%). Their age, sex, breed, clinical state, lifestyle (in/outdoor), and immunization data against FeLV were also evaluated. In line with our results, the prevalence of enFeLV and co-infection with other pathogens in cats admitted to the clinic for various reasons were discussed. The majority of positive animals in terms of FeLV (94/112, 83.93%) had clinical findings. We emphasized that the FeLV-positive situation of cats should be taken into consideration by veterinarians when planning treatment and vaccination programs. Additionally, in this study, we questioned the group in which our enFeLVs were phylogenetically located. Therefore, we performed a phylogenetic analysis based on a comparison with global FeLV sequences obtained from the GenBank database. The sequenced positive samples were in the AGTT subgroup within Group-II.", "journal": "Animals : an open access journal from MDPI", "doi": "10.3390/ani14030385", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2024, "pmid": "38240589", "author": "Ngo MH", "n_authors": 17, "title": "Multiple recombination events between endogenous retroviral elements and feline leukemia virus.", "abstract": "Feline leukemia virus (FeLV) is an exogenous retrovirus that causes malignant hematopoietic disorders in domestic cats, and its virulence may be closely associated with viral sequences. FeLV is classified into several subgroups, including A, B, C, D, E, and T, based on viral receptor interference properties or receptor usage. However, the transmission manner and disease specificity of the recombinant viruses FeLV-D and FeLV-B remain unclear. The aim of this study was to understand recombination events between exogenous and endogenous retroviruses within a host and elucidate the emergence and transmission of recombinant viruses. We observed multiple recombination events involving endogenous retroviruses (ERVs) in FeLV from a family of domestic cats kept in one house; two of these cats (ON-T and ON-C) presented with lymphoma and leukemia, respectively. Clonal integration of FeLV-D was observed in the ON-T case, suggesting an association with FeLV-D pathogenesis. Notably, the receptor usage of FeLV-B observed in ON-T was mediated by feline Pit1 and feline Pit2, whereas only feline Pit1 was used in ON-C. Furthermore, XR-FeLV, a recombinant FeLV containing an unrelated sequence referred to the X-region, which is homologous to a portion of the 5'-leader sequence of ", "journal": "Journal of virology", "doi": "10.1128/jvi.01400-23", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2025, "pmid": "41392067", "author": "Stone NV", "n_authors": 10, "title": "Intra-host diversity of proviral FeLV and clinical outcomes.", "abstract": "Feline leukemia virus (FeLV) is a retrovirus associated with a variety of clinical conditions, including either regenerative or non-regenerative anemia. The high mutation rate of retroviruses promotes the formation of quasispecies — populations composed of multiple genetically related haplotypes — which drives the evolution of the viral population within a host and can impact on disease development. This study investigated the intra-host diversity of proviral FeLV and evaluated their impact on the hematological parameters in naturally infected cats. Twenty-seven blood samples from FeLV-positive cats were analyzed. Total DNA was extracted, and the complete env gene was amplified by PCR, followed by next-generation sequencing (NGS). Raw sequence data were quality-checked, trimmed, and aligned to the FeLV SU reference sequence. Quasispecies with frequencies above 5% were inferred using CliqueSNV v2.0.3, phylogenetic reconstruction was performed with IQ-TREE v1.6.12 and recombinant sequences were identified using SimPlot v3.5.1. A remarkable variability in quasispecies composition was observed among infected cats. While 13 animals (48.1%) harbored infections driven by a single haplotype, others (n = 14) exhibited a much more complex viral landscape, with five or more distinct haplotypes detected. In samples with greater viral diversity, quasispecies frequencies were more evenly distributed. In the phylogenetic reconstruction, most quasispecies sequences isolated from the same host clustered together in well-supported clades within the FeLV-A lineage. Notably, one exception was identified as a FeLV-A/enFeLV recombinant. Additionally, five other recombinant quasispecies were detected. Analysis of hematological parameters showed no significant correlations between the number of haplotypes and the presence of anemia (regenerative or non-regenerative). However, classifying animals by their lymphocyte values’ adherence to normal reference ranges revealed a statistically significant difference in the number of viral haplotypes detected between groups (p = 0.04). Additionally, a negative binomial regression indicated that life stage had a positive trend in its relationship with the number of proviral quasispecies (p = 0.0593), indirectly suggesting that a higher number of quasispecies tends to be observed in more advanced disease stages. Although not statistically significant, the result suggests a potential relationship that warrants further investigation. This study, therefore, indicates that the number of intra-host quasispecies can be influenced by both the duration of infection and alterations in the immune response in naturally FeLV-infected cats.", "journal": "Brazilian journal of microbiology : [publication of the Brazilian Society for Microbiology]", "doi": "10.1007/s42770-025-01815-6", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2025, "pmid": "40545979", "author": "Úsuga-Monroy C", "n_authors": 7, "title": "Prevalence, Recombination Events, and Risk Factors of FeLV Infection in Domestic Cats from Colombia.", "abstract": "Feline leukemia virus (FeLV) is one of the primary pathogens in domestic felines, causing significant immunosuppression, lymphomas, and even death. Various subtypes of this virus have been described, with FeLV-A being the least pathogenic and the most widely distributed subtype. Conversely, the recombination of FeLV-A with endogenous retroviral sequences has resulted in variant B, which is associated with the development of leukemias and lymphomas. FeLV transmission occurs primarily through grooming between individuals, facilitating its distribution and circulation. The aim of this study was to characterize subtype B and analyze risk factors associated with viral infection in a sample of felines from Colombia. To achieve this, blood samples were taken from the cephalic or jugular veins of 151 felines in four municipalities of Antioquia, and data on age, sex, and area of origin were collected. PCR was performed on a region of the pol gene (306 bp), and only FeLV-positive feline samples underwent a second PCR for the env gene (1400 bp). Only env-positive PCR products were sequenced, and phylogenetic and recombination analyses were performed. Logistic regression was used to calculate the odds ratios (OR) for each variable (age, sex, and area of origin). The overall FeLV positivity rate was 33.77%, with an association found between male sex and FeLV infection (OR = 2.23, p = 0.038), as well as between the area of origin and FeLV infection (OR = 0.22, p = 0.035). Of the total samples, only 11 (7.3%) amplified for FeLV-B, with seven samples from Buriticá and four from Medellín. The recombination analyses confirmed that all sequences belonged to the FeLV-B subtype and were unique recombinants. The molecular presence of the virus in the study area demonstrates that the circulation of this retrovirus remains active. Additionally, the area of origin and male sex are risk factors for FeLV infection. Finally, an increase in FeLV positivity was observed, and while the B variants are generated de novo in each feline, it is crucial to continue health monitoring, especially in regions distant from major urban centers.", "journal": "Veterinaria italiana", "doi": "10.12834/VetIt.3641.31503.1", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2025, "pmid": "40155393", "author": "Chin PJ", "n_authors": 15, "title": "Virus detection by short read high throughput sequencing in a high virus low cellular background.", "abstract": "The safety of all biological products includes demonstrating the absence of adventitious viruses by testing various types of samples at different stages of the manufacturing process. Seven laboratories evaluated short-read high-throughput sequencing (HTS) for sensitivity and breadth of adventitious virus detection using viruses with distinct physicochemical and genome properties. These five viruses are currently designated as CBER NGS Virus Reagents and include: Epstein-Barr virus (EBV; or human herpes virus 4), feline leukemia virus (FeLV), respiratory syncytial virus (RSV), mammalian orthoreovirus type 1 (Reo1), and porcine circovirus type 1 (PCV1). To evaluate adventitious virus detection in a biological material with a high production virus titer and low cellular background, the 5 viruses were mixed and different copies of the viral genomes spiked into 1 - 5 × 10", "journal": "NPJ vaccines", "doi": "10.1038/s41541-025-01104-1", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2026, "pmid": "42288833", "author": "Castillo-Aliaga C", "n_authors": 6, "title": "Cross-species transmission of host adaptation of feline leukemia virus between domestic cats and the wild felid Leopardus guigna.", "abstract": "Feline leukemia virus (FeLV) is widespread in domestic cats and frequently spills over into wild felid populations, causing severe outbreaks in nondomestic felid populations. Domestic cats carry both endogenous FeLV (enFeLV) and exogenous variants of FeLV (exFeLV), which can recombine to generate novel variants with alternate receptor usage. In contrast, most nondomestic felids, including the guigna, do not harbor enFeLV. This study applied amplification of the FeLV envelope gene combined with Illumina sequencing to characterize FeLV envelope gene diversity and transmission dynamics in guignas (Leopardus guigna), a small wild felid native to Chile and Argentina. Seven polymerase chain reaction (PCR )amplicons from five free-ranging guignas were sequenced. Illumina sequencing was successfully conducted, and subsequent phylogenetic analysis indicated that the detected infections were most closely related to strains circulating in Chilean domestic cats. However, a distinct guigna-specific cluster with unique sequence variations was identified, suggesting that FeLV transmission also occurs among guignas independent of domestic cats. Phylogenetic analysis showed that all guigna sequences formed a Chile-specific FeLV clade, closely related to domestic cat viruses but clearly separated from international FeLV-A strains.", "journal": "Veterinary research", "doi": "10.1186/s13567-026-01770-6", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2026, "pmid": "42026075", "author": "Jeun M", "n_authors": 6, "title": "Discovery of a novel envelope protein derived from simian retrovirus 2 for pseudotyping retroviral vectors used for production of CAR immune cells.", "abstract": "In this study, we develop a simian retrovirus 2 pseudotyped retrovirus (SRV2 RV) for the generation of CAR-based immune cells. The SRV2 RV exhibits superior gene transduction efficiency in both T cells and NK cells compared to feline endogenous retrovirus (RD114) pseudotyped retrovirus (RD114 RV) or vesicular stomatitis virus glycoprotein (VSV-G) pseudotyped lentivirus (VSV-G LV). Among the various SRV pseudotypes tested, only the SRV2 RV successfully transduces genes into immune cells. Unlike the SRV2 RV, however, lentivirus pseudotyped with the SRV2 envelope glycoprotein (ENV) fails to mediate gene transduction into T cells. CAR-T and NK cells generated using SRV2 RV demonstrate substantial anticancer activity both in vitro and in preclinical models. In conclusion, our findings highlight the SRV2 RV as a highly effective platform for producing CAR-based immune cells.", "journal": "Nature communications", "doi": "10.1038/s41467-026-72024-4", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2026, "pmid": "42013235", "author": "Mouta R", "n_authors": 7, "title": "Evolutionary Dynamics of Endogenous Feline Leukemia Virus in the Felis Genus Through the Lens of Genomics.", "abstract": "Feline leukemia virus (Gammaretrovirus felleu) causes variable pathologies, partially modulated by its endogenous form (enFeLV). Although enFeLV is found in genomes of all species of the Felis genus, the limitations of transposable element sequencing have hindered a comprehensive characterization. In this study, we examined 17 felid genomes for enFeLV copies, confirming that enFeLV is restricted to the Felis genus. From the long-read genomes of Felis catus, Felis nigripes, and Felis chaus, we identified 73 solo LTRs, 64 copies with genic segments, and 4 atypical copies. These were annotated and characterized using recombination assessment, phylogenetic analysis, insertion dating, and Fisher's exact tests. All enFeLV copies shared a single origin, with insertions occurring within the last 3.5 million years, except for predicted recombinants. Copy distribution, dating, and the phylogenetic position of F. chaus copies reinforce the hypothesis of a recent introgression of enFeLV into this species. Furthermore, 41 copies exhibit identical LTR pairs and 14 retain intact open reading frames spanning the viral genome. Uneven evolutionary pressures across the enFeLV genome were evidenced by discrepancies between tree topologies of individual genes and the preferential loss of pol. We conclude that enFeLV has undergone a complex post-endogenization evolutionary history and urge additional studies of other endogenous retroviruses.", "journal": "Annals of the New York Academy of Sciences", "doi": "10.1111/nyas.70278", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}, {"year": 2026, "pmid": "41808988", "author": "Malekos E", "n_authors": 3, "title": "Integrative multiomics analysis and CRISPR screening identify functional noncanonical translation loci in the mouse immune system.", "abstract": "Ribosome profiling has revealed thousands of noncanonical translation events across mammalian genomes, yet functional characterization has overwhelmingly focused on proliferative fitness in cancer cell lines. Here, we present a comprehensive survey of noncanonical translation in the mouse immune system and its functional consequences in macrophages. By performing a unified Ribo-seq meta-analysis across 20 public mouse leukocyte datasets - spanning macrophages, dendritic cells, neutrophils, B cells, and T cells - we define a compendium of 22,276 noncanonical coding sequences (CDSs), including upstream ORFs (uORFs), downstream ORFs, and ORFs on noncoding RNAs and pseudogenes (ncORFs). Proteogenomic integration with reanalyzed mass spectrometry data prioritizes a high-confidence subset with detectable protein products, including pseudogene-encoded and lncRNA-encoded zinc finger proteins. To move beyond cataloging, we carried out two orthogonal CRISPR screens in immortalized bone marrow-derived macrophages: a fitness screen identifying noncanonical CDSs required for macrophage viability, and a TLR1/TLR2-NFκB reporter screen uncovering CDSs that modulate innate immune signaling. These screens nominate uORFs, several conserved between mouse and human, that exert phenotypic effects on par with their cognate coding sequences. We unexpectedly discovered a family of endogenous retroviral envelope-derived proteins translated in adult myeloid cells. Among these, SYNIR is a full-length syncytin-like membrane glycoprotein that positively regulates NFκB-responsive transcription, while SEMR is a secreted protein with structural homology to the feline leukemia virus accessory protein FeLIX that drives broad transcriptional remodeling of macrophage gene programs upon knockout. Updated single-cell RNA-seq annotations and an interactive UCSC Genome Browser session integrating Ribo-seq, proteomics, and CRISPR screen data are provided as community resources. Together, these findings expand the functional landscape of noncanonical translation in immunity and establish endogenous retroviral proteins as previously unrecognized regulators of macrophage biology.", "journal": "bioRxiv : the preprint server for biology", "doi": "10.64898/2026.02.23.707583", "deposited_data": "Nao", "nuccore_ids": null, "bioproject_ids": null, "sra_ids": null}]};
